  final parameter Modelica.Units.SI.MagneticPotentialDifference V_mPM = 2 / pi * sqrt(2) * (m / 2) * VsOpenCircuit / effectiveStatorTurns / (Lmd / effectiveStatorTurns ^ 2 * 2 * pi * fsNominal) "Equivalent excitation magnetic potential difference";
