modelica://Modelica.Magnetic/SymmetricPo:
Modelica.Magnetic: SymmetricPolyphaseWinding (model)

The symmetrical polyphase winding consists of a symmetrical winding  resistor , a  stray reluctance , a symmetrical  polyphase electromagnetic coupling and a  core loss model including heat port .    See also  
   QuasiStaticAnalogWinding ,   Magnetic.FundamentalWave.BasicMachines.Components.SinglePhaseWinding ,   Magnetic.FundamentalWave.BasicMachines.Components.SymmetricPolyphaseWinding

Code:
model SymmetricPolyphaseWinding "Symmetric winding model coupling electrical and magnetic domain"
  // Orientation changed
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.PositivePlug plug_p(final m = m) "Positive plug" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug plug_n(final m = m) "Negative plug" ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Interfaces.NegativeMagneticPort port_n "Negative complex magnetic port" ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Interfaces.PositiveMagneticPort port_p "Positive complex magnetic port" ;
  parameter Integer m = 3 "Number of phases" ;
  parameter Boolean useHeatPort = false "Enable / disable (=fixed temperatures) thermal port" ;
  // Resistor model
  parameter Modelica.Units.SI.Resistance RRef "Winding resistance per phase at TRef";
  parameter Modelica.Units.SI.Temperature TRef(start = 293.15) "Reference temperature of winding";
  parameter Modelica.Electrical.Machines.Thermal.LinearTemperatureCoefficient20 alpha20(start = 0) "Temperature coefficient of winding at 20 degC";
  final parameter Modelica.Units.SI.LinearTemperatureCoefficient alphaRef = Modelica.Electrical.Machines.Thermal.convertAlpha(alpha20, TRef, 293.15) "Temperature coefficient of winding at reference temperature";
  parameter Modelica.Units.SI.Temperature TOperational(start = 293.15) "Operational temperature of winding" ;
  parameter Modelica.Units.SI.Inductance Lsigma "Winding stray inductance per phase";
  parameter Real effectiveTurns = 1 "Effective number of turns per phase";
  parameter Modelica.Units.SI.Conductance GcRef "Electrical reference core loss reluctance";
  Modelica.Units.SI.ComplexVoltage v[m] = plug_p.pin.v - plug_n.pin.v "Complex voltage";
  Modelica.Units.SI.Voltage abs_v[m] = Modelica.ComplexMath.abs(v) "Magnitude of complex voltage";
  Modelica.Units.SI.Angle arg_v[m] = Modelica.ComplexMath.arg(v) "Argument of complex voltage";
  Modelica.Units.SI.ComplexCurrent i[m] = plug_p.pin.i "Complex current";
  Modelica.Units.SI.Current abs_i[m] = Modelica.ComplexMath.abs(i) "Magnitude of complex current";
  Modelica.Units.SI.Angle arg_i[m] = Modelica.ComplexMath.arg(i) "Argument of complex current";
  Modelica.Units.SI.ActivePower P[m] = array(Modelica.ComplexMath.real(v[k] * Modelica.ComplexMath.conj(i[k])) for k in 1:m) "Active power";
  Modelica.Units.SI.ActivePower P_total = sum(P) "Total active power";
  Modelica.Units.SI.ReactivePower Q[m] = array(Modelica.ComplexMath.imag(v[k] * Modelica.ComplexMath.conj(i[k])) for k in 1:m) "Reactive power";
  Modelica.Units.SI.ReactivePower Q_total = sum(Q) "Total reactive power";
  Modelica.Units.SI.ApparentPower S[m] = array(Modelica.ComplexMath.abs(v[k] * Modelica.ComplexMath.conj(i[k])) for k in 1:m) "Magnitude of complex apparent power";
  Modelica.Units.SI.ApparentPower S_total = sqrt(P_total ^ 2 + Q_total ^ 2) "Magnitude of total complex apparent power";
  Real pf[m] = array(cos(Modelica.ComplexMath.arg(Complex(P[k], Q[k]))) for k in 1:m) "Power factor";
  Modelica.Units.SI.ComplexMagneticPotentialDifference V_m = port_p.V_m - port_n.V_m "Complex magnetic potential difference";
  Modelica.Units.SI.MagneticPotentialDifference abs_V_m = Modelica.ComplexMath.abs(V_m) "Magnitude of complex magnetic potential difference";
  Modelica.Units.SI.Angle arg_V_m = Modelica.ComplexMath.arg(V_m) "Argument of complex magnetic potential difference";
  Modelica.Units.SI.ComplexMagneticFlux Phi = port_p.Phi "Complex magnetic flux";
  Modelica.Units.SI.MagneticFlux abs_Phi = Modelica.ComplexMath.abs(Phi) "Magnitude of complex magnetic flux";
  Modelica.Units.SI.Angle arg_Phi = Modelica.ComplexMath.arg(Phi) "Argument of complex magnetic flux";
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.PolyphaseElectroMagneticConverter electroMagneticConverter(final m = m, final effectiveTurns = effectiveTurns) "Symmetric winding" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.Resistor resistor(final m = m, final useHeatPort = useHeatPort, final T_ref = fill(TRef, m), final T = fill(TOperational, m), R_ref = fill(RRef, m), final alpha_ref = fill(alphaRef, m)) "Winding resistor" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortWinding[m] if useHeatPort "Heat ports of winding resistors" ;
  Modelica.Thermal.HeatTransfer.Interfaces.HeatPort_a heatPortCore if useHeatPort "Heat ports of winding resistor" ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.EddyCurrent core(final useHeatPort = useHeatPort, final G = m / 2 * GcRef * effectiveTurns ^ 2) "Core loss model (currently eddy currents only)" ;
  Modelica.Magnetic.QuasiStatic.FundamentalWave.Components.Permeance stray(final G_m(d = 2 * Lsigma / m / effectiveTurns ^ 2, q = 2 * Lsigma / m / effectiveTurns ^ 2)) "Stray permeance equivalent to ideally coupled stray inductances" ;
equation
  connect(resistor.heatPort, heatPortWinding) ;
  connect(core.heatPort, heatPortCore) ;
  connect(stray.port_n, core.port_n) ;
  connect(electroMagneticConverter.plug_p, resistor.plug_n) ;
  connect(plug_n, electroMagneticConverter.plug_n) ;
  connect(plug_p, resistor.plug_p) ;
  connect(port_p, electroMagneticConverter.port_p) ;
  connect(stray.port_p, port_p) ;
  connect(port_n, core.port_n) ;
  connect(electroMagneticConverter.port_n, core.port_p) ;

end SymmetricPolyphaseWinding;

