model PermanentMagnet "Permanent magnet model without intrinsic reluctance, represented by magnetic potential difference"
  extends Modelica.Magnetic.QuasiStatic.FundamentalWave.Losses.PermanentMagnetLosses;
  extends Modelica.Magnetic.QuasiStatic.FundamentalWave.Interfaces.TwoPortElementary;
  parameter Modelica.Units.SI.ComplexMagneticPotentialDifference V_m = Complex(re = 1, im = 0) "Complex magnetic potential difference w.r.t. the rotor fixed reference frame";
  Modelica.Units.SI.MagneticPotentialDifference abs_V_m = Modelica.ComplexMath.abs(V_m) "Magnitude of complex magnetic potential difference";
  Modelica.Units.SI.Angle arg_V_m = Modelica.ComplexMath.arg(V_m) "Argument of complex magnetic potential difference w.r.t. reference frame";
  Modelica.Units.SI.Angle gamma "Angle of V_m fixed reference frame";
  Modelica.Units.SI.ComplexMagneticFlux Phi "Complex magnetic flux";
  Modelica.Units.SI.MagneticPotentialDifference abs_Phi = Modelica.ComplexMath.abs(Phi) "Magnitude of complex magnetic flux";
  Modelica.Units.SI.Angle arg_Phi = Modelica.ComplexMath.arg(Phi) "Argument of complex magnetic flux";
  Modelica.Units.SI.ComplexMagneticPotentialDifference V_mGamma = V_m * Modelica.ComplexMath.fromPolar(1, -gamma) "Magnetic potential difference w.r.t. the reference frame";
