Code:
model ConstantMagneticPotentialDifference "Source with constant magnetic potential difference"
  extends Modelica.Magnetic.QuasiStatic.FundamentalWave.Interfaces.TwoPortElementary;
  parameter Modelica.Units.SI.Frequency f(start = 1) "Frequency of the source";
  parameter Modelica.Units.SI.ComplexMagneticPotentialDifference V_m = Complex(re = 1, im = 0) "Complex magnetic potential difference";
  Modelica.Units.SI.MagneticPotentialDifference abs_V_m = Modelica.ComplexMath.abs(V_m) "Magnitude of complex magnetic potential difference";
  Modelica.Units.SI.Angle arg_V_m = Modelica.ComplexMath.arg(V_m) "Argument of complex magnetic potential difference";
  Modelica.Units.SI.ComplexMagneticFlux Phi "Complex magnetic flux";
  Modelica.Units.SI.MagneticPotentialDifference abs_Phi = Modelica.ComplexMath.abs(Phi) "Magnitude of complex magnetic flux";
  Modelica.Units.SI.Angle arg_Phi = Modelica.ComplexMath.arg(Phi) "Argument of complex magnetic flux";
equation
  // Flux into positive port
  port_p.V_m - port_n.V_m = V_m;
  // Magnetomotive force
  port_p.Phi = Phi;
  // Local flux balance
  port_p.Phi + port_n.Phi = Complex(0, 0);
  // Reference angular speed and angle
  omega = 2 * Modelica.Constants.pi * f;
  Connections.root(port_p.reference);

end ConstantMagneticPotentialDifference;

