  final parameter Integer mBasic = integer(m / mSystems) "Number of phases of basic system" ;
  parameter String terminalConnection(start = "Y") "Choose \"Y\" for star or \"D\" for delta connection" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.PositivePlug plug_sp(final m = m) "To be connected with positive stator plug" ;
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug plug_sn(final m = m) "To be connected with negative stator plug" ;
