Modelica.Math: sort (function)

Syntax    sorted_M = Matrices. sort (M); (sorted_M, indices) = Matrices. sort (M, sortRows=true, ascending=true);    Description  
 Function sort (..) sorts the rows of a Real matrix M in ascending order and returns the result in sorted_M. If the optional argument "sortRows" is false , the columns of the matrix are sorted. If the optional argument "ascending" is false , the rows or columns are sorted in descending order. In the optional second output argument, the indices of the sorted rows or columns with respect to the original matrix are given, such that     sorted_M = if sortedRow then M[indices,:] else M[:,indices];    Example    (M2, i2) := Matrices.sort([2, 1, 0; 2, 0, -1]); -> M2 = [2, 0, -1; 2, 1, 0 ]; i2 = {2,1};

Code:
function sort "Sort the rows or columns of a matrix in ascending or descending order"
  extends Modelica.Icons.Function;
  input Real M[:, :] "Matrix to be sorted";
  input Boolean sortRows = true "= true, if rows are sorted, otherwise columns";
  input Boolean ascending = true "= true, if ascending order, otherwise descending order";
  output Real sorted_M[size(M, 1), size(M, 2)] = M "Sorted matrix";
  output Integer indices[if sortRows then size(M, 1) else size(M, 2)] "sorted_M = if sortRows then M[indices,:] else M[:,indices]";
  /* shellsort algorithm; should be improved later */
protected
  Integer gap;
  Integer i;
  Integer j;
  Real wM2[size(M, 2)];
  Integer wi;
  Integer nM1 = size(M, 1);
  Boolean swap;
  Real sorted_MT[size(M, 2), size(M, 1)];

  encapsulated function greater "Compare whether vector v1 > v2"
  import Modelica;
  extends Modelica.Icons.Function;
  import Modelica.Utilities.Types.Compare;
  input Real v1[:];
  input Real v2[size(v1, 1)];
  output Boolean result;
  protected
  Integer n = size(v1, 1);
  Integer i = 1;
  algorithm
  result := false;
  while i <= n loop
  if v1[i] > v2[i] then
    result := true;
    i := n;
  elseif v1[i] < v2[i] then
    i := n;
  end if;
  i := i + 1;
  end while;
  end greater;

  encapsulated function less "Compare whether vector v1 < v2"
  import Modelica;
  extends Modelica.Icons.Function;
  import Modelica.Utilities.Types.Compare;
  input Real v1[:];
  input Real v2[size(v1, 1)];
  output Boolean result;
  protected
  Integer n = size(v1, 1);
  Integer i = 1;
  algorithm
  result := false;
  while i <= n loop
  if v1[i] < v2[i] then
    result := true;
    i := n;
  elseif v1[i] > v2[i] then
    i := n;
  end if;
  i := i + 1;
  end while;
  end less;
algorithm
  if not sortRows then
    (sorted_MT, indices) := sort(transpose(M), ascending = ascending);
    sorted_M := transpose(sorted_MT);
  else
    indices := 1:size(M, 1);
    gap := div(nM1, 2);
    while gap > 0 loop
      i := gap;
      while i < nM1 loop
        j := i - gap;
        if j >= 0 then
          if ascending then
            swap := greater(sorted_M[j + 1, :], sorted_M[j + gap + 1, :]);
          else
            swap := less(sorted_M[j + 1, :], sorted_M[j + gap + 1, :]);
          end if;
        else
          swap := false;
        end if;
        while swap loop
          wM2 := sorted_M[j + 1, :];
          wi := indices[j + 1];
          sorted_M[j + 1, :] := sorted_M[j + gap + 1, :];
          sorted_M[j + gap + 1, :] := wM2;
          indices[j + 1] := indices[j + gap + 1];
          indices[j + gap + 1] := wi;
          j := j - gap;
          if j >= 0 then
            if ascending then
              swap := greater(sorted_M[j + 1, :], sorted_M[j + gap + 1, :]);
            else
              swap := less(sorted_M[j + 1, :], sorted_M[j + gap + 1, :]);
            end if;
          else
            swap := false;
          end if;
        end while;
        i := i + 1;
      end while;
      gap := div(gap, 2);
    end while;
  end if;

(sorted_M, indices) = Matrices.<strong>sort</strong>(M, sortRows=true, ascending=true);
</pre></blockquote>

<h4>Description</h4>
<p>
Function <strong>sort</strong>(..) sorts the rows of a Real matrix M
in ascending order and returns the result in sorted_M.
If the optional argument \"sortRows\" is <strong>false</strong>, the columns
of the matrix are sorted.
If the optional argument \"ascending\" is <strong>false</strong>, the rows or
columns are sorted in descending order. In the optional second
output argument, the indices of the sorted rows or columns with respect
to the original matrix are given, such that
</p>

<blockquote><pre>
sorted_M = <strong>if</strong> sortedRow <strong>then</strong> M[indices,:] <strong>else</strong> M[:,indices];
</pre></blockquote>

<h4>Example</h4>
<blockquote><pre>
(M2, i2) := Matrices.sort([2, 1,  0;
                           2, 0, -1]);
     -> M2 = [2, 0, -1;
              2, 1, 0 ];
        i2 = {2,1};
</pre></blockquote>
</html>"));
end sort;

