pure function dormqr "Overwrite the general real M-by-N matrix C with Q * C or C * Q or Q' * C or C * Q', where Q is an orthogonal matrix of a QR factorization as returned by dgeqrf"
  extends Modelica.Icons.Function;
  input Real C[:, :];
  input Real A[:, :];
  input Real tau[:];
  input String side = "L";
  input String trans = "N";
  output Real Cout[size(C, 1), size(C, 2)] = C "Contains Q*C or Q**T*C or C*Q**T or C*Q";
  output Integer info;
protected
  Integer m = size(C, 1);
  Integer n = size(C, 2);
  Integer k = if side == "L" then m else n;
  Integer lda = if side == "L" then max(1, m) else max(1, n);
  Integer ldc = max(1, m);
  Integer lwork = if side == "L" then max(1, n) else max(1, m);
  Real work[if side == "L" then max(1, size(C, 2)) else max(1, size(C, 1))];
external "FORTRAN 77"
  dormqr(side, trans, m, n, k, A, lda, tau, Cout, ldc, work, lwork, info)


            if SIDE = 'R', LDA >= max(1,N).

    TAU     (input) DOUBLE PRECISION array, dimension (K)
            TAU(i) must contain the scalar factor of the elementary
            reflector H(i), as returned by DGEQRF.

    C       (input/output) DOUBLE PRECISION array, dimension (LDC,N)
            On entry, the M-by-N matrix C.
            On exit, C is overwritten by Q*C or Q**T*C or C*Q**T or C*Q.

    LDC     (input) INTEGER
