modelica://Modelica.Math/quadratureLobat:
Modelica.Math: quadratureLobatto (function)

Syntax     quadratureLobatto (function f(), a, b);  quadratureLobatto (function f(), a, b, tolerance=100*Modelica.Constants.eps);    Description  
 Compute definite integral over function f(u,...) from u=a up to u=b using the adaptive Lobatto rule according to:      Walter Gander: Adaptive Quadrature - Revisited . 1998.  ftp://ftp.inf.ethz.ch/pub/publications/tech-reports/3xx/306.ps       Example  
 See the examples in Modelica.Math.Nonlinear.Examples .

Code:
function quadratureLobatto "Return the integral of an integrand function using an adaptive Lobatto rule"
  extends Modelica.Icons.Function;
  input Modelica.Math.Nonlinear.Interfaces.partialScalarFunction f "Integrand function";
  input Real a "Lower limit of integration interval";
  input Real b "Upper limit of integration interval";
  input Real tolerance = 100 * Modelica.Constants.eps "Relative tolerance for integral value";
  output Real integral "Integral value";
protected
  constant Real x1 = 0.942882415695480;
  constant Real x2 = 0.641853342345781;
  constant Real x3 = 0.236383199662150;
  constant Real eps = 10 * Modelica.Constants.eps;
  Real m;
  Real h;
  Real alpha;
  Real beta;
  Real x[13];
  Real y[13];
  Real fa;
  Real fb;
  Real i1;
  Real i2;
  Real is;
  Real erri1;
  Real erri2;
  Real R;
  Real tol;
  Integer s;

  function quadStep "Recursive function used by quadrature"
  input Modelica.Math.Nonlinear.Interfaces.partialScalarFunction f;
  input Real a "Right interval end";
  input Real b "Left interval end";
  input Real fa "Function value at a";
  input Real fb "Function value at b";
  input Real is "First approximation of the integral";
  output Real I "Integral value";
  protected
  Real m;
  Real h;
  Real alpha;
  Real beta;
  Real x[5];
  Real y[5];
  Real mll;
  Real ml;
  Real mr;
  Real mrr;
  Real fmll;
  Real fml;
  Real fm;
  Real fmr;
  Real fmrr;
  Real i1;
  Real i2;
  algorithm
  h := (b - a) / 2;
  m := (a + b) / 2;
  alpha := sqrt(2 / 3);
  beta := 1 / sqrt(5);
  mll := m - alpha * h;
  ml := m - beta * h;
  mr := m + beta * h;
  mrr := m + alpha * h;
  x := {mll, ml, m, mr, mrr};
  for i in 1:size(x, 1) loop
    y[i] := f(x[i]);
  end for;
  fmll := y[1];
  fml := y[2];
  fm := y[3];
  fmr := y[4];
  fmrr := y[5];
  i2 := h / 6 * (fa + fb + 5 * (fml + fmr));
  i1 := h / 1470 * (77 * (fa + fb) + 432 * (fmll + fmrr) + 625 * (fml + fmr) + 672 * fm);
  if is + (i1 - i2) == is or mll <= a or b <= mrr then
    I := i1;
  else
    I := quadStep(f, a, mll, fa, fmll, is) + quadStep(f, mll, ml, fmll, fml, is) + quadStep(f, ml, m, fml, fm, is) + quadStep(f, m, mr, fm, fmr, is) + quadStep(f, mr, mrr, fmr, fmrr, is) + quadStep(f, mrr, b, fmrr, fb, is);
  end if;
  end quadStep;
algorithm
  /*
        Numerically evaluate integral using adaptive
        Lobatto rule.
        see Walter Gander: Adaptive Quadrature - Revisited, 1998
                        ftp.inf.ethz.ch in pub/publications/tech-reports/3xx/306.ps

        x[:] are the nodes
        y[:] = f(x[:]) are function values at the nodes
        */
  tol := tolerance;
  m := (a + b) / 2;
  h := (b - a) / 2;
  alpha := sqrt(2 / 3);
  beta := 1 / sqrt(5);
  x := {a, m - x1 * h, m - alpha * h, m - x2 * h, m - beta * h, m - x3 * h, m, m + x3 * h, m + beta * h, m + x2 * h, m + alpha * h, m + x1 * h, b};
  for i in 1:size(x, 1) loop
    y[i] := f(x[i]);
  end for;
  fa := y[1];
  fb := y[13];
  i2 := h / 6 * (y[1] + y[13] + 5 * (y[5] + y[9]));
  i1 := h / 1470 * (77 * (y[1] + y[13]) + 432 * (y[3] + y[11]) + 625 * (y[5] + y[9]) + 672 * y[7]);
  is := h * (0.0158271919734802 * (y[1] + y[13]) + 0.0942738402188500 * (y[2] + y[12]) + 0.155071987336585 * (y[3] + y[11]) + 0.188821573960182 * (y[4] + y[10]) + 0.199773405226859 * (y[5] + y[9]) + 0.224926465333340 * (y[6] + y[8]) + 0.242611071901408 * y[7]);
  s := sign(is);
  if s == 0 then
    s := 1;
  end if;
  erri1 := abs(i1 - is);
  erri2 := abs(i2 - is);
  R := 1;
  if erri2 <> 0 then
    R := erri1 / erri2;
  end if;
  if R > 0 and R < 1 then
    tol := tol / R;
  end if;
  is := s * abs(is) * tol / eps;
  if is == 0 then
    is := b - a;
  end if;
  integral := quadStep(f, a, b, fa, fb, is);

<strong>quadratureLobatto</strong>(function f(), a, b, tolerance=100*Modelica.Constants.eps);
</pre></blockquote>

