Code:
function quadratureLobatto1 "Integrate integral with fixed inputs"
  extends Modelica.Icons.Function;
  import Modelica.Utilities.Streams.print;
  input Real tolerance = 1e-5 "Error tolerance of integral values";
protected
  Real I_numerical[3] "Numerical integral values";
  Real I_analytical[size(I_numerical, 1)] "Analytical integral values";
  Real I_err[size(I_numerical, 1)] "Absolute errors between numerical and analytical integral values";
algorithm
  I_numerical[1] := Modelica.Math.Nonlinear.quadratureLobatto(function Modelica.Math.Nonlinear.Examples.UtilityFunctions.fun4(), 0, 1, tolerance);
  I_analytical[1] := -Modelica.Math.cos(1) + Modelica.Math.cos(0);
  I_numerical[2] := Modelica.Math.Nonlinear.quadratureLobatto(function Modelica.Math.Nonlinear.Examples.UtilityFunctions.fun5(w = 5), 0, 13, tolerance);
  I_analytical[2] := -Modelica.Math.cos(5 * 13) / 5 + Modelica.Math.cos(5 * 0) / 5;
  I_numerical[3] := Modelica.Math.Nonlinear.quadratureLobatto(function Modelica.Math.Nonlinear.Examples.UtilityFunctions.fun6(k = 1 / sqrt(2)), 0, Modelica.Constants.pi / 2, tolerance);
  I_analytical[3] := 1.8540746773013719184338503;
  I_err := abs(I_numerical - I_analytical);
  print("\n... Results of Modelica.Math.Nonlinear.Examples.quadratureLobatto1:");
  print("Function 1 ( integral(sin(x)*dx) from x=0 to x=1): ");
  print("Analytical integral value = " + String(I_analytical[1], format = "2.16f"));
  print("Numerical integral value  = " + String(I_numerical[1], format = "2.16f"));
  print("Absolute difference       = " + String(I_err[1], format = "2.0e"));
  print("");
  print("Function 2 (integral(sin(5*x)*dx) from x=0 to x=13): ");
  print("Analytical integral value = " + String(I_analytical[2], format = "2.16f"));
  print("Numerical integral value  = " + String(I_numerical[2], format = "2.16f"));
  print("Absolute difference       = " + String(I_err[2], format = "2.0e"));
  print("");
  print("Function 3 (Elliptic integral from x=0 to pi/2): ");
