modelica://Modelica.Math/quadStep:
Modelica.Math: quadStep (function)

Code:
function quadStep "Recursive function used by quadrature"
  input Modelica.Math.Nonlinear.Interfaces.partialScalarFunction f;
  input Real a "Right interval end";
  input Real b "Left interval end";
  input Real fa "Function value at a";
  input Real fb "Function value at b";
  input Real is "First approximation of the integral";
  output Real I "Integral value";
protected
  Real m;
  Real h;
  Real alpha;
  Real beta;
  Real x[5];
  Real y[5];
  Real mll;
  Real ml;
  Real mr;
  Real mrr;
  Real fmll;
  Real fml;
  Real fm;
  Real fmr;
  Real fmrr;
  Real i1;
  Real i2;
algorithm
  h := (b - a) / 2;
  m := (a + b) / 2;
  alpha := sqrt(2 / 3);
  beta := 1 / sqrt(5);
  mll := m - alpha * h;
  ml := m - beta * h;
  mr := m + beta * h;
  mrr := m + alpha * h;
  x := {mll, ml, m, mr, mrr};
  for i in 1:size(x, 1) loop
    y[i] := f(x[i]);
  end for;
  fmll := y[1];
  fml := y[2];
  fm := y[3];
  fmr := y[4];
  fmrr := y[5];
  i2 := h / 6 * (fa + fb + 5 * (fml + fmr));
  i1 := h / 1470 * (77 * (fa + fb) + 432 * (fmll + fmrr) + 625 * (fml + fmr) + 672 * fm);
  if is + (i1 - i2) == is or mll <= a or b <= mrr then
    I := i1;
  else
    I := quadStep(f, a, mll, fa, fmll, is) + quadStep(f, mll, ml, fmll, fml, is) + quadStep(f, ml, m, fml, fm, is) + quadStep(f, m, mr, fm, fmr, is) + quadStep(f, mr, mrr, fmr, fmrr, is) + quadStep(f, mrr, b, fmrr, fb, is);
  end if;
end quadStep;

