  Modelica.Mechanics.MultiBody.Forces.Spring spring1(coilWidth = 0.01, numberOfWindings = 5, c = 20, s_unstretched = 0.2) ;
  Modelica.Mechanics.MultiBody.Forces.Damper damper1(d = 1, length_a = 0.1, diameter_a = 0.08, animation = false) ;
  Modelica.Mechanics.MultiBody.Joints.Revolute revolute(phi(fixed = true), w(fixed = true)) ;
  Modelica.Mechanics.MultiBody.Joints.Prismatic prismatic(boxWidth = 0.04, boxColor = {255, 65, 65}, s(fixed = true, start = 0.5), v(fixed = true)) ;
equation
  connect(world.frame_b, bar1.frame_a) ;
  connect(revolute.frame_a, bar1.frame_b) ;
  connect(prismatic.frame_a, revolute.frame_b) ;
  connect(damper1.frame_a, bar1.frame_b) ;
  connect(damper1.frame_b, prismatic.frame_b) ;
  connect(spring1.frame_a, bar1.frame_b) ;
  connect(spring1.frame_b, prismatic.frame_b) ;
  connect(body1.frame_a, prismatic.frame_b) ;

end PendulumWithSpringDamper;

modelica://Modelica.Mechanics/PointGravi:
Modelica.Mechanics: PointGravity (model)

This model demonstrates a point gravity field. Two bodies are placed in the gravity field. The initial positions and velocities of these bodies are selected such that one body rotates on a circle and the other body rotates on an ellipse around the center of the point gravity field.

Code:
model PointGravity "Two point masses in a point gravity field"
  extends Modelica.Icons.Example;
  inner Modelica.Mechanics.MultiBody.World world(mu = 1, gravitySphereDiameter = 0.1, gravityType = Modelica.Mechanics.MultiBody.Types.GravityTypes.PointGravity) ;
  Modelica.Mechanics.MultiBody.Parts.Body body1(m = 1, sphereDiameter = 0.1, I_11 = 0.1, I_22 = 0.1, I_33 = 0.1, r_0(start = {0, 0.6, 0}, each fixed = true), v_0(start = {1, 0, 0}, each fixed = true), angles_fixed = true, w_0_fixed = true, r_CM = {0, 0, 0}) ;
  Modelica.Mechanics.MultiBody.Parts.Body body2(m = 1, sphereDiameter = 0.1, I_11 = 0.1, I_22 = 0.1, I_33 = 0.1, r_0(start = {0.6, 0.6, 0}, each fixed = true), v_0(start = {0.6, 0, 0}, each fixed = true), angles_fixed = true, w_0_fixed = true, r_CM = {0, 0, 0}) ;

end PointGravity;

Modelica.Mechanics: PointGravityWithPointMasses (model)

This model demonstrates the usage of model Parts.PointMass in a point gravity field. The PointMass model has the feature that the rotation is not taken into account and can therefore also not be calculated. This example demonstrates two cases where this does not matter: If a PointMass is not connected (body1, body2), the orientation object in these point masses is set to a unit rotation. If a PointMass is connected by a line force element, such as the used Forces.LineForceWithMass component, then the orientation object is set to a unit rotation within the line force element. These are the two cases where the rotation is automatically set to a default value, when the physical system does not provide the equations.

Code:
model PointGravityWithPointMasses "Two point masses in a point gravity field (rotation of bodies is neglected)"
  extends Modelica.Icons.Example;
  inner Modelica.Mechanics.MultiBody.World world(mu = 1, gravitySphereDiameter = 0.1, gravityType = Modelica.Mechanics.MultiBody.Types.GravityTypes.PointGravity) ;
  Modelica.Mechanics.MultiBody.Parts.PointMass body1(m = 1, sphereDiameter = 0.1, r_0(start = {0, 0.6, 0}, each fixed = true), v_0(start = {1, 0, 0}, each fixed = true)) ;
  Modelica.Mechanics.MultiBody.Parts.PointMass body2(m = 1, sphereDiameter = 0.1, r_0(start = {0.6, 0.6, 0}, each fixed = true), v_0(start = {0.6, 0, 0}, each fixed = true)) ;
  Modelica.Mechanics.MultiBody.Parts.PointMass body3(m = 1, sphereDiameter = 0.1, r_0(start = {0, 0.8, 0}, each fixed = true), v_0(start = {0.6, 0, 0}, each fixed = true)) ;
  Modelica.Mechanics.MultiBody.Parts.PointMass body4(m = 1, sphereDiameter = 0.1, r_0(start = {0.3, 0.8, 0}, each fixed = true), v_0(start = {0.6, 0, 0}, each fixed = true)) ;
  Modelica.Mechanics.MultiBody.Forces.Spring spring(showMass = false, c = 10, fixedRotationAtFrame_b = true, fixedRotationAtFrame_a = true) ;
equation
  connect(spring.frame_a, body3.frame_a) ;
  connect(spring.frame_b, body4.frame_a) ;

end PointGravityWithPointMasses;

Modelica.Mechanics: PointGravityWithPointMasses2 (model)

This model demonstrates the usage of model Parts.PointMass in a point gravity field. 6 point masses are connected rigidly together. Translating such a model results in an error, because point masses do not define an orientation object. The example demonstrates that in such a case (when the orientation object is not defined by an object that is connected to a point mass), a "MultiBody.Joints.FreeMotion" joint has to be used, to define the degrees of freedom of this structure.   
 In order to demonstrate that this approach is correct, in model "referenceSystem", the same system is again provided, but this time modeled with a generic body (Parts.Body) where the inertia tensor is set to zero. In this case, no FreeMotion object is needed because every body provides its absolute translational and rotational position and velocity as potential states.   
 The two systems should move exactly in the same way. The system with the PointMasses object visualizes the point masses in "red", whereas the "referenceSystem" shows its bodies in "blue".

Code:
model PointGravityWithPointMasses2 "Rigidly connected point masses in a point gravity field"
  extends Modelica.Icons.Example;
  model PointMass = Modelica.Mechanics.MultiBody.Parts.PointMass(m = 1, sphereColor = {255, 0, 0}) "Point mass used at all places of this example" ;
  PointMass pointMass1(r_0(start = {3, 0, 0}, each fixed = true), v_0(start = {0, 0, -1}, each fixed = true)) ;
  PointMass pointMass2 ;
  PointMass pointMass3(r_0(start = {2, 1, 0}, fixed = {true, false, false}), v_0(start = {0, 0, -1}, fixed = {true, false, false})) ;
  PointMass pointMass4(r_0(start = {2, -1, 0}, fixed = {false, false, true}), v_0(start = {0, 0, -1}, fixed = {false, false, true})) ;
  PointMass pointMass5(r_0(start = {2, 0, 1}, fixed = {false, false, true}), v_0(start = {0, 0, -1}, fixed = {false, false, true})) ;
  PointMass pointMass6 ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation(r = {1, 0, 0}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation1(r = {-1, 0, 0}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation2(r = {0, 1, 0}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation3(r = {0, -1, 0}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation4(r = {0, 0, 1}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation5(r = {0, 0, -1}) ;
  inner Modelica.Mechanics.MultiBody.World world(gravitySphereDiameter = 0.1, gravityType = Modelica.Mechanics.MultiBody.Types.GravityTypes.PointGravity, mu = 5) ;
  Modelica.Mechanics.MultiBody.Joints.FreeMotion freeMotion ;
  SystemWithStandardBodies referenceSystem ;

  model SystemWithStandardBodies "For comparison purposes, an equivalent model with Bodies instead of PointMasses"
    model PointMass = Modelica.Mechanics.MultiBody.Parts.Body(final m = 1, final r_CM = {0, 0, 0}, final I_11 = 0, final I_22 = 0, final I_33 = 0, final I_21 = 0, final I_31 = 0, final I_32 = 0) "Body used at all places of the comparison model with zero inertia tensor" ;
    PointMass pointMass1(r_0(start = {3, 0, 0}, each fixed = true), v_0(start = {0, 0, -1}, each fixed = true), angles_fixed = true, w_0_fixed = true) ;
    PointMass pointMass2 ;
    PointMass pointMass3 ;
    PointMass pointMass4 ;
    PointMass pointMass5 ;
    PointMass pointMass6 ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation(r = {1, 0, 0}) ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation1(r = {-1, 0, 0}) ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation2(r = {0, 1, 0}) ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation3(r = {0, -1, 0}) ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation4(r = {0, 0, 1}) ;
    Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslation5(r = {0, 0, -1}) ;
  equation
    connect(fixedTranslation1.frame_a, fixedTranslation.frame_a) ;
    connect(fixedTranslation1.frame_a, fixedTranslation2.frame_a) ;
    connect(fixedTranslation3.frame_a, fixedTranslation.frame_a) ;
    connect(fixedTranslation1.frame_a, fixedTranslation4.frame_a) ;
    connect(fixedTranslation5.frame_a, fixedTranslation.frame_a) ;
    connect(fixedTranslation2.frame_b, pointMass3.frame_a) ;
    connect(fixedTranslation3.frame_b, pointMass4.frame_a) ;
    connect(pointMass5.frame_a, fixedTranslation4.frame_b) ;
    connect(fixedTranslation5.frame_b, pointMass6.frame_a) ;
    connect(fixedTranslation.frame_b, pointMass1.frame_a) ;
    connect(fixedTranslation1.frame_b, pointMass2.frame_a) ;

  end SystemWithStandardBodies;
equation
  connect(fixedTranslation1.frame_a, fixedTranslation.frame_a) ;
  connect(fixedTranslation1.frame_a, fixedTranslation2.frame_a) ;
  connect(fixedTranslation3.frame_a, fixedTranslation.frame_a) ;
  connect(fixedTranslation1.frame_a, fixedTranslation4.frame_a) ;
  connect(fixedTranslation5.frame_a, fixedTranslation.frame_a) ;
  connect(fixedTranslation2.frame_b, pointMass3.frame_a) ;
  connect(fixedTranslation3.frame_b, pointMass4.frame_a) ;
  connect(pointMass5.frame_a, fixedTranslation4.frame_b) ;
  connect(fixedTranslation5.frame_b, pointMass6.frame_a) ;
  connect(fixedTranslation.frame_b, pointMass1.frame_a) ;
  connect(fixedTranslation1.frame_b, pointMass2.frame_a) ;
  connect(world.frame_b, freeMotion.frame_a) ;
  connect(freeMotion.frame_b, fixedTranslation1.frame_a) ;

end PointGravityWithPointMasses2;

modelica://Modelica.Mechanics/SpringDamp:
Modelica.Mechanics: SpringDamperSystem (model)

This example demonstrates:   
The animation of spring and damper components A body can be freely moving without any connection to a joint. In this case body coordinates are used automatically as states (whenever joints are present, it is first tried to use the generalized coordinates of the joints as states). If a body is freely moving, the initial position and velocity of the body can be defined with the "Initialization" menu as shown with the body "body1" in the left part (click on "Initialization").

Code:
model SpringDamperSystem "Simple spring/damper/mass system"
  extends Modelica.Icons.Example;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  inner Modelica.Mechanics.MultiBody.World world ;
  Modelica.Mechanics.MultiBody.Parts.Body body1(m = 1, animation = animation, r_CM = {0, -0.2, 0}, cylinderDiameter = 0.05, sphereDiameter = 0.15, I_11 = 0.1, I_22 = 0.1, I_33 = 0.1, r_0(start = {0.3, -0.2, 0}, each fixed = true), v_0(each fixed = true), angles_fixed = true, w_0_fixed = true, w_0_start(each displayUnit = "deg/s") = {0, 0, 0.03490658503988659}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation bar1(animation = animation, r = {0.3, 0, 0}) ;
