  extends Modelica.Icons.Example;
  extends Modelica.Mechanics.MultiBody.Examples.Loops.Utilities.Engine1bBase;
  Modelica.Mechanics.MultiBody.Joints.Revolute b1(n = {1, 0, 0}, cylinderLength = 0.02, cylinderDiameter = 0.05) ;
  Modelica.Mechanics.MultiBody.Joints.RevolutePlanarLoopConstraint b2(n = {1, 0, 0}, cylinderLength = 0.02, cylinderDiameter = 0.05) ;
  Modelica.Mechanics.MultiBody.Joints.Prismatic cylinder(useAxisFlange = true, boxWidth = 0.02, n = {0, -1, 0}) ;
