  Modelica.Mechanics.MultiBody.Joints.Universal joint(n_a = {0, 0, 1}, n_b = {1, 0, 0}, stateSelect = StateSelect.always, phi_a(fixed = true), phi_b(fixed = true), w_a(fixed = true), w_b(fixed = true)) ;
  Modelica.Mechanics.MultiBody.Joints.Constraints.Universal constraint(n_a = joint.n_a, n_b = joint.n_b) ;
