  Modelica.Mechanics.MultiBody.Parts.BodyShape bodyOfJoint(m = 1, I_11 = 1, I_22 = 1, I_33 = 1, r = {0.4, 0, 0}, r_CM = {0.2, 0, 0}, width = 0.05, r_0(start = {0.2, -0.5, 0.1}, each fixed = false), v_0(each fixed = false), angles_fixed = false, w_0_fixed = false, angles_start = {0.17453292519943, 0.95993108859688, 1.1868238913561}, final color = {0, 0, 255}) ;
  Modelica.Mechanics.MultiBody.Parts.BodyShape bodyOfConstraint(I_11 = 1, I_22 = 1, I_33 = 1, width = 0.05, r_0(start = {0.2, -0.5, 0.1}, each fixed = false), v_0(each fixed = false), angles_fixed = false, w_0_fixed = false, final color = {0, 128, 0}, r = bodyOfJoint.r, r_CM = bodyOfJoint.r_CM, m = bodyOfJoint.m, angles_start = {0.17453292519943, 0.95993108859688, 1.1868238913561}) ;
  Modelica.Mechanics.MultiBody.Forces.Spring springOfJoint(c = 20, s_unstretched = 0, width = 0.1, coilWidth = 0.005, numberOfWindings = 5) ;
  Modelica.Mechanics.MultiBody.Forces.Spring springOfConstraint(width = 0.1, coilWidth = 0.005, c = springOfJoint.c, s_unstretched = springOfJoint.s_unstretched, numberOfWindings = springOfJoint.numberOfWindings) ;
  inner Modelica.Mechanics.MultiBody.World world ;
  Modelica.Mechanics.MultiBody.Parts.FixedRotation fixedRotation(r = {0.2, -0.3, 0.2}, rotationType = Modelica.Mechanics.MultiBody.Types.RotationTypes.PlanarRotationSequence, angles = {10, 55, 68}) ;
