  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslationOfJoint(r = {0.1, 0.15, 0.2}) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation fixedTranslationOfConstraint(r = fixedTranslationOfJoint.r) ;
