  parameter Modelica.Units.SI.Distance cylinderDiameter = world.defaultJointWidth "Diameter of revolute cylinder" ;
  input Modelica.Mechanics.MultiBody.Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of revolute cylinder" ;
  parameter Modelica.Units.SI.Distance boxWidth = 0.3 * cylinderDiameter "Width of prismatic joint boxes" ;
  parameter Modelica.Units.SI.Distance boxHeight = boxWidth "Height of prismatic joint boxes" ;
  input Modelica.Mechanics.MultiBody.Types.Color boxColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of prismatic joint boxes" ;
  parameter StateSelect stateSelect = StateSelect.prefer "Priority to use joint coordinates (s_x, s_y, phi, v_x, v_y, w) as states" ;
  Modelica.Mechanics.MultiBody.Joints.Prismatic prismatic_x(stateSelect = StateSelect.never, n = cross(cross(n, n_x), n), animation = false) ;
  Modelica.Mechanics.MultiBody.Joints.Prismatic prismatic_y(stateSelect = StateSelect.never, n = cross(n, n_x), animation = false) ;
  Modelica.Mechanics.MultiBody.Joints.Revolute revolute(stateSelect = StateSelect.never, n = n, animation = false) ;
  Modelica.Units.SI.Position s_x(start = 0, stateSelect = stateSelect) "Relative distance along first prismatic joint starting at frame_a";
  Modelica.Units.SI.Position s_y(start = 0, stateSelect = stateSelect) "Relative distance along second prismatic joint starting at first prismatic joint";
  Modelica.Units.SI.Angle phi(start = 0, stateSelect = stateSelect) "Relative rotation angle from frame_a to frame_b";
  Modelica.Units.SI.Velocity v_x(start = 0, stateSelect = stateSelect) "First derivative of s_x (relative velocity in s_x direction)";
  Modelica.Units.SI.Velocity v_y(start = 0, stateSelect = stateSelect) "First derivative of s_y (relative velocity in s_y direction)";
  Modelica.Units.SI.AngularVelocity w(start = 0, stateSelect = stateSelect) "First derivative of angle phi (relative angular velocity)";
  Modelica.Units.SI.Acceleration a_x(start = 0) "Second derivative of s_x (relative acceleration in s_x direction)";
  Modelica.Units.SI.Acceleration a_y(start = 0) "Second derivative of s_y (relative acceleration in s_y direction)";
  Modelica.Units.SI.AngularAcceleration wd(start = 0) "Second derivative of angle phi (relative angular acceleration)";
protected
  parameter Integer ndim = if world.enableAnimation and animation then 1 else 0;
  parameter Real e[3](each final unit = "1") = Modelica.Math.Vectors.normalize(n);
protected
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape box_x[ndim](each shapeType = "box", each color = boxColor, each length = prismatic_x.s, each width = boxWidth, each height = boxWidth, each lengthDirection = prismatic_x.e, each widthDirection = {0, 1, 0}, each r = frame_a.r_0, each R = frame_a.R) ;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape box_y[ndim](each shapeType = "box", each color = boxColor, each length = prismatic_y.s, each width = boxWidth, each height = boxWidth, each lengthDirection = prismatic_y.e, each widthDirection = {1, 0, 0}, each r = prismatic_y.frame_a.r_0, each R = prismatic_y.frame_a.R) ;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape cylinder[ndim](each shapeType = "cylinder", each color = cylinderColor, each length = cylinderLength, each width = cylinderDiameter, each height = cylinderDiameter, each lengthDirection = n, each widthDirection = {0, 1, 0}, each r_shape = -e * (cylinderLength / 2), each r = revolute.frame_b.r_0, each R = revolute.frame_b.R) ;
equation
  s_x = prismatic_x.s;
  s_y = prismatic_y.s;
  phi = revolute.phi;
  v_x = der(s_x);
  v_y = der(s_y);
  w = der(phi);
  a_x = der(v_x);
  a_y = der(v_y);
