  frame_b.r_0 = frame_a.r_0 + Modelica.Mechanics.MultiBody.Frames.resolve1(frame_a.R, r_rel_a);
  // Cut-forces and cut-torques are zero
  frame_a.f = zeros(3);
  frame_a.t = zeros(3);
  frame_b.f = zeros(3);
  frame_b.t = zeros(3);
  if enforceStates then
    Connections.branch(frame_a.R, frame_b.R);
    if Connections.rooted(frame_a.R) then
      R_rel_inv = Modelica.Mechanics.MultiBody.Frames.nullRotation();
      frame_b.R = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(frame_a.R, R_rel);
    else
      R_rel_inv = Modelica.Mechanics.MultiBody.Frames.inverseRotation(R_rel);
      frame_a.R = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(frame_b.R, R_rel_inv);
    end if;
    // Compute relative orientation object
    if useQuaternions then
      // Use Quaternions as states (with dynamic state selection)
      {0} = Modelica.Mechanics.MultiBody.Frames.Quaternions.orientationConstraint(Q);
      w_rel_b = Modelica.Mechanics.MultiBody.Frames.Quaternions.angularVelocity2(Q, der(Q));
      R_rel = Modelica.Mechanics.MultiBody.Frames.from_Q(Q, w_rel_b);
      // Dummies
      phi = zeros(3);
      phi_d = zeros(3);
      phi_dd = zeros(3);
    else
      // Use angles as states
      phi_d = der(phi);
      phi_dd = der(phi_d);
      R_rel = Modelica.Mechanics.MultiBody.Frames.axesRotations(sequence_angleStates, phi, phi_d);
      w_rel_b = Modelica.Mechanics.MultiBody.Frames.angularVelocity2(R_rel);
      // Dummies
      Q = zeros(4);
    end if;
  else
    // Free motion joint does not have states
    if w_rel_a_fixed or z_rel_a_fixed then
      w_rel_b = Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_b.R) - Modelica.Mechanics.MultiBody.Frames.resolve2(frame_b.R, Modelica.Mechanics.MultiBody.Frames.angularVelocity1(frame_a.R));
    else
      // dummy
      w_rel_b = zeros(3);
    end if;
    // Dummies
    R_rel = Modelica.Mechanics.MultiBody.Frames.nullRotation();
    R_rel_inv = Modelica.Mechanics.MultiBody.Frames.nullRotation();
    Q = zeros(4);
    phi = zeros(3);
    phi_d = zeros(3);
    phi_dd = zeros(3);
  end if;

end FreeMotion;

Modelica.Mechanics: FreeMotionScalarInit (model)

Joint which does not constrain the motion between frame_a and frame_b. Such a joint is meaningful if the relative distance and orientation between frame_a and frame_b, and their derivatives, shall be used as states or shall be used for non-standard  initialization . This joint allows to initialize  every scalar element of the relative quantities, as well as to define StateSelect attributes for every  scalar element separately.   
 In the following figure the animation of a FreeMotionScalarInit joint is shown. The light blue coordinate system is frame_a and the dark blue coordinate system is frame_b of the joint. (here: r_rel_a_1(start = 0.5), r_rel_a_2(start = 0), r_rel_a_3(start = 0.5), angle_1(start = 45 o ), angle_2(start = 45 o ), angle_3(start = 45 o )).   

 A example to use this joint for the initialization of a planar double pendulum by providing its tip position, is shown in  Examples.Elementary.DoublePendulumInitTip .

Code:
model FreeMotionScalarInit "Free motion joint with scalar initialization and state selection (6 degrees-of-freedom, 12 potential states)"
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialTwoFrames;
