  parameter Boolean use_w = false "= true, if w_rel_b shall be used" ;
  Modelica.Blocks.Interfaces.RealOutput w_rel_b_1(final quantity = "AngularVelocity", final unit = "rad/s", start = 0, stateSelect = w_rel_b_1_stateSelect) if use_w "Relative angular velocity w_rel_b[1]" ;
  Modelica.Blocks.Interfaces.RealOutput w_rel_b_2(final quantity = "AngularVelocity", final unit = "rad/s", start = 0, stateSelect = w_rel_b_2_stateSelect) if use_w "Relative angular velocity w_rel_b[2]" ;
  Modelica.Blocks.Interfaces.RealOutput w_rel_b_3(final quantity = "AngularVelocity", final unit = "rad/s", start = 0, stateSelect = w_rel_b_3_stateSelect) if use_w "Relative angular velocity w_rel_b[3]" ;
  parameter StateSelect w_rel_b_1_stateSelect = StateSelect.never "StateSelect of w_rel_b[1]" ;
