model UniversalSpherical "Universal - spherical joint aggregation (1 constraint, no potential states)"
  import Modelica.Mechanics.MultiBody.Types;
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialTwoFrames;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_ia "Coordinate system at the origin of frame_a, fixed at the rod connecting the universal with the spherical joint" ;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Boolean showUniversalAxes = true "= true, if universal joint shall be visualized with two cylinders, otherwise with a sphere (provided animation=true)";
  parameter Boolean computeRodLength = false "= true, if distance between frame_a and frame_b shall be computed during initialization (see info)";
  parameter Types.Axis n1_a = {0, 0, 1} "Axis 1 of universal joint resolved in frame_a (axis 2 is orthogonal to axis 1 and to rod)" ;
  parameter Modelica.Units.SI.Position rRod_ia[3] = {1, 0, 0} "Vector from origin of frame_a to origin of frame_b, resolved in frame_ia (if computeRodLength=true, rRod_ia is only an axis vector along the connecting rod)" ;
  parameter Modelica.Units.SI.Diameter sphereDiameter = world.defaultJointLength "Diameter of spheres representing the universal and the spherical joint" ;
  input Types.Color sphereColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of spheres representing the universal and the spherical joint" ;
  parameter Types.ShapeType rodShapeType = "cylinder" "Shape type of rod connecting the universal and the spherical joint" ;
  parameter Modelica.Units.SI.Distance rodWidth = sphereDiameter / Types.Defaults.JointRodDiameterFraction "Width of rod shape in direction of axis 2 of universal joint." ;
  parameter Modelica.Units.SI.Distance rodHeight = rodWidth "Height of rod shape in direction that is orthogonal to rod and to axis 2" ;
  parameter Types.ShapeExtra rodExtra = 0.0 "Additional parameter depending on rodShapeType" ;
  input Types.Color rodColor = Modelica.Mechanics.MultiBody.Types.Defaults.RodColor "Color of rod shape connecting the universal and the spherical joints" ;
  parameter Modelica.Units.SI.Distance cylinderLength = world.defaultJointLength "Length of cylinders representing the two universal joint axes" ;
  parameter Modelica.Units.SI.Distance cylinderDiameter = world.defaultJointWidth "Diameter of cylinders representing the two universal joint axes" ;
  input Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of cylinders representing the two universal joint axes" ;
  input Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
  parameter Boolean kinematicConstraint = true "= false, if no constraint shall be defined, due to analytically solving a kinematic loop" ;
  Real constraintResidue = rRod_0 * rRod_0 - rodLength * rodLength "Constraint equation of joint in residue form: Either length constraint (= default) or equation to compute rod force (for analytic solution of loops in combination with Internal.RevoluteWithLengthConstraint/PrismaticWithLengthConstraint)" ;
  parameter Boolean checkTotalPower = false "= true, if total power flowing into this component shall be determined (must be zero)" ;
  Modelica.Units.SI.Force f_rod "Constraint force in direction of the rod (positive, if rod is pressed)";
  final parameter Modelica.Units.SI.Distance rodLength(fixed = false, start = Modelica.Math.Vectors.length(rRod_ia)) "Length of rod (distance between origin of frame_a and origin of frame_b)";
  final parameter Real eRod_ia[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(rRod_ia) "Unit vector from origin of frame_a to origin of frame_b, resolved in frame_ia";
  final parameter Real e2_ia[3](each final unit = "1") = Modelica.Math.Vectors.normalize(cross(n1_a, eRod_ia)) "Unit vector in direction of axis 2 of universal joint, resolved in frame_ia (orthogonal to n1_a and eRod_ia; note: frame_ia is parallel to frame_a when the universal joint angles are zero)";
  final parameter Real e3_ia[3](each final unit = "1") = cross(eRod_ia, e2_ia) "Unit vector perpendicular to eRod_ia and e2_ia, resolved in frame_ia";
  Modelica.Units.SI.Power totalPower "Total power flowing into this element, if checkTotalPower=true (otherwise dummy)";
  Modelica.Units.SI.Force f_b_a1[3] "frame_b.f without f_rod part, resolved in frame_a (needed for analytic loop handling)";
  Real eRod_a[3](each final unit = "1") "Unit vector in direction of rRod_a, resolved in frame_a (needed for analytic loop handling)";
  Modelica.Units.SI.Position rRod_0[3](start = rRod_ia) "Position vector from origin of frame_a to origin of frame_b resolved in world frame";
  Modelica.Units.SI.Position rRod_a[3](start = rRod_ia) "Position vector from origin of frame_a to origin of frame_b resolved in frame_a";
protected
  Modelica.Units.SI.Force f_b_a[3] "frame_b.f resolved in frame_a";
  Modelica.Units.SI.Force f_ia_a[3] "frame_ia.f resolved in frame_a";
  Modelica.Units.SI.Torque t_ia_a[3] "frame_ia.t resolved in frame_a";
  Real n2_a[3](each final unit = "1") "Vector in direction of axis 2 of the universal joint (e2_ia), resolved in frame_a";
  Real length2_n2_a(start = 1, unit = "1") "Square of length of vector n2_a";
  Real length_n2_a(unit = "1") "Length of vector n2_a";
  Real e2_a[3](each final unit = "1") "Unit vector in direction of axis 2 of the universal joint (e2_ia), resolved in frame_a";
  Real e3_a[3](each final unit = "1") "Unit vector perpendicular to eRod_ia and e2_a, resolved in frame_a";
  Real der_rRod_a_L[3](each unit = "1/s") "= der(rRod_a)/rodLength";
  Modelica.Units.SI.AngularVelocity w_rel_ia1[3];
  Modelica.Mechanics.MultiBody.Frames.Orientation R_rel_ia1;
  Modelica.Mechanics.MultiBody.Frames.Orientation R_rel_ia2;
  // Real T_rel_ia[3, 3];
  Modelica.Mechanics.MultiBody.Frames.Orientation R_rel_ia "Rotation from frame_a to frame_ia";
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape rodShape(shapeType = rodShapeType, color = rodColor, specularCoefficient = specularCoefficient, length = rodLength, width = rodWidth, height = rodHeight, lengthDirection = eRod_ia, widthDirection = e2_ia, r = frame_ia.r_0, R = frame_ia.R) if world.enableAnimation and animation;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape sphericalShape_b(shapeType = "sphere", color = sphereColor, specularCoefficient = specularCoefficient, length = sphereDiameter, width = sphereDiameter, height = sphereDiameter, lengthDirection = {1, 0, 0}, widthDirection = {0, 1, 0}, r_shape = {-0.5, 0, 0} * sphereDiameter, r = frame_b.r_0, R = frame_b.R) if world.enableAnimation and animation;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape sphericalShape_a(shapeType = "sphere", color = sphereColor, specularCoefficient = specularCoefficient, length = sphereDiameter, width = sphereDiameter, height = sphereDiameter, lengthDirection = {1, 0, 0}, widthDirection = {0, 1, 0}, r_shape = {-0.5, 0, 0} * sphereDiameter, r = frame_a.r_0, R = frame_a.R) if world.enableAnimation and animation and not showUniversalAxes;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape universalShape1(shapeType = "cylinder", color = cylinderColor, specularCoefficient = specularCoefficient, length = cylinderLength, width = cylinderDiameter, height = cylinderDiameter, lengthDirection = n1_a, widthDirection = {0, 1, 0}, r_shape = -n1_a * (cylinderLength / 2), r = frame_a.r_0, R = frame_a.R) if world.enableAnimation and animation and showUniversalAxes;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape universalShape2(shapeType = "cylinder", color = cylinderColor, specularCoefficient = specularCoefficient, length = cylinderLength, width = cylinderDiameter, height = cylinderDiameter, lengthDirection = e2_ia, widthDirection = {0, 1, 0}, r_shape = -e2_ia * (cylinderLength / 2), r = frame_ia.r_0, R = frame_ia.R) if world.enableAnimation and animation and showUniversalAxes;
initial equation
  if not computeRodLength then
    rodLength = Modelica.Math.Vectors.length(rRod_ia);
  end if;
equation
  Connections.branch(frame_a.R, frame_ia.R);
  if kinematicConstraint then
    rRod_0 = transpose(frame_b.R.T) * (frame_b.R.T * frame_b.r_0) - transpose(frame_a.R.T) * (frame_a.R.T * frame_a.r_0);
  else
    rRod_0 = frame_b.r_0 - frame_a.r_0;
  end if;
  //rRod_0 = frame_b.r_0 - frame_a.r_0;
  rRod_a = Modelica.Mechanics.MultiBody.Frames.resolve2(frame_a.R, rRod_0);
  // Constraint equation
  constraintResidue = 0;
  /* Determine relative Rotation R_rel_ia from frame_a to frame_ia
     and absolute rotation of frame_a.R.
  */
  eRod_a = rRod_a / rodLength;
  n2_a = cross(n1_a, eRod_a);
  length2_n2_a = n2_a * n2_a;
  assert(length2_n2_a > 1e-10, "
A Modelica.Mechanics.MultiBody.Joints.UniversalSpherical joint (consisting of
a universal joint and a spherical joint connected together
by a rigid rod) is in the singular configuration of the
universal joint. This means that axis 1 of the universal
joint defined via parameter \"n1_a\" is parallel to vector
\"rRod_ia\" that is directed from the origin of frame_a to the
origin of frame_b.
   You may try to use another \"n1_a\" vector. If this fails,
use instead Modelica.Mechanics.MultiBody.Joints.SphericalSpherical, if this is
possible, because this joint aggregation does not have a
singular configuration.
");
  length_n2_a = sqrt(length2_n2_a);
  e2_a = n2_a / length_n2_a;
  e3_a = cross(eRod_a, e2_a);
  /* The statements below are an efficient implementation of the
   original equations:
     T_rel_ia = [eRod_ia, e2_ia, e3_ia]*transpose([eRod_a, e2_a, e3_a]);
     R_rel_ia = Frames.from_T(T_rel_ia,
                   Frames.TransformationMatrices.angularVelocity2(T_rel_ia, der(T_rel_ia)));
   To perform this, the rotation is split into two parts:
     R_rel_ia : Rotation object from frame_a to frame_ia
     R_rel_ia1: Rotation object from frame_a to frame_ia1
                (frame that is fixed in frame_ia such that x-axis
                is along the rod axis)
                T = transpose([eRod_a, e2_a, e3_a]; w = w_rel_ia1
     R_rel_ia2: Fixed rotation object from frame_ia1 to frame_ia
                T = [eRod_ia, e2_ia, e3_ia]; w = zeros(3)

   The difficult part is to compute w_rel_ia1:
      w_rel_ia1 = [  e3_a*der(e2_a);
                    -e3_a*der(eRod_a);
                     e2_a*der(eRod_a)]
   der(eRod_a) is directly given, since eRod_a is a function
   of translational quantities only.
      der(eRod_a) = (der(rRod_a) - eRod_a*(eRod_a*der(rRod_a)))/rodLength
      der(n2_a)   = cross(n1_a, der(eRod_a))
      der(e2_a)   = (der(n2_a) - e2_a*(e2_a*der(n2_a)))/length_n2_a
   Inserting these equations in w_rel_ia1 results in:
      e3_a*der(eRod_a) = e3_a*der(rRod_a)/rodLength       // e3_a*eRod_a = 0
      e2_a*der(eRod_a) = e2_a*der(rRod_a)/rodLength       // e2_a*eRod_a = 0
      e3_a*der(e2_a)   = e3_a*der(n2_a)/length_n2_a       // e3_a*e2_a = 0
                       = e3_a*cross(n1_a, der(eRod_a))/length_n2_a
                       = e3_a*cross(n1_a, der(rRod_a) - eRod_a*(eRod_a*der(rRod_a)))/(length_n2_a*rodLength)
                       = e3_a*cross(n1_a, der(rRod_a))/(length_n2_a*rodLength)
   Furthermore, we have:
     rRod_a            = resolve2(frame_a.R, rRod_0);
     der(rRod_a)       = resolve2(frame_a.R, der(rRod_0)) - cross(frame_a.R.w, rRod_a));
*/
  der_rRod_a_L = (Modelica.Mechanics.MultiBody.Frames.resolve2(frame_a.R, der(rRod_0)) - cross(frame_a.R.w, rRod_a)) / rodLength;
  w_rel_ia1 = {e3_a * cross(n1_a, der_rRod_a_L) / length_n2_a, -e3_a * der_rRod_a_L, e2_a * der_rRod_a_L};
  R_rel_ia1 = Modelica.Mechanics.MultiBody.Frames.from_T(transpose([eRod_a, e2_a, e3_a]), w_rel_ia1);
  R_rel_ia2 = Modelica.Mechanics.MultiBody.Frames.from_T([eRod_ia, e2_ia, e3_ia], zeros(3));
  R_rel_ia = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(R_rel_ia1, R_rel_ia2);
  /*
  T_rel_ia = [eRod_ia, e2_ia, e3_ia]*transpose([eRod_a, e2_a, e3_a]);
  R_rel_ia = Frames.from_T(T_rel_ia,
    Frames.TransformationMatrices.angularVelocity2(T_rel_ia, der(T_rel_ia)));
*/
  // Compute kinematic quantities of frame_ia
  frame_ia.r_0 = frame_a.r_0;
  frame_ia.R = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(frame_a.R, R_rel_ia);
  /* In the following formulas f_a, f_b, f_ia, t_a, t_b, t_ia are
     the forces and torques at frame_a, frame_b, frame_ia, respectively,
     resolved in frame_a. e_x, e_y, e_z are the unit vectors resolved in frame_a.
     Torque balance at the rod around the origin of frame_a:
       0 = t_a + t_ia + cross(rRod_a, f_b)
     with
         rRod_a = rodLength*e_x
         f_b     = -f_rod*e_x + f_b[2]*e_y + f_b[3]*e_z
     follows:
       0 = t_a + t_ia + rodLength*(f_b[2]*e_z - f_b[3]*e_y)
     The projection of t_a with respect to universal joint axes vanishes:
       n1_a*t_a = 0
       e_y*t_a = 0
     Therefore:
        0 = n1_a*t_ia + rodLength*f_b[2]*(n1_a*e_z)
        0 = e_y*t_ia - rodLength*f_b[3]
     or
        f_b = -f_rod*e_x - e_y*(n1_a*t_ia)/(rodLength*(n1_a*e_z)) + e_z*(e_y*t_ia)/rodLength
     Force balance:
        0 = f_a + f_b + f_ia
  */
  f_ia_a = Modelica.Mechanics.MultiBody.Frames.resolve1(R_rel_ia, frame_ia.f);
  t_ia_a = Modelica.Mechanics.MultiBody.Frames.resolve1(R_rel_ia, frame_ia.t);
  // f_b_a1 is needed in aggregation joints to solve kinematic loops analytically
  f_b_a1 = -e2_a * (n1_a * t_ia_a / (rodLength * (n1_a * e3_a))) + e3_a * (e2_a * t_ia_a / rodLength);
  f_b_a = -f_rod * eRod_a + f_b_a1;
  frame_b.f = Modelica.Mechanics.MultiBody.Frames.resolveRelative(f_b_a, frame_a.R, frame_b.R);
  frame_b.t = zeros(3);
  zeros(3) = frame_a.f + f_b_a + f_ia_a;
  zeros(3) = frame_a.t + t_ia_a + cross(rRod_a, f_b_a);
  // Measure power for test purposes
  if checkTotalPower then
    totalPower = frame_a.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_a.R, der(frame_a.r_0)) + frame_b.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_b.R, der(frame_b.r_0)) + frame_ia.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_ia.R, der(frame_ia.r_0)) + frame_a.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_a.R) + frame_b.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_b.R) + frame_ia.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_ia.R);
  else
    totalPower = 0;
  end if;

  Modelica.Mechanics.MultiBody.Visualizers.FixedShape    shape(shapeType       = \"box\",
                                            lengthDirection = jointUS.eRod_ia,
                                            widthDirection  = jointUS.e2_ia,
                                            length          = jointUS.rodLength/2,
                                            width           = jointUS.rodLength/10);
<strong>equation</strong>
  <strong>connect</strong>(jointUS.frame_ia, shape.frame_a);
</pre></blockquote>
