  parameter Modelica.Units.SI.Position nAxis_ia[3] = {1, 0, 0} "Axis vector along line from origin of frame_a to origin of frame_b, resolved in frame_ia" ;
  parameter Modelica.Units.SI.Position s_offset = 0 "Relative distance offset (distance between frame_a and frame_b = s(t) + s_offset)";
