  input Types.Color rod2Color = rod1Color "Color of rod 2 connecting the revolute and the spherical joint" ;
  parameter Modelica.Units.SI.Diameter revoluteDiameter = world.defaultJointWidth "Diameter of cylinder representing the revolute joint" ;
