model JointUSP "Universal - spherical - prismatic joint aggregation (no constraints, no potential states)"
  import Modelica.Mechanics.MultiBody.Types;
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialTwoFramesDoubleSize;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_ia "Coordinate system at origin of frame_a fixed at connecting rod of universal and spherical joint" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_ib "Coordinate system at origin of frame_b fixed at connecting rod of spherical and prismatic joint" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_im "Coordinate system at origin of spherical joint fixed at connecting rod of spherical and prismatic joint" ;
  Modelica.Mechanics.Translational.Interfaces.Flange_a axis "1-dim. translational flange that drives the prismatic joint" ;
  Modelica.Mechanics.Translational.Interfaces.Flange_b bearing "1-dim. translational flange of the drive bearing of the prismatic joint" ;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Boolean showUniversalAxes = true "= true, if universal joint shall be visualized with two cylinders, otherwise with a sphere (provided animation=true)";
  parameter Types.Axis n1_a = {0, 0, 1} "Axis 1 of universal joint fixed and resolved in frame_a (axis 2 is orthogonal to axis 1 and to rod 1)" ;
  parameter Types.Axis n_b = {-1, 0, 0} "Axis of prismatic joint fixed and resolved in frame_b" ;
  parameter Modelica.Units.SI.Position rRod1_ia[3] = {1, 0, 0} "Vector from origin of frame_a to spherical joint, resolved in frame_ia" ;
  parameter Modelica.Units.SI.Position rRod2_ib[3] = {-1, 0, 0} "Vector from origin of frame_ib to spherical joint, resolved in frame_ib (frame_ib is parallel to frame_b)" ;
  parameter Modelica.Units.SI.Position s_offset = 0 "Relative distance offset of prismatic joint (distance between the prismatic joint frames = s(t) + s_offset)";
  parameter Modelica.Units.SI.Position s_guess = 0 "Select the configuration such that at initial time |s(t0)-s_guess| is minimal";
  parameter Modelica.Units.SI.Diameter sphereDiameter = world.defaultJointLength "Diameter of the spheres representing the universal and the spherical joint" ;
  input Types.Color sphereColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of the spheres representing the universal and the spherical joint" ;
  parameter Modelica.Units.SI.Diameter rod1Diameter = sphereDiameter / Types.Defaults.JointRodDiameterFraction "Diameter of rod 1 connecting the universal and the spherical joint" ;
  input Types.Color rod1Color = Modelica.Mechanics.MultiBody.Types.Defaults.RodColor "Color of rod 1 connecting the universal and the spherical joint" ;
  parameter Modelica.Units.SI.Diameter rod2Diameter = rod1Diameter "Diameter of rod 2 connecting the prismatic and the spherical joint" ;
  input Types.Color rod2Color = rod1Color "Color of rod 2 connecting the prismatic and the spherical joint" ;
  parameter Types.Axis boxWidthDirection = {0, 1, 0} "Vector in width direction of prismatic joint, resolved in frame_b" ;
  parameter Modelica.Units.SI.Distance boxWidth = world.defaultJointWidth "Width of prismatic joint box" ;
  parameter Modelica.Units.SI.Distance boxHeight = boxWidth "Height of prismatic joint box" ;
  input Types.Color boxColor = sphereColor "Color of prismatic joint box" ;
  input Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
  parameter Modelica.Units.SI.Distance cylinderLength = world.defaultJointLength "Length of cylinders representing the two universal joint axes" ;
  parameter Modelica.Units.SI.Distance cylinderDiameter = world.defaultJointWidth "Diameter of cylinders representing the two universal joint axes" ;
  input Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of cylinders representing the two universal joint axes" ;
  parameter Boolean checkTotalPower = false "= true, if total power flowing into this component shall be determined (must be zero)" ;
  final parameter Real eRod1_ia[3](each final unit = "1") = rod1.eRod_ia "Unit vector from origin of frame_a to origin of spherical joint, resolved in frame_ia";
  final parameter Real e2_ia[3](each final unit = "1") = rod1.e2_ia "Unit vector in direction of axis 2 of universal joint, resolved in frame_ia";
  final parameter Modelica.Units.SI.Distance rod1Length = rod1.rodLength "Length of rod 1 (= distance between universal and spherical joint)";
  Modelica.Units.SI.Force f_rod "Constraint force in direction of the rod (positive, if rod is pressed)";
  Modelica.Units.SI.Power totalPower "Total power flowing into this element, if checkTotalPower=true (otherwise dummy)";
  Modelica.Mechanics.MultiBody.Joints.Internal.PrismaticWithLengthConstraint prismatic(animation = animation, length = rod1.rodLength, n = n_b, s_offset = s_offset, s_guess = s_guess, boxWidthDirection = boxWidthDirection, boxWidth = boxWidth, boxHeight = boxHeight, boxColor = boxColor, specularCoefficient = specularCoefficient) ;
  Modelica.Mechanics.MultiBody.Joints.UniversalSpherical rod1(animation = animation, showUniversalAxes = showUniversalAxes, rRod_ia = rRod1_ia, n1_a = n1_a, sphereDiameter = sphereDiameter, sphereColor = sphereColor, rodWidth = rod1Diameter, rodHeight = rod1Diameter, rodColor = rod1Color, specularCoefficient = specularCoefficient, cylinderLength = cylinderLength, cylinderDiameter = cylinderDiameter, cylinderColor = cylinderColor, kinematicConstraint = false, constraintResidue = rod1.f_rod - f_rod) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation rod2(animation = animation, r = rRod2_ib, width = rod2Diameter, height = rod2Diameter, specularCoefficient = specularCoefficient, color = rod2Color) ;
  Modelica.Mechanics.MultiBody.Sensors.RelativePosition relativePosition(resolveInFrame = Types.ResolveInFrameAB.frame_a) ;
  Modelica.Blocks.Sources.Constant position_b[3](k = rRod2_ib) ;
protected
  Real aux "Denominator used to compute force in rod connecting universal and spherical joint";
equation
  /* Compute the unknown force in rod1 connecting the universal and
     the spherical joint by a force balance at the prismatic joint
        0 = -prismatic.frame_b.f + frame_ib.f + frame_im.f - rod1.frame_b.f
     The force at rod1.frame_b is split into two parts:
        rod1.frame_b.f = Frames.resolve2(rod1.R_rel, rod1.f_b_a1 - rod1.f_rod*rod1.eRod_a)
     where rod1.f_rod is the unknown force in rod1.
     The condition is that the projection of the force in the prismatic
     joint along the axis of its translation axis is equal to the driving
     axis force in the flange:
       -prismatic.f = prismatic.e*prismatic.frame_b.f
     Therefore, we have with e=prismatic.e and f=prismatic.f
       -f = e*(frame_ib.f + frame_im.f
               - Frames.resolve2(rod1.R_rel, rod1.f_b_a1 - rod1.f_rod*rod1.eRod_a))
          = e*(frame_ib.f + frame_im.f - Frames.resolve2(rod1.R_rel, rod1.f_b_a1)
              + rod1.f_rod*Frames.resolve2(rod1.R_rel, rod1.eRod_a))
     Solving this equation for f_rod results in
       rod1.f_rod = -(f+e*(frame_ib.f + frame_im.f - Frames.resolve2(rod1.R_rel, rod1.f_b_a1)))
                   /(e*Frames.resolve2(rod1.R_rel, rod1.eRod_a))
     Additionally, a guard against division by zero is introduced
  */
  aux = prismatic.e * Modelica.Mechanics.MultiBody.Frames.resolveRelative(rod1.eRod_a, rod1.frame_a.R, rod1.frame_b.R);
  f_rod = (-prismatic.f - prismatic.e * (frame_ib.f + frame_im.f - Modelica.Mechanics.MultiBody.Frames.resolveRelative(rod1.f_b_a1, rod1.frame_a.R, rod1.frame_b.R))) / noEvent(if abs(aux) < 1e-10 then 1e-10 else aux);
  // Measure power for test purposes
  if checkTotalPower then
    totalPower = frame_a.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_a.R, der(frame_a.r_0)) + frame_b.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_b.R, der(frame_b.r_0)) + frame_ia.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_ia.R, der(frame_ia.r_0)) + frame_ib.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_ib.R, der(frame_ib.r_0)) + frame_im.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_im.R, der(frame_im.r_0)) + frame_a.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_a.R) + frame_b.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_b.R) + frame_ia.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_ia.R) + frame_ib.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_ib.R) + frame_im.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_im.R) + axis.f * der(axis.s) + bearing.f * der(bearing.s);
  else
    totalPower = 0;
  end if;
  connect(prismatic.frame_b, rod2.frame_a) ;
  connect(rod2.frame_b, rod1.frame_b) ;
  connect(prismatic.frame_a, frame_b) ;
  connect(rod2.frame_a, frame_ib) ;
  connect(rod1.frame_a, frame_a) ;
  connect(relativePosition.frame_b, frame_a) ;
  connect(relativePosition.frame_a, frame_b) ;
  connect(rod2.frame_b, frame_im) ;
  connect(rod1.frame_ia, frame_ia) ;
  connect(position_b.y, prismatic.position_b) ;
  connect(prismatic.axis, axis) ;
  connect(prismatic.bearing, bearing) ;
  connect(relativePosition.r_rel, prismatic.position_a) ;

  Modelica.Mechanics.MultiBody.Visualizers.FixedShape     shape(shapeType       = \"box\",
                                             lengthDirection = jointUSP.eRod1_ia,
                                             widthDirection  = jointUSP.e2_ia,
                                             length          = jointUSP.rod1Length/2,
                                             width           = jointUSP.rod1Length/10);
<strong>equation</strong>
