Modelica.Mechanics: JointSSP (model)

This component consists of a spherical joint 1 at frame_a, a prismatic  joint at frame_b and a spherical joint 2 which is connected via rod 1 to the spherical joint 1 and via rod 2 to the prismatic joint, see the default animation in the following figure (the axes vectors are not part of the default animation):   

 Besides an optional point mass in the middle of rod 1, this joint aggregation has no mass and no inertia, and introduces neither constraints nor potential state variables. It should be used in kinematic loops whenever possible since the non-linear system of equations introduced by this joint aggregation is solved analytically (i.e., a solution is always computed, if a unique solution exists).   
 An additional frame_ib is present. It is fixed in rod 2 connecting the prismatic and the spherical joint at the side of the prismatic joint that is connected to this rod (= rod2.frame_a = prismatic.frame_a).   
 An additional frame_im is present. It is fixed in rod 2 connecting the prismatic and the spherical joint at the side of spherical joint 2 that is connected to this rod (= rod2.frame_b). It is always parallel to frame_ib .   
 The easiest way to define the parameters of this joint is by moving the MultiBody system in a reference configuration where all frames  of all components are parallel to each other (alternatively, at least frame_b and frame_ib of the JointSSP joint should be parallel to each other when defining an instance of this component).

Code:
model JointSSP "Spherical - spherical - prismatic joint aggregation with mass (no constraints, no potential states)"
  import Modelica.Mechanics.MultiBody.Types;
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialTwoFramesDoubleSize;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_ib "Coordinate system at origin of frame_b fixed at connecting rod of spherical and prismatic joint" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_im "Coordinate system at origin of spherical joint in the middle fixed at connecting rod of spherical and prismatic joint" ;
  Modelica.Mechanics.Translational.Interfaces.Flange_a axis "1-dim. translational flange that drives the prismatic joint" ;
  Modelica.Mechanics.Translational.Interfaces.Flange_b bearing "1-dim. translational flange of the drive bearing of the prismatic joint" ;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Boolean showMass = true "= true, if point mass on rod 1 shall be shown (provided animation = true and rod1Mass > 0)";
  parameter Modelica.Units.SI.Length rod1Length(min = Modelica.Constants.eps, start = 1) "Distance between the origins of the two spherical joints";
  parameter Modelica.Units.SI.Mass rod1Mass(min = 0) = 0 "Mass of rod 1 (= point mass located in middle of rod connecting the two spherical joints)";
  parameter Types.Axis n_b = {0, 0, 1} "Axis of prismatic joint fixed and resolved in frame_b";
  parameter Modelica.Units.SI.Position rRod2_ib[3] = {1, 0, 0} "Vector from origin of frame_ib to spherical joint in the middle, resolved in frame_ib";
  parameter Modelica.Units.SI.Position s_offset = 0 "Relative distance offset of prismatic joint (distance between frame_b and frame_ib = s(t) + s_offset)";
  parameter Modelica.Units.SI.Position s_guess = 0 "Select the configuration such that at initial time |s(t0)-s_guess| is minimal";
  parameter Modelica.Units.SI.Diameter sphereDiameter = world.defaultJointLength "Diameter of the spheres representing the two spherical joints" ;
  input Types.Color sphereColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of the spheres representing the two spherical joints" ;
  parameter Modelica.Units.SI.Diameter rod1Diameter = sphereDiameter / Types.Defaults.JointRodDiameterFraction "Diameter of rod 1 connecting the two spherical joints" ;
  input Types.Color rod1Color = Modelica.Mechanics.MultiBody.Types.Defaults.RodColor "Color of rod 1 connecting the two spherical joint" ;
  parameter Modelica.Units.SI.Diameter rod2Diameter = rod1Diameter "Diameter of rod 2 connecting the revolute joint and spherical joint 2" ;
  input Types.Color rod2Color = rod1Color "Color of rod 2 connecting the revolute joint and spherical joint 2" ;
  parameter Types.Axis boxWidthDirection = {0, 1, 0} "Vector in width direction of prismatic joint box, resolved in frame_b" ;
  parameter Modelica.Units.SI.Distance boxWidth = world.defaultJointWidth "Width of prismatic joint box" ;
  parameter Modelica.Units.SI.Distance boxHeight = boxWidth "Height of prismatic joint box" ;
  input Types.Color boxColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of prismatic joint box" ;
  input Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
  parameter Boolean checkTotalPower = false "= true, if total power flowing into this component shall be determined (must be zero)" ;
  Real aux "Denominator used to compute force in rod connecting universal and spherical joint";
  Modelica.Units.SI.Force f_rod "Constraint force in direction of the rod (positive, if rod is pressed)";
  Modelica.Units.SI.Power totalPower "Total power flowing into this element, if checkTotalPower=true (otherwise dummy)";
  Modelica.Mechanics.MultiBody.Joints.Internal.PrismaticWithLengthConstraint prismatic(animation = animation, length = rod1Length, n = n_b, s_offset = s_offset, s_guess = s_guess, boxWidthDirection = boxWidthDirection, boxWidth = boxWidth, boxHeight = boxHeight, specularCoefficient = specularCoefficient, boxColor = boxColor) ;
  Modelica.Mechanics.MultiBody.Joints.SphericalSpherical rod1(animation = animation, showMass = showMass, m = rod1Mass, rodLength = rod1Length, rodDiameter = rod1Diameter, sphereDiameter = sphereDiameter, rodColor = rod1Color, kinematicConstraint = false, specularCoefficient = specularCoefficient, sphereColor = sphereColor, constraintResidue = rod1.f_rod - f_rod) ;
  Modelica.Mechanics.MultiBody.Parts.FixedTranslation rod2(animation = animation, width = rod2Diameter, height = rod2Diameter, specularCoefficient = specularCoefficient, color = rod2Color, r = rRod2_ib) ;
  Modelica.Mechanics.MultiBody.Sensors.RelativePosition relativePosition(resolveInFrame = Types.ResolveInFrameAB.frame_a) ;
  Modelica.Blocks.Sources.Constant position_b[3](k = rRod2_ib) ;
equation
  /* Compute the unknown force in the rod of the rod1 joint
     by a force balance:
       0 = frame_b.f + frame_ib.f + frame_im.f +
           Frames.resolve2(rod1.R_rel, rod1.f_rod*rod1.eRod_a)
     The condition is that the projection of the force in the prismatic
     joint along the axis of the prismatic joint is equal to the driving
     axis force in the flange:
       -prismatic.f = prismatic.e*frame_b.f
     Therefore, we have with e=prismatic.e and f=prismatic.f
        f = e*(frame_ib.f + frame_im.f +
               Frames.resolve2(rod1.R_rel, rod1.f_rod*rod1.eRod_a))
          = e*(frame_ib.f + frame_im.f +
               rod1.f_rod*Frames.resolve2(rod1.R_rel, rod1.eRod_a))
     Solving this equation for f_rod results in
       rod1.f_rod = (f - e*(frame_ib.f + frame_im.f))
                    / (e*Frames.resolve2(rod1.R_rel, rod1.eRod_a))
     Additionally, a guard against division by zero is introduced
  */
  aux = prismatic.e * Modelica.Mechanics.MultiBody.Frames.resolveRelative(rod1.eRod_a, rod1.frame_a.R, rod1.frame_b.R);
  f_rod = (-prismatic.f - prismatic.e * (frame_ib.f + frame_im.f)) / noEvent(if abs(aux) < 1e-10 then 1e-10 else aux);
  // Measure power for test purposes
  if checkTotalPower then
    totalPower = frame_a.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_a.R, der(frame_a.r_0)) + frame_b.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_b.R, der(frame_b.r_0)) + frame_ib.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_ib.R, der(frame_ib.r_0)) + frame_im.f * Modelica.Mechanics.MultiBody.Frames.resolve2(frame_im.R, der(frame_im.r_0)) + frame_a.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_a.R) + frame_b.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_b.R) + frame_ib.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_ib.R) + frame_im.t * Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_im.R) + axis.f * der(axis.s) + bearing.f * der(bearing.s) + (-rod1Mass) * (der(rod1.v_CM_0) - world.gravityAcceleration(rod1.r_CM_0)) * rod1.v_CM_0;
  else
    totalPower = 0;
  end if;
  connect(prismatic.frame_b, rod2.frame_a) ;
  connect(rod2.frame_b, rod1.frame_b) ;
  connect(prismatic.frame_a, frame_b) ;
  connect(rod2.frame_a, frame_ib) ;
  connect(rod1.frame_a, frame_a) ;
  connect(relativePosition.frame_b, frame_a) ;
  connect(relativePosition.frame_a, frame_b) ;
  connect(position_b.y, prismatic.position_b) ;
  connect(prismatic.axis, axis) ;
  connect(prismatic.bearing, bearing) ;
  connect(rod2.frame_b, frame_im) ;
  connect(relativePosition.r_rel, prismatic.position_a) ;

