model RevoluteWithLengthConstraint "Revolute joint where the rotation angle is computed from a length constraint (1 degree-of-freedom, no potential state)"
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialTwoFrames;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a axis "1-dim. rotational flange that drives the joint" ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_b bearing "1-dim. rotational flange of the drive bearing" ;
  Modelica.Blocks.Interfaces.RealInput position_a[3](each final quantity = "Length", each final unit = "m") "Position vector from frame_a to frame_a side of length constraint, resolved in frame_a of revolute joint" ;
  Modelica.Blocks.Interfaces.RealInput position_b[3](each final quantity = "Length", each final unit = "m") "Position vector from frame_b to frame_b side of length constraint, resolved in frame_b of revolute joint" ;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Modelica.Units.SI.Position lengthConstraint(start = 1) "Fixed length of length constraint";
  parameter Modelica.Mechanics.MultiBody.Types.Axis n = {0, 0, 1} "Axis of rotation resolved in frame_a (= same as in frame_b)" ;
  parameter Modelica.Units.NonSI.Angle_deg phi_offset = 0 "Relative angle offset (angle = phi + from_deg(phi_offset))";
  parameter Modelica.Units.NonSI.Angle_deg phi_guess = 0 "Select the configuration such that at initial time |phi - from_deg(phi_guess)| is minimal";
  parameter Modelica.Units.SI.Distance cylinderLength = world.defaultJointLength "Length of cylinder representing the joint axis" ;
  parameter Modelica.Units.SI.Distance cylinderDiameter = world.defaultJointWidth "Diameter of cylinder representing the joint axis" ;
  input Modelica.Mechanics.MultiBody.Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.JointColor "Color of cylinder representing the joint axis" ;
  input Modelica.Mechanics.MultiBody.Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
  final parameter Boolean positiveBranch(fixed = false) "Based on phi_guess, selection of one of the two solutions of the non-linear constraint equation";
  final parameter Real e[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(n) "Unit vector in direction of rotation axis, resolved in frame_a";
  Modelica.Units.SI.Angle phi "Rotation angle of revolute joint";
  Modelica.Mechanics.MultiBody.Frames.Orientation R_rel "Relative orientation object from frame_a to frame_b";
  Modelica.Units.SI.Angle angle "= phi + from_deg(phi_offset) (relative rotation angle between frame_a and frame_b)";
  Modelica.Units.SI.Torque tau "= axis.tau (driving torque in the axis)";
protected
  Modelica.Units.SI.Position r_a[3] = position_a "Position vector from frame_a to frame_a side of length constraint, resolved in frame_a of revolute joint";
  Modelica.Units.SI.Position r_b[3] = position_b "Position vector from frame_b to frame_b side of length constraint, resolved in frame_b of revolute joint";
  Real e_r_a "Projection of r_a on e";
  Real e_r_b "Projection of r_b on e";
  Real A "Coefficient A of equation: A*cos(phi) + B*sin(phi) + C = 0";
  Real B "Coefficient B of equation: A*cos(phi) + B*sin(phi) + C = 0";
  Real C "Coefficient C of equation: A*cos(phi) + B*sin(phi) + C = 0";
  Real k1 "Constant of quadratic equation";
  Real k2 "Constant of quadratic equation";
  Real k1a(start = 1);
  Real k1b;
  Real kcos_angle "= k1*cos(angle)";
  Real ksin_angle "= k1*sin(angle)";
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape cylinder(shapeType = "cylinder", color = cylinderColor, specularCoefficient = specularCoefficient, length = cylinderLength, width = cylinderDiameter, height = cylinderDiameter, lengthDirection = e, widthDirection = {0, 1, 0}, r_shape = -e * (cylinderLength / 2), r = frame_a.r_0, R = frame_a.R) if world.enableAnimation and animation;

  function selectBranch "Determine branch which is closest to initial angle=0"
    extends Modelica.Icons.Function;
    input Modelica.Units.SI.Length L "Length of length constraint";
    input Real e[3](each final unit = "1") "Unit vector along axis of rotation, resolved in frame_a (= same in frame_b)";
    input Modelica.Units.SI.Angle angle_guess "Select the configuration such that at initial time |angle-angle_guess| is minimal (angle=0: frame_a and frame_b coincide)";
    input Modelica.Units.SI.Position r_a[3] "Position vector from frame_a to frame_a side of length constraint, resolved in frame_a of revolute joint";
    input Modelica.Units.SI.Position r_b[3] "Position vector from frame_b to frame_b side of length constraint, resolved in frame_b of revolute joint";
    output Boolean positiveBranch "Branch of the initial solution";
  protected
    Real e_r_a "Projection of r_a on e";
    Real e_r_b "Projection of r_b on e";
    Real A "Coefficient A of equation: A*cos(phi) + B*sin(phi) + C = 0";
    Real B "Coefficient B of equation: A*cos(phi) + B*sin(phi) + C = 0";
    Real C "Coefficient C of equation: A*cos(phi) + B*sin(phi) + C = 0";
    Real k1 "Constant of quadratic equation";
    Real k2 "Constant of quadratic equation";
    Real k1a;
    Real k1b;
    Real kcos1 "k1*cos(angle1)";
    Real ksin1 "k1*sin(angle1)";
    Real kcos2 "k2*cos(angle2)";
    Real ksin2 "k2*sin(angle2)";
    Modelica.Units.SI.Angle angle1 "Solution 1 of nonlinear equation";
    Modelica.Units.SI.Angle angle2 "Solution 2 of nonlinear equation";
  algorithm
    /* The position vector r_rel from frame_a to frame_b of the length constraint
       element, resolved in frame_b of the revolute joint is given by
       (T_rel is the planar transformation matrix from frame_a to frame_b of
        the revolute joint):
          r_rel = r_b - T_rel*r_a
       The length constraint can therefore be formulated as:
          r_rel*r_rel = L*L
       with
          (r_b - T_rel*r_a)*(r_b - T_rel*r_a)
             = r_b*r_b - 2*r_b*T_rel*r_a + r_a*transpose(T_rel)*T_rel*r_a
             = r_b*r_b + r_a*r_a - 2*r_b*T_rel*r_a
       follows
          (1) 0 = r_a*r_a + r_b*r_b - 2*r_b*T_rel*r_a - L*L
       The vectors r_a, r_b and parameter L are NOT a function of
       the angle of the revolute joint. Since T_rel = T_rel(angle) is a function
       of the unknown angle of the revolute joint, this is a non-linear
       equation in this angle.
          T_rel = [e]*transpose([e]) + (identity(3) - [e]*transpose([e]))*cos(angle)
                  - skew(e)*sin(angle);
       with
          r_b*T_rel*r_a
             = r_b*(e*(e*r_a) + (r_a - e*(e*r_a))*cos(angle) - cross(e,r_a)*sin(angle)
             = (e*r_b)*(e*r_a) + (r_b*r_a - (e*r_b)*(e*r_a))*cos(angle) - r_b*cross(e,r_a)*sin(angle)
       follows for the constraint equation (1)
          (2) 0 = r_a*r_a + r_b*r_b - L*L
                  - 2*(e*r_b)*(e*r_a)
                  - 2*(r_b*r_a - (e*r_b)*(e*r_a))*cos(angle)
                  + 2*r_b*cross(e,r_a)*sin(angle)
       or
          (3) A*cos(angle) + B*sin(angle) + C = 0
       with
              A = -2*(r_b*r_a - (e*r_b)*(e*r_a))
              B = 2*r_b*cross(e,r_a)
              C = r_a*r_a + r_b*r_b - L*L - 2*(e*r_b)*(e*r_a)
       Equation (3) is solved by computing sin(angle) and cos(angle)
       independently from each other. This allows to compute
       angle in the range: -180 deg <= angle <= 180 deg
    */
    e_r_a := e * r_a;
    e_r_b := e * r_b;
    A := -2 * (r_b * r_a - e_r_b * e_r_a);
    B := 2 * r_b * cross(e, r_a);
    C := r_a * r_a + r_b * r_b - L * L - 2 * e_r_b * e_r_a;
    k1 := A * A + B * B;
    k1a := k1 - Modelica.Constants * Modelica.Constants;
    assert(k1a > 1e-10, "
Singular position of loop (either no or two analytic solutions;
the mechanism has lost one-degree-of freedom in this position).
Try first to use another Modelica.Mechanics.MultiBody.Joints.Assemblies.JointXXX component.
In most cases it is best that the joints outside of the JointXXX
component are revolute and NOT prismatic joints. If this also
lead to singular positions, it could be that this kinematic loop
cannot be solved analytically. In this case you have to build
up the loop with basic joints (NO aggregation JointXXX components)
and rely on dynamic state selection, i.e., during simulation
the states will be dynamically selected in such a way that in no
position a degree of freedom is lost.
");
    k1b := max(k1a, 1.0e-12);
    k2 := sqrt(k1b);
    kcos1 := -A * Modelica.Constants + B * k2;
    ksin1 := -B * Modelica.Constants - A * k2;
    angle1 := Modelica.Math.atan2(ksin1, kcos1);
    kcos2 := -A * Modelica.Constants - B * k2;
    ksin2 := -B * Modelica.Constants + A * k2;
    angle2 := Modelica.Math.atan2(ksin2, kcos2);
    if abs(angle1 - angle_guess) <= abs(angle2 - angle_guess) then
      positiveBranch := true;
    else
      positiveBranch := false;
    end if;
  end selectBranch;
initial equation
  positiveBranch = selectBranch(lengthConstraint, e, Modelica.Units.Conversions.from_deg(phi_offset + phi_guess), r_a, r_b);
equation
  Connections.branch(frame_a.R, frame_b.R);
  axis.tau = tau;
  axis.phi = phi;
  bearing.phi = 0;
  angle = Modelica.Units.Conversions.from_deg(phi_offset) + phi;
  // transform kinematic quantities from frame_a to frame_b
  frame_b.r_0 = frame_a.r_0;
  R_rel = Modelica.Mechanics.MultiBody.Frames.planarRotation(e, angle, der(angle));
  frame_b.R = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(frame_a.R, R_rel);
  // Force and torque balance
  zeros(3) = frame_a.f + Modelica.Mechanics.MultiBody.Frames.resolve1(R_rel, frame_b.f);
  zeros(3) = frame_a.t + Modelica.Mechanics.MultiBody.Frames.resolve1(R_rel, frame_b.t);
  // Compute rotation angle (details, see function "selectBranch")
  e_r_a = e * r_a;
  e_r_b = e * r_b;
  A = -2 * (r_b * r_a - e_r_b * e_r_a);
  B = 2 * r_b * cross(e, r_a);
  Modelica.Constants = r_a * r_a + r_b * r_b - lengthConstraint * lengthConstraint - 2 * e_r_b * e_r_a;
  k1 = A * A + B * B;
  k1a = k1 - Modelica.Constants * Modelica.Constants;
  assert(k1a > 1e-10, "
Singular position of loop (either no or two analytic solutions;
the mechanism has lost one-degree-of freedom in this position).
Try first to use another Modelica.Mechanics.MultiBody.Joints.Assemblies.JointXXX component.
In most cases it is best that the joints outside of the JointXXX
component are revolute and NOT prismatic joints. If this also
lead to singular positions, it could be that this kinematic loop
cannot be solved analytically. In this case you have to build
up the loop with basic joints (NO aggregation JointXXX components)
and rely on dynamic state selection, i.e., during simulation
the states will be dynamically selected in such a way that in no
position a degree of freedom is lost.
");
  k1b = Modelica.Mechanics.MultiBody.Frames.Internal.maxWithoutEvent(k1a, 1.0e-12);
  k2 = sqrt(k1b);
  kcos_angle = -A * Modelica.Constants + (if positiveBranch then B else -B) * k2;
  ksin_angle = -B * Modelica.Constants + (if positiveBranch then -A else A) * k2;
  angle = Modelica.Math.atan2(ksin_angle, kcos_angle);

end RevoluteWithLengthConstraint;

