  Modelica.Units.SI.Velocity v_0[3] "Velocity of wheel center, resolved in world frame";
  Modelica.Units.SI.AngularVelocity w_0[3] "Angular velocity of wheel, resolved in world frame";
  Modelica.Units.SI.Velocity vContact_0[3] "Velocity of wheel contact point, resolved in world frame";
  // Utility vectors
  Real aux[3];
equation
  // Coordinate system at contact point (e_long_0, e_lat_0, e_n_0)
  e_n_0 = {0, 0, 1};
  e_axis_0 = Frames.resolve1(frame_a.R, {0, 1, 0});
  aux = cross(e_n_0, e_axis_0);
  e_long_0 = aux / Modelica.Math.Vectors.length(aux);
  e_lat_0 = cross(e_long_0, e_n_0);
  // Slip velocities
  rContact_0 = {0, 0, -radius};
  v_0 = der(frame_a.r_0);
  w_0 = Frames.angularVelocity1(frame_a.R);
