model Rotor1D "1D inertia attachable on 3-dim. bodies (3D dynamic effects are taken into account if world.driveTrainMechanics3D=true)"
  parameter Boolean animation = true "= true, if animation shall be enabled (show rotor as cylinder)";
  parameter Modelica.Units.SI.Inertia J(min = 0, start = 1) "Moment of inertia of rotor around its axis of rotation";
  parameter Modelica.Mechanics.MultiBody.Types.Axis n = {1, 0, 0} "Axis of rotation resolved in frame_a" ;
  parameter Modelica.Units.SI.Position r_center[3] = zeros(3) "Position vector from origin of frame_a to center of cylinder" ;
  parameter Modelica.Units.SI.Distance cylinderLength = 2 * world.defaultJointLength "Length of cylinder representing the rotor" ;
  parameter Modelica.Units.SI.Distance cylinderDiameter = 2 * world.defaultJointWidth "Diameter of cylinder representing the rotor" ;
  input Modelica.Mechanics.MultiBody.Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.RodColor "Color of cylinder representing the rotor" ;
  input Modelica.Mechanics.MultiBody.Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
  parameter StateSelect stateSelect = StateSelect.default "Priority to use rotor angle (phi) and rotor speed (w) as states" ;
  parameter Boolean exact = true "= true, if exact calculations; false if influence of bearing on rotor acceleration is neglected to avoid an algebraic loop" ;
  Modelica.Units.SI.Angle phi(start = 0, stateSelect = stateSelect) "Rotation angle of rotor with respect to frame_a (= flange_a.phi = flange_b.phi)";
  Modelica.Units.SI.AngularVelocity w(start = 0, stateSelect = stateSelect) "Angular velocity of rotor with respect to frame_a";
  Modelica.Units.SI.AngularAcceleration a(start = 0) "Angular acceleration of rotor with respect to frame_a";
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flange_a "(left) driving flange (flange axis directed INTO cut plane)" ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_b flange_b "(right) driven flange (flange axis directed OUT OF cut plane)" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a if world.driveTrainMechanics3D "Frame in which rotor housing is fixed (connector is removed, if world.driveTrainMechanics3D=false)" ;

  encapsulated model RotorWith3DEffects "1D inertia attachable on 3-dim. bodies (3D dynamic effects are taken into account)"
    import Modelica;
    import Modelica.Units.SI;
    import Modelica.Mechanics.MultiBody.Frames;
    import Modelica.Mechanics.MultiBody.Types;
    parameter Boolean animation = true "= true, if animation shall be enabled (show rotor as cylinder)";
    parameter Modelica.Units.SI.Inertia J(min = 0) = 1 "Moment of inertia of rotor around its axis of rotation";
    parameter Modelica.Mechanics.MultiBody.Types.Axis n = {1, 0, 0} "Axis of rotation resolved in frame_a";
    parameter Modelica.Units.SI.Position r_center[3] = zeros(3) "Position vector from origin of frame_a to center of cylinder" ;
    parameter Modelica.Units.SI.Distance cylinderLength = 2 * world.defaultJointLength "Length of cylinder representing the rotor" ;
    parameter Modelica.Units.SI.Distance cylinderDiameter = 2 * world.defaultJointWidth "Diameter of cylinder representing the rotor" ;
    input Modelica.Mechanics.MultiBody.Types.Color cylinderColor = Modelica.Mechanics.MultiBody.Types.Defaults.RodColor "Color of cylinder representing the rotor" ;
    input Modelica.Mechanics.MultiBody.Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
    parameter StateSelect stateSelect = StateSelect.default "Priority to use rotor angle (phi) and rotor speed (w) as states" ;
    parameter Boolean exact = true "= true, if exact calculations; false if influence of bearing on rotor acceleration is neglected to avoid an algebraic loop" ;
    Modelica.Units.SI.AngularVelocity w_a[3] "Angular velocity of frame_a, resolved in frame_a";
    Modelica.Units.SI.Angle phi(start = 0, final stateSelect = stateSelect) "Rotation angle of rotor with respect to frame_a (= flange_a.phi = flange_b.phi)" ;
    Modelica.Units.SI.AngularVelocity w(start = 0, stateSelect = stateSelect) "Angular velocity of rotor with respect to frame_a" ;
    Modelica.Units.SI.AngularAcceleration a(start = 0) "Angular acceleration of rotor with respect to frame_a" ;
    Modelica.Mechanics.Rotational.Interfaces.Flange_a flange_a "(left) driving flange (flange axis directed INTO cut plane)" ;
    Modelica.Mechanics.Rotational.Interfaces.Flange_b flange_b "(right) driven flange (flange axis directed OUT OF cut plane)" ;
    Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a "Frame in which rotor housing is fixed" ;
  protected
    outer Modelica.Mechanics.MultiBody.World world;
    parameter Real e[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(n) "Unit vector in direction of rotor axis, resolved in frame_a";
    parameter Modelica.Units.SI.Inertia nJ[3] = J * e;
    Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape cylinder(shapeType = "cylinder", color = cylinderColor, specularCoefficient = specularCoefficient, length = cylinderLength, width = cylinderDiameter, height = cylinderDiameter, lengthDirection = n, widthDirection = {0, 1, 0}, extra = 1, r_shape = r_center - e * (cylinderLength / 2), r = frame_a.r_0, R = Modelica.Mechanics.MultiBody.Frames.absoluteRotation(frame_a.R, Modelica.Mechanics.MultiBody.Frames.planarRotation(e, phi, 0))) if world.enableAnimation and animation;
  equation
    phi = flange_a.phi;
    phi = flange_b.phi;
    w = der(phi);
    a = der(w);
    w_a = Modelica.Mechanics.MultiBody.Frames.angularVelocity2(frame_a.R);
    if exact then
      J * a = flange_a.tau + flange_b.tau - nJ * der(w_a);
    else
      J * a = flange_a.tau + flange_b.tau;
    end if;
    /* Reaction torque:
        t = n*(J*a - flange_a.tau - flange_b.tau) + cross(w_a, nJ*w)

     Since
        J*a = flange_a.tau + flange_b.tau - nJ*der(w_a);

     the reaction torque can be simplified to
        t = n*(- nJ*der(w_a)) + cross(w_a, nJ*w)

  */
    frame_a.f = zeros(3);
    frame_a.t = cross(w_a, nJ * w) - e * (nJ * der(w_a));

  end RotorWith3DEffects;
protected
  outer Modelica.Mechanics.MultiBody.World world;
  parameter Real e[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(n) "Unit vector in direction of rotor axis, resolved in frame_a";
