  Modelica.Mechanics.Rotational.Components.Inertia inertia(J = J, stateSelect = StateSelect.never) if not world.driveTrainMechanics3D ;
  RotorWith3DEffects rotorWith3DEffects(animation = animation, J = J, n = n, r_center = r_center, cylinderLength = cylinderLength, cylinderDiameter = cylinderDiameter, cylinderColor = cylinderColor, specularCoefficient = specularCoefficient, exact = exact, stateSelect = StateSelect.never) if world.driveTrainMechanics3D ;
equation
  phi = flange_a.phi;
  w = der(phi);
  a = der(w);
  connect(inertia.flange_a, flange_a) ;
  connect(inertia.flange_b, flange_b) ;
  connect(rotorWith3DEffects.flange_b, flange_b) ;
  connect(rotorWith3DEffects.flange_a, flange_a) ;
  connect(rotorWith3DEffects.frame_a, frame_a) ;

end Rotor1D;

modelica://Modelica.Mechanics/BevelGear1:
Modelica.Mechanics: BevelGear1D (model)

This component is used to model a 1-dim. gearbox with non-parallel axes (defined by parameters n_a , n_b ). A 3-dim. bearing frame is necessary to reflect the correct support torque, as the axes of rotation of flange_a and  flange_b and the direction of the support torque vector are different in general.  
Note: The name BevelGear1D is kept only for simplicity. Regardless, this component could be used to model any kind of gearbox with non-parallel axes. For a usage example, see Examples.Rotational3DEffects.BevelGear1D .  
Reference
  Schweiger , Christian ;  Otter , Martin:  Modelling 3D Mechanical Effects of 1-dim. Powertrains . In: Proceedings of the 3rd International Modelica Conference . Linköping : The Modelica Association and Linköping University, November 3-4, 2003, pp. 149-158

Code:
model BevelGear1D "1D gearbox with arbitrary shaft directions and 3-dim. bearing frame (3D dynamic effects are taken into account provided world.driveTrainMechanics3D=true)"
  extends Modelica.Mechanics.Rotational.Interfaces.PartialTwoFlanges;
  parameter Real ratio(start = 1) "Gear speed ratio";
  parameter Modelica.Mechanics.MultiBody.Types.Axis n_a = {1, 0, 0} "Axis of rotation of flange_a, resolved in frame_a" ;
  parameter Modelica.Mechanics.MultiBody.Types.Axis n_b = {1, 0, 0} "Axis of rotation of flange_b, resolved in frame_a" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a if world.driveTrainMechanics3D "Bearing frame" ;
protected
  outer Modelica.Mechanics.MultiBody.World world;
  parameter Real e_a[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(n_a) "Unit vector in direction of flange_a rotation axis";
  parameter Real e_b[3](each final unit = "1") = Modelica.Math.Vectors.normalizeWithAssert(n_b) "Unit vector in direction of flange_b rotation axis";

  encapsulated model Housing
    import Modelica;
    input Modelica.Units.SI.Torque t[3];
    Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a ;
  equation
    frame_a.f = zeros(3);
    frame_a.t = t;

  end Housing;

  Housing housing(t = -flange_a.tau * e_a - flange_b.tau * e_b) if world.driveTrainMechanics3D ;
equation
  flange_a.phi = ratio * flange_b.phi;
  0 = ratio * flange_a.tau + flange_b.tau;
  connect(housing.frame_a, frame_a) ;

end BevelGear1D;

