  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape cylinder(shapeType = "cylinder", color = cylinderColor, specularCoefficient = specularCoefficient, length = cylinderLength, width = cylinderDiameter, height = cylinderDiameter, lengthDirection = n, widthDirection = {0, 1, 0}, extra = 1, r_shape = r_center - e * (cylinderLength / 2), r = frame_a.r_0, R = Frames.absoluteRotation(frame_a.R, Frames.planarRotation(e, phi, 0))) if world.enableAnimation and animation;
equation
  phi = flange_a.phi;
  phi = flange_b.phi;
  w = der(phi);
  a = der(w);
  w_a = Frames.angularVelocity2(frame_a.R);
  if exact then
    J * a = flange_a.tau + flange_b.tau - nJ * der(w_a);
  else
    J * a = flange_a.tau + flange_b.tau;
  end if;
  /* Reaction torque:
        t = n*(J*a - flange_a.tau - flange_b.tau) + cross(w_a, nJ*w)

     Since
        J*a = flange_a.tau + flange_b.tau - nJ*der(w_a);

     the reaction torque can be simplified to
        t = n*(- nJ*der(w_a)) + cross(w_a, nJ*w)

  */
  frame_a.f = zeros(3);
  frame_a.t = cross(w_a, nJ * w) - e * (nJ * der(w_a));

end RotorWith3DEffects;

