model FixedShape2 "Visualizing an elementary shape with dynamically varying shape attributes (has two frame connectors)"
  import Modelica.Mechanics.MultiBody.Frames;
  import Modelica.Mechanics.MultiBody.Types;
  import Modelica.Units.Conversions.to_unit1;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_a frame_a "Coordinate system a (all shape definition vectors are resolved in this frame)" ;
  Modelica.Mechanics.MultiBody.Interfaces.Frame_b frame_b "Coordinate system b" ;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Types.ShapeType shapeType = "box" "Type of shape" ;
  input Modelica.Units.SI.Position r[3] = {1, 0, 0} "Vector from frame_a to frame_b resolved in frame_a";
  input Modelica.Units.SI.Position r_shape[3] = {0, 0, 0} "Vector from frame_a to shape origin, resolved in frame_a" ;
  input Types.Axis lengthDirection = to_unit1(r - r_shape) "Vector in length direction of shape, resolved in frame_a" ;
  input Types.Axis widthDirection = {0, 1, 0} "Vector in width direction of shape, resolved in frame_a" ;
  input Modelica.Units.SI.Length length = Modelica.Math.Vectors.length(r - r_shape) "Length of shape" ;
  input Modelica.Units.SI.Distance width = 0.1 "Width of shape" ;
  input Modelica.Units.SI.Distance height = width "Height of shape" ;
  input Types.ShapeExtra extra = 0.0 "Additional data for cylinder, cone, pipe, gearwheel and spring" ;
  input Types.Color color = {0, 128, 255} "Color of shape" ;
  input Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
protected
  outer Modelica.Mechanics.MultiBody.World world;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape shape(shapeType = shapeType, r_shape = r_shape, lengthDirection = lengthDirection, widthDirection = widthDirection, length = length, width = width, height = height, extra = extra, color = color, specularCoefficient = specularCoefficient, r = frame_a.r_0, R = frame_a.R) if world.enableAnimation and animation;
equation
  Connections.branch(frame_a.R, frame_b.R);
  assert(cardinality(frame_a) > 0 or cardinality(frame_b) > 0, "Neither connector frame_a nor frame_b of
MultiBody.Visualizers.FixedShape2 object is connected");
  frame_b.r_0 = frame_a.r_0 + Frames.resolve1(frame_a.R, r);
  frame_b.R = frame_a.R;
  /* Force and torque balance */
  zeros(3) = frame_a.f + frame_b.f;
  zeros(3) = frame_a.t + frame_b.t + cross(r, frame_b.f);

