Modelica.Mechanics: FixedFrame (model)

Model FixedFrame visualizes the three axes of its coordinate system frame_a together with appropriate axes labels. A typical example is shown in the following figure: 


 The sizes of the axes, the axes colors and the specular coefficient (= reflection factor for ambient light) can vary dynamically by providing appropriate expressions in the input fields of the parameter menu.

Code:
model FixedFrame "Visualizing a coordinate system including axes labels (visualization data may vary dynamically)"
  import Modelica.Mechanics.MultiBody.Types;
  extends Modelica.Mechanics.MultiBody.Interfaces.PartialVisualizer;
  parameter Boolean animation = true "= true, if animation shall be enabled";
  parameter Boolean showLabels = true "= true, if labels shall be shown" ;
  input Modelica.Units.SI.Distance length = 0.5 "Length of axes arrows" ;
  input Modelica.Units.SI.Distance diameter = length / world.defaultFrameDiameterFraction "Diameter of axes arrows" ;
  input Types.Color color_x = Modelica.Mechanics.MultiBody.Types.Defaults.FrameColor "Color of x-arrow" ;
  input Types.Color color_y = color_x "Color of y-arrow" ;
  input Types.Color color_z = color_x "Color of z-arrow" ;
  input Types.SpecularCoefficient specularCoefficient = world.defaultSpecularCoefficient "Reflection of ambient light (= 0: light is completely absorbed)" ;
protected
  parameter Boolean animation2 = world.enableAnimation and animation;
  parameter Boolean showLabels2 = world.enableAnimation and animation and showLabels;
  // Parameters to define axes
  Modelica.Units.SI.Length headLength = min(length, diameter * Types.Defaults.FrameHeadLengthFraction);
  Modelica.Units.SI.Length headWidth = diameter * Types.Defaults.FrameHeadWidthFraction;
  Modelica.Units.SI.Length lineLength = max(0, length - headLength);
  Modelica.Units.SI.Length lineWidth = diameter;
  // Parameters to define axes labels
  Modelica.Units.SI.Length scaledLabel = Modelica.Mechanics.MultiBody.Types.Defaults.FrameLabelHeightFraction * diameter;
  Modelica.Units.SI.Length labelStart = 1.05 * length;
  // x-axis
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape x_arrowLine(shapeType = "cylinder", length = lineLength, width = lineWidth, height = lineWidth, lengthDirection = {1, 0, 0}, widthDirection = {0, 1, 0}, color = color_x, specularCoefficient = specularCoefficient, r = frame_a.r_0, R = frame_a.R) if animation2;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape x_arrowHead(shapeType = "cone", length = headLength, width = headWidth, height = headWidth, lengthDirection = {1, 0, 0}, widthDirection = {0, 1, 0}, color = color_x, specularCoefficient = specularCoefficient, r = frame_a.r_0 + Modelica.Mechanics.MultiBody.Frames.resolve1(frame_a.R, {lineLength, 0, 0}), R = frame_a.R) if animation2;
  Modelica.Mechanics.MultiBody.Visualizers.Internal.Lines x_label(lines = scaledLabel * {[0, 0; 1, 1], [0, 1; 1, 0]}, diameter = diameter, color = color_x, specularCoefficient = specularCoefficient, r_lines = {labelStart, 0, 0}, n_x = {1, 0, 0}, n_y = {0, 1, 0}, r = frame_a.r_0, R = frame_a.R) if showLabels2;
  // y-axis
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape y_arrowLine(shapeType = "cylinder", length = lineLength, width = lineWidth, height = lineWidth, lengthDirection = {0, 1, 0}, widthDirection = {1, 0, 0}, color = color_y, specularCoefficient = specularCoefficient, r = frame_a.r_0, R = frame_a.R) if animation2;
  Modelica.Mechanics.MultiBody.Visualizers.Advanced.Shape y_arrowHead(shapeType = "cone", length = headLength, width = headWidth, height = headWidth, lengthDirection = {0, 1, 0}, widthDirection = {1, 0, 0}, color = color_y, specularCoefficient = specularCoefficient, r = frame_a.r_0 + Modelica.Mechanics.MultiBody.Frames.resolve1(frame_a.R, {0, lineLength, 0}), R = frame_a.R) if animation2;
  Modelica.Mechanics.MultiBody.Visualizers.Internal.Lines y_label(lines = scaledLabel * {[0, 0; 1, 1.5], [0, 1.5; 0.5, 0.75]}, diameter = diameter, color = color_y, specularCoefficient = specularCoefficient, r_lines = {0, labelStart, 0}, n_x = {0, 1, 0}, n_y = {-1, 0, 0}, r = frame_a.r_0, R = frame_a.R) if showLabels2;
