  parameter Integer n_rTire = 40 "Number of points along rTire" ;
  parameter Integer n_rCurvature = 20 "Number of points along rCurvature" ;
protected
  parameter Modelica.Units.SI.Radius rw = width / 2;
  parameter Modelica.Units.SI.Radius rCurvature2 = if rCurvature > rw then rCurvature else rw;
