  Modelica.Blocks.Interfaces.RealInput tauDrive(unit = "N.m") "Accelerating torque acting at flange (= -flange.tau)" ;
  Modelica.Mechanics.Rotational.Components.TorqueToAngleAdaptor torqueToAngle ;
