equation
  connect(tauDrive, torqueSource.tau) ;
  connect(torqueSource.flange, inertia.flange_a) ;
  connect(inertia.flange_b, torqueToAngle.flange) ;
  connect(torqueToAngle.phi, phi) ;
  connect(torqueToAngle.w, w) ;
  connect(torqueToAngle.a, a) ;
  connect(torqueToAngle.tau, tau) ;

end DirectInertia;

