partial model PartialElementaryRotationalToTranslational "Partial model to transform rotational into translational motion"
  parameter Boolean useSupportR = false "= true, if rotational support flange enabled, otherwise implicitly grounded" ;
  parameter Boolean useSupportT = false "= true, if translational support flange enabled, otherwise implicitly grounded" ;
  Modelica.Mechanics.Rotational.Interfaces.Flange_a flangeR "Flange of rotational shaft" ;
  Modelica.Mechanics.Translational.Interfaces.Flange_b flangeT "Flange of translational rod" ;
  Modelica.Mechanics.Rotational.Interfaces.Support supportR if useSupportR "Rotational support/housing of component" ;
  Modelica.Mechanics.Translational.Interfaces.Support supportT if useSupportT "Translational support/housing of component" ;
protected
  Modelica.Mechanics.Rotational.Interfaces.InternalSupport internalSupportR(tau = -flangeR.tau) ;
  Modelica.Mechanics.Translational.Interfaces.InternalSupport internalSupportT(f = -flangeT.f) ;
  Modelica.Mechanics.Rotational.Components.Fixed fixedR if not useSupportR ;
  Modelica.Mechanics.Translational.Components.Fixed fixedT if not useSupportT ;
equation
  connect(internalSupportR.flange, supportR) ;
  connect(internalSupportR.flange, fixedR.flange) ;
  connect(fixedT.flange, internalSupportT.flange) ;
  connect(internalSupportT.flange, supportT) ;

end PartialElementaryRotationalToTranslational;

