   the different structural configurations,
   if for each configuration special code shall be generated)
*/
    startForward = pre(mode) == Stuck and (sa > f0_max / unitForce and s < smax - L / 2 or pre(startForward) and sa > f0 / unitForce and s < smax - L / 2) or pre(mode) == Backward and v_relfric > v_small or initial() and v_relfric > 0;
    startBackward = pre(mode) == Stuck and (sa < -f0_max / unitForce and s > smin + L / 2 or pre(startBackward) and sa < -f0 / unitForce and s > smin + L / 2) or pre(mode) == Forward and v_relfric < -v_small or initial() and v_relfric < 0;
    locked = not free and not (pre(mode) == Forward or startForward or pre(mode) == Backward or startBackward);
