model Move "Forced movement of a flange according to a position, velocity and acceleration signal"
  extends Modelica.Mechanics.Translational.Interfaces.PartialElementaryOneFlangeAndSupport2;
  Modelica.Blocks.Interfaces.RealInput u[3] "Position, velocity and acceleration of flange as input signals" ;
protected
  function position
    extends Modelica.Icons.Function;
    input Real q_qd_qdd[3] "Required values for position, speed, acceleration";
    input Real dummy "Just to have one input signal that should be differentiated to avoid possible problems in the Modelica tool (is not used)";
    output Real q;
  algorithm
    q := q_qd_qdd[1];

  end position;

  function position_der
    extends Modelica.Icons.Function;
    input Real q_qd_qdd[3] "Required values for position, speed, acceleration";
    input Real dummy "Just to have one input signal that should be differentiated to avoid possible problems in the Modelica tool (is not used)";
    input Real dummy_der;
    output Real qd;
  algorithm
    qd := q_qd_qdd[2];

  end position_der;

  function position_der2
    extends Modelica.Icons.Function;
    input Real q_qd_qdd[3] "Required values for position, speed, acceleration";
    input Real dummy "Just to have one input signal that should be differentiated to avoid possible problems in the Modelica tool (is not used)";
    input Real dummy_der;
    input Real dummy_der2;
    output Real qdd;
  algorithm
    qdd := q_qd_qdd[3];
  end position_der2;
equation
  s = position(u, time);

end Move;

