  parameter Modelica.Units.SI.Temperature T_min = 300 "Vary temperature linearly from T_min (time=0) up to T_max (time=1)";
  parameter Modelica.Units.SI.Temperature T_max = 500 "Vary temperature linearly from T_min (time=0) up to T_max (time=1)";
  parameter Modelica.Units.SI.Pressure p = 1.0e5 "Fixed pressure in model";
  final parameter Modelica.Units.SI.SpecificEnthalpy h_min = Medium.specificEnthalpy(Medium.setState_pT(p, T_min)) "Specific enthalpy at T_min";
  final parameter Modelica.Units.SI.SpecificEnthalpy h_max = Medium.specificEnthalpy(Medium.setState_pT(p, T_max)) "Specific enthalpy at T_max";
  final parameter Modelica.Units.SI.SpecificEntropy s_min = Medium.specificEntropy(Medium.setState_pT(p, T_min)) "Specific entropy at T_min";
  final parameter Modelica.Units.SI.SpecificEntropy s_max = Medium.specificEntropy(Medium.setState_pT(p, T_max)) "Specific entropy at T_max";
  Modelica.Units.SI.SpecificEnthalpy h1(start = h_min, fixed = true) "Pre-defined specific enthalpy";
  Modelica.Units.SI.SpecificEnthalpy h2 "Specific enthalpy computed from Th (= h1 required)";
  Modelica.Units.SI.SpecificEntropy s1(start = s_min, fixed = true) "Pre-defined specific entropy";
  Modelica.Units.SI.SpecificEntropy s2 "Specific entropy computed from Ts (= s1 required)";
  Modelica.Units.SI.Temperature Th "Temperature computed from h1";
  Modelica.Units.SI.Temperature Ts "Temperature computed from s1";
protected
  constant Modelica.Units.SI.Time timeUnit = 1.0;
equation
  // Define specific enthalpy and specific entropy
  der(h1) = if time < 1.0 then 1 / timeUnit * (h_max - h_min) else 0.0;
  der(s1) = if time < 1.0 then 1 / timeUnit * (s_max - s_min) else 0.0;
  // Solve for temperatures
  Th = Medium.temperature_phX(p, h1, fill(0.0, 0));
  Ts = Medium.temperature_psX(p, s1, fill(0.0, 0));
