model FixedMassFlowRate "Ideal pump that produces a constant mass flow rate from a large reservoir at fixed temperature and mass fraction"
  parameter Medium.MassFlowRate m_flow "Fixed mass flow rate from an infinite reservoir to the fluid port";
  parameter Boolean use_T_ambient = true "Select T_ambient or h_ambient" ;
  parameter Medium.Temperature T_ambient = Modelica.Units.Conversions.from_degC(20) "Ambient temperature" ;
  parameter Medium.SpecificEnthalpy h_ambient = 1.e4 "Ambient specific enthalpy" ;
  parameter Medium.MassFraction X_ambient[Medium.nX] "Ambient mass fractions m_i/m of reservoir";
  replaceable package Medium = Modelica.Media.Interfaces.PartialMedium "Medium model" ;
  Medium.BaseProperties medium "Medium in the source";
  Modelica.Media.Examples.Utilities.FluidPort_b port(redeclare package Medium = Medium) ;
equation
