modelica://Modelica.Media/setState_phX-2:
Modelica.Media: setState_phX (function)

Code:
function extends setState_phX "Set the thermodynamic state record from p and h (X not needed)"
  algorithm
    state := Modelica.Media.Interfaces.PartialLinearFluid.ThermodynamicState(p = p, T = (h - reference_h - (p - reference_p) * ((1 - beta_const * reference_T) / reference_d)) / cp_const + reference_T);
end setState_phX;

modelica://Modelica.Media/setState_psX-2:
Modelica.Media: setState_psX (function)

Code:
function extends setState_psX "Set the thermodynamic state record from p and s (X not needed)"
  algorithm
    state := Modelica.Media.Interfaces.PartialLinearFluid.ThermodynamicState(p = p, T = reference_T * cp_const / (cp_const - s + reference_s + (p - reference_p) * (-beta_const / reference_d)));
end setState_psX;

modelica://Modelica.Media/setState_dTX-2:
Modelica.Media: setState_dTX (function)

Code:
function extends setState_dTX "Set the thermodynamic state record from d and T (X not needed)"
  algorithm
    state := Modelica.Media.Interfaces.PartialLinearFluid.ThermodynamicState(p = (d - reference_d + (T - reference_T) * beta_const * reference_d) / (reference_d * kappa_const) + reference_p, T = T);
end setState_dTX;

