    state := Modelica.Media.Interfaces.PartialLinearFluid.ThermodynamicState(p = Modelica.Media.Common.smoothStep(x, state_a.p, state_b.p, x_small), T = Modelica.Media.Common.smoothStep(x, state_a.T, state_b.T, x_small));
end setSmoothState;

