Modelica.Media: specificEntropy (function)

Code:
function extends specificEntropy "Return the specific entropy from the thermodynamic state"
  algorithm
    s := reference_s + (state.T - reference_T) * cp_const / state.T + (state.p - reference_p) * (-beta_const / reference_d);
end specificEntropy;

