function extends specificGibbsEnergy "Return specific Gibbs energy from the thermodynamic state"
    extends Modelica.Icons.Function;

  algorithm
    g := Modelica.Media.Interfaces.PartialLinearFluid.specificEnthalpy(state) - state.T * Modelica.Media.Interfaces.PartialLinearFluid.specificEntropy(state);
