modelica://Modelica.Media/T_ph:
Modelica.Media: T_ph (function)

Code:
function T_ph "Return temperature from pressure and specific enthalpy"
  extends Modelica.Icons.Function;
  input Modelica.Media.Interfaces.PartialLinearFluid.SpecificEnthalpy h "Specific enthalpy";
  input Modelica.Media.Interfaces.PartialLinearFluid.AbsolutePressure p "Pressure";
  output Modelica.Media.Interfaces.PartialLinearFluid.Temperature T "Temperature";
algorithm
  T := (h - reference_h - (p - reference_p) * ((1 - beta_const * reference_T) / reference_d)) / cp_const + reference_T;
end T_ph;

