modelica://Modelica.Media/moleToMassFrac:
Modelica.Media: moleToMassFractions (function)

Code:
function moleToMassFractions "Return mass fractions X from mole fractions"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MoleFraction moleFractions[:] "Mole fractions of mixture";
  input Modelica.Media.Interfaces.PartialMixtureMedium.MolarMass[:] MMX "Molar masses of components";
  output Modelica.Units.SI.MassFraction X[size(moleFractions, 1)] "Mass fractions of gas mixture";
protected
  Modelica.Media.Interfaces.PartialMixtureMedium.MolarMass Mmix = moleFractions * MMX "Molar mass of mixture";
algorithm
  for i in 1:size(moleFractions, 1) loop
    X[i] := moleFractions[i] * MMX[i] / Mmix;
  end for;

end moleToMassFractions;

modelica://Modelica.Media/massToMoleFrac:
Modelica.Media: massToMoleFractions (function)

Code:
function massToMoleFractions "Return mole fractions from mass fractions X"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.MassFraction X[:] "Mass fractions of mixture";
  input Modelica.Units.SI.MolarMass[:] MMX "Molar masses of components";
  output Modelica.Units.SI.MoleFraction moleFractions[size(X, 1)] "Mole fractions of gas mixture";
protected
  Real invMMX[size(X, 1)] "Inverses of molar weights";
  Modelica.Units.SI.MolarMass Mmix "Molar mass of mixture";
algorithm
  for i in 1:size(X, 1) loop
    invMMX[i] := 1 / MMX[i];
  end for;
  Mmix := 1 / (X * invMMX);
  for i in 1:size(X, 1) loop
    moleFractions[i] := Mmix * X[i] / MMX[i];
  end for;

end massToMoleFractions;

