Code:
function setState_px "Return thermodynamic state from pressure and vapour quality"
  extends Modelica.Icons.Function;
  input Modelica.Media.Interfaces.PartialTwoPhaseMedium.AbsolutePressure p "Pressure";
  input Modelica.Media.Interfaces.PartialTwoPhaseMedium.MassFraction x "Vapour quality";
  output Modelica.Media.Interfaces.PartialTwoPhaseMedium.ThermodynamicState state "Thermodynamic state record";
algorithm
  state := Modelica.Media.Interfaces.PartialTwoPhaseMedium.setState_ph(p, (1 - x) * Modelica.Media.Interfaces.PartialTwoPhaseMedium.bubbleEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_p(p)) + x * Modelica.Media.Interfaces.PartialTwoPhaseMedium.dewEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_p(p)), 2);
end setState_px;

