  input Modelica.Media.Interfaces.PartialTwoPhaseMedium.MassFraction x "Vapour quality";
  output Modelica.Media.Interfaces.PartialTwoPhaseMedium.ThermodynamicState state "Thermodynamic state record";
algorithm
  state := Modelica.Media.Interfaces.PartialTwoPhaseMedium.setState_ph(Modelica.Media.Interfaces.PartialTwoPhaseMedium.saturationPressure_sat(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_T(T)), (1 - x) * Modelica.Media.Interfaces.PartialTwoPhaseMedium.bubbleEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_T(T)) + x * Modelica.Media.Interfaces.PartialTwoPhaseMedium.dewEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_T(T)), 2);
end setState_Tx;

modelica://Modelica.Media/vapourQuality:
Modelica.Media: vapourQuality (function)

Code:
function vapourQuality "Return vapour quality"
  extends Modelica.Icons.Function;
  input Modelica.Media.Interfaces.PartialTwoPhaseMedium.ThermodynamicState state "Thermodynamic state record";
  output Modelica.Media.Interfaces.PartialTwoPhaseMedium.MassFraction x "Vapour quality";
protected
  constant Modelica.Media.Interfaces.PartialTwoPhaseMedium.SpecificEnthalpy eps = 1e-8;
algorithm
  x := min(max((Modelica.Media.Interfaces.PartialTwoPhaseMedium.specificEnthalpy(state) - Modelica.Media.Interfaces.PartialTwoPhaseMedium.bubbleEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_p(Modelica.Media.Interfaces.PartialTwoPhaseMedium.pressure(state)))) / (Modelica.Media.Interfaces.PartialTwoPhaseMedium.dewEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_p(Modelica.Media.Interfaces.PartialTwoPhaseMedium.pressure(state))) - Modelica.Media.Interfaces.PartialTwoPhaseMedium.bubbleEnthalpy(Modelica.Media.Interfaces.PartialTwoPhaseMedium.setSat_p(Modelica.Media.Interfaces.PartialTwoPhaseMedium.pressure(state))) + eps), 0), 1);
end vapourQuality;

