modelica://Modelica.Media/gibbsToBridgma:
Modelica.Media: gibbsToBridgmansTables (function)

Code:
function gibbsToBridgmansTables "Calculates base coefficients for Bridgman's tables from gibbs enthalpy"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Units.SI.SpecificVolume v "Specific volume";
  output Modelica.Units.SI.Pressure p = g.p "Pressure";
  output Modelica.Units.SI.Temperature T = g.T "Temperature";
  output Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  output Modelica.Units.SI.SpecificHeatCapacity cp "Heat capacity at constant pressure";
  output Modelica.Media.Common.IsobaricVolumeExpansionCoefficient alpha "Isobaric volume expansion coefficient";
  // beta in Bejan
  output Modelica.Media.Common.IsothermalCompressibility gamma "Isothermal compressibility";
  // kappa in Bejan
protected
  Real vt(unit = "m3/(kg.K)") "Derivative of specific volume w.r.t. temperature";
  Real vp(unit = "m4.kg-2.s2") "Derivative of specific volume w.r.t. pressure";
algorithm
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  v := g.R_s * g.T * g.pi * g.gpi / g.p;
  s := g.R_s * (g.tau * g.gtau - g.g);
  cp := -g.R_s * g.tau * g.tau * g.gtautau;
  alpha := vt / v;
  gamma := -vp / v;
end gibbsToBridgmansTables;

modelica://Modelica.Media/helmholtzToBri:
Modelica.Media: helmholtzToBridgmansTables (function)

Code:
function helmholtzToBridgmansTables "Calculates base coefficients for Bridgmans tables from Helmholtz energy"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Units.SI.SpecificVolume v = 1 / f.d "Specific volume";
  output Modelica.Units.SI.Pressure p "Pressure";
  output Modelica.Units.SI.Temperature T = f.T "Temperature";
  output Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  output Modelica.Units.SI.SpecificHeatCapacity cp "Heat capacity at constant pressure";
  output Modelica.Media.Common.IsobaricVolumeExpansionCoefficient alpha "Isobaric volume expansion coefficient";
  // beta in Bejan
  output Modelica.Media.Common.IsothermalCompressibility gamma "Isothermal compressibility";
  // kappa in Bejan
protected
  Modelica.Media.Common.DerPressureByTemperature pt "Derivative of pressure w.r.t. temperature";
  Modelica.Media.Common.DerPressureBySpecificVolume pv "Derivative of pressure w.r.t. specific volume";
  Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric specific heat capacity";
algorithm
  p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  pv := -f.d * f.d * f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  s := f.R_s * (f.tau * f.ftau - f.f);
  alpha := -f.d * pt / pv;
  gamma := -f.d / pv;
  cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
end helmholtzToBridgmansTables;

modelica://Modelica.Media/gibbsToBoundar:
Modelica.Media: gibbsToBoundaryProps (function)

Code:
function gibbsToBoundaryProps "Calculate phase boundary property record from dimensionless Gibbs function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.PhaseBoundaryProperties sat "Phase boundary properties";
protected
  Real vt "Derivative of specific volume w.r.t. temperature";
  Real vp "Derivative of specific volume w.r.t. pressure";
algorithm
  sat.d := g.p / (g.R_s * g.T * g.pi * g.gpi);
  sat.h := g.R_s * g.T * g.tau * g.gtau;
  sat.u := g.T * g.R_s * (g.tau * g.gtau - g.pi * g.gpi);
  sat.s := g.R_s * (g.tau * g.gtau - g.g);
  sat.cp := -g.R_s * g.tau * g.tau * g.gtautau;
  sat.cv := g.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  // sat.kappa := -1/(sat.d*g.p)*sat.cp/(vp*sat.cp + vt*vt*g.T);
  sat.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
  sat.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
end gibbsToBoundaryProps;

modelica://Modelica.Media/helmholtzToBou:
Modelica.Media: helmholtzToBoundaryProps (function)

Code:
function helmholtzToBoundaryProps "Calculate phase boundary property record from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.PhaseBoundaryProperties sat "Phase boundary property record";
protected
  Modelica.Units.SI.Pressure p "Pressure";
algorithm
  p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  sat.d := f.d;
  sat.h := f.R_s * f.T * (f.tau * f.ftau + f.delta * f.fdelta);
  sat.s := f.R_s * (f.tau * f.ftau - f.f);
  sat.u := f.R_s * f.T * f.tau * f.ftau;
  sat.cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
  sat.cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  sat.pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  sat.pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
end helmholtzToBoundaryProps;

modelica://Modelica.Media/cv2Phase:
Modelica.Media: cv2Phase (function)

Code:
function cv2Phase "Compute isochoric specific heat capacity inside the two-phase region"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.PhaseBoundaryProperties liq "Properties on the boiling curve";
  input Modelica.Media.Common.PhaseBoundaryProperties vap "Properties on the condensation curve";
  input Modelica.Units.SI.MassFraction x "Vapour mass fraction";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.Pressure p "Properties";
  output Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric specific heat capacity";
protected
  Real dpT "Derivative of pressure w.r.t. temperature";
  Real dxv "Derivative of vapour mass fraction w.r.t. specific volume";
  Real dvTl "Derivative of liquid specific volume w.r.t. temperature";
  Real dvTv "Derivative of vapour specific volume w.r.t. temperature";
  Real duTl "Derivative of liquid specific inner energy w.r.t. temperature";
  Real duTv "Derivative of vapour specific inner energy w.r.t. temperature";
  Real dxt "Derivative of vapour mass fraction w.r.t. temperature";
algorithm
  dxv := if liq.d <> vap.d then liq.d * vap.d / (liq.d - vap.d) else 0.0;
  dpT := (vap.s - liq.s) * dxv;
  // wrong at critical point
  dvTl := (liq.pt - dpT) / liq.pd / liq.d / liq.d;
  dvTv := (vap.pt - dpT) / vap.pd / vap.d / vap.d;
  dxt := -dxv * (dvTl + x * (dvTv - dvTl));
  duTl := liq.cv + (T * liq.pt - p) * dvTl;
  duTv := vap.cv + (T * vap.pt - p) * dvTv;
  cv := duTl + x * (duTv - duTl) + dxt * (vap.u - liq.u);
end cv2Phase;

