  output Modelica.Media.Common.ExtraDerivatives dpro "Additional property derivatives";
protected
  Real vt "Derivative of specific volume w.r.t. temperature";
  Real vp "Derivative of specific volume w.r.t. pressure";
  Modelica.Units.SI.Density d "Density";
  Modelica.Units.SI.SpecificVolume v "Specific volume";
  Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric heat capacity";
  Modelica.Units.SI.SpecificHeatCapacity cp "Isobaric heat capacity";
algorithm
  d := g.p / (g.R_s * g.T * g.pi * g.gpi);
  v := 1 / d;
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  cp := -g.R_s * g.tau * g.tau * g.gtautau;
  cv := g.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  dpro.kappa := -1 / (d * g.p) * cp / (vp * cp + vt * vt * g.T);
  dpro.theta := cp / (d * g.p * (-vp * cp + vt * v - g.T * vt * vt));
  dpro.alpha := d * vt;
  dpro.beta := -vt / (g.p * vp);
  dpro.gamma := -d * vp;
  dpro.mu := -(v - g.T * vt) / cp;
end gibbsToExtraDerivs;

modelica://Modelica.Media/helmholtzToExt:
Modelica.Media: helmholtzToExtraDerivs (function)

Code:
function helmholtzToExtraDerivs "Compute additional thermodynamic derivatives from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.ExtraDerivatives dpro "Additional property derivatives";
protected
  Modelica.Units.SI.Pressure p "Pressure";
  Modelica.Units.SI.SpecificVolume v "Specific volume";
  Modelica.Media.Common.DerPressureByTemperature pt "Derivative of pressure w.r.t. temperature";
  Modelica.Media.Common.DerPressureBySpecificVolume pv "Derivative of pressure w.r.t. specific volume";
  Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric specific heat capacity";
algorithm
  v := 1 / f.d;
  p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  pv := -f.d * f.d * f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  dpro.kappa := 1 / (f.d * p) * ((-pv * cv + pt * pt * f.T) / cv);
  dpro.theta := -1 / (f.d * p) * ((-pv * cv + f.T * pt * pt) / (cv + pt * v));
  dpro.alpha := -f.d * pt / pv;
  dpro.beta := pt / p;
  dpro.gamma := -f.d / pv;
  dpro.mu := (v * pv + f.T * pt) / (pt * pt * f.T - pv * cv);
end helmholtzToExtraDerivs;

modelica://Modelica.Media/Helmholtz_ph:
Modelica.Media: Helmholtz_ph (function)

Code:
function Helmholtz_ph "Function to calculate analytic derivatives for computing d and t given p and h"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.NewtonDerivatives_ph nderivs "Derivatives for Newton iteration to calculate d and t from p and h";
protected
  Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric heat capacity";
algorithm
  cv := -f.R_s * (f.tau * f.tau * f.ftautau);
  nderivs.p := f.d * f.R_s * f.T * f.delta * f.fdelta;
  nderivs.h := f.R_s * f.T * (f.tau * f.ftau + f.delta * f.fdelta);
  nderivs.pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  nderivs.pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  nderivs.ht := cv + nderivs.pt / f.d;
  nderivs.hd := (nderivs.pd - f.T * nderivs.pt / f.d) / f.d;
end Helmholtz_ph;

modelica://Modelica.Media/Helmholtz_pT:
Modelica.Media: Helmholtz_pT (function)

Code:
function Helmholtz_pT "Function to calculate analytic derivatives for computing d and t given p and t"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.NewtonDerivatives_pT nderivs "Derivatives for Newton iteration to compute d and t from p and t";
algorithm
  nderivs.p := f.d * f.R_s * f.T * f.delta * f.fdelta;
  nderivs.pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
end Helmholtz_pT;

modelica://Modelica.Media/Helmholtz_ps:
Modelica.Media: Helmholtz_ps (function)

Code:
function Helmholtz_ps "Function to calculate analytic derivatives for computing d and t given p and s"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.NewtonDerivatives_ps nderivs "Derivatives for Newton iteration to compute d and t from p and s";
protected
  Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric heat capacity";
algorithm
  cv := -f.R_s * (f.tau * f.tau * f.ftautau);
  nderivs.p := f.d * f.R_s * f.T * f.delta * f.fdelta;
  nderivs.s := f.R_s * (f.tau * f.ftau - f.f);
  nderivs.pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  nderivs.pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  nderivs.st := cv / f.T;
  nderivs.sd := -nderivs.pt / (f.d * f.d);
end Helmholtz_ps;

modelica://Modelica.Media/Gibbs2_ph:
Modelica.Media: Gibbs2_ph (function)

Code:
function Gibbs2_ph "Function to calculate analytic derivatives for computing T given p and h"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs2 g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.NewtonDerivatives_ph nderivs "Derivatives for Newton iteration to calculate d and t from p and h";
algorithm
  nderivs.h := g.g - g.T * g.gT;
  nderivs.ht := -g.T * g.gTT;
  //dummy values - DO NOT USE
  nderivs.p := 0.0;
  nderivs.pd := 0.0;
  nderivs.pt := 0.0;
  nderivs.hd := 0.0;
end Gibbs2_ph;

modelica://Modelica.Media/Gibbs2_dT:
Modelica.Media: Gibbs2_dT (function)

Code:
function Gibbs2_dT "Function to calculate analytic derivatives for computing p given d and T"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs2 g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.NewtonDerivatives_dT nderivs "Derivatives for Newton iteration to compute p from d and T";
algorithm
  nderivs.v := g.gp;
  nderivs.vp := nderivs.v * g.gpp / g.gp;
end Gibbs2_dT;

modelica://Modelica.Media/Gibbs2_ps:
Modelica.Media: Gibbs2_ps (function)

Code:
function Gibbs2_ps "Function to calculate analytic derivatives for computing d and t given p and s"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs2 g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.NewtonDerivatives_ps nderivs "Derivatives for Newton iteration to compute T from p and s";
algorithm
  nderivs.s := -g.gT;
