modelica://Modelica.Media/gibbsToProps_p:
Modelica.Media: gibbsToProps_ph (function)

Code:
function gibbsToProps_ph "Calculate property record for pressure and specific enthalpy as states from dimensionless Gibbs function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_ph pro "Property record for pressure and specific enthalpy as dynamic states";
protected
  Real vt(unit = "m3.kg-1.K-1") "Derivative of specific volume w.r.t. temperature";
  Real vp(unit = "m4.kg-2.s2") "Derivative of specific volume w.r.t. pressure";
algorithm
  pro.T := g.T;
  pro.R_s := g.R_s;
  pro.d := g.p / (pro.R_s * pro.T * g.pi * g.gpi);
  pro.u := g.T * g.R_s * (g.tau * g.gtau - g.pi * g.gpi);
  pro.s := pro.R_s * (g.tau * g.gtau - g.g);
  pro.cp := -pro.R_s * g.tau * g.tau * g.gtautau;
  pro.cv := pro.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  pro.a := abs(g.R_s * g.T * (g.gpi * g.gpi / ((g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / (g.tau * g.tau * g.gtautau) - g.gpipi))) ^ 0.5;
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  pro.kappa := -1 / (pro.d * g.p) * pro.cp / (vp * pro.cp + vt * vt * g.T);
  pro.ddhp := -pro.d * pro.d * vt / pro.cp;
  pro.ddph := -pro.d * pro.d * (vp * pro.cp - vt / pro.d + g.T * vt * vt) / pro.cp;
  pro.duph := -1 / pro.d + g.p / (pro.d * pro.d) * pro.ddph;
  pro.duhp := 1 + g.p / (pro.d * pro.d) * pro.ddhp;
end gibbsToProps_ph;

modelica://Modelica.Media/gibbsToBoundar:
Modelica.Media: gibbsToBoundaryProps (function)

Code:
function gibbsToBoundaryProps "Calculate phase boundary property record from dimensionless Gibbs function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.PhaseBoundaryProperties sat "Phase boundary properties";
protected
  Real vt(unit = "m3.kg-1.K-1") "Derivative of specific volume w.r.t. temperature";
  Real vp(unit = "m4.kg-2.s2") "Derivative of specific volume w.r.t. pressure";
algorithm
  sat.d := g.p / (g.R_s * g.T * g.pi * g.gpi);
  sat.h := g.R_s * g.T * g.tau * g.gtau;
  sat.u := g.T * g.R_s * (g.tau * g.gtau - g.pi * g.gpi);
  sat.s := g.R_s * (g.tau * g.gtau - g.g);
  sat.cp := -g.R_s * g.tau * g.tau * g.gtautau;
  sat.cv := g.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  // sat.kappa := -1/(sat.d*g.p)*sat.cp/(vp*sat.cp + vt*vt*g.T);
  sat.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
  sat.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
end gibbsToBoundaryProps;

modelica://Modelica.Media/gibbsToProps_d:
Modelica.Media: gibbsToProps_dT (function)

Code:
function gibbsToProps_dT "Calculate property record for density and temperature as states from dimensionless Gibbs function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_dT pro "Property record for density and temperature as dynamic states";
protected
  Real vt(unit = "m3.kg-1.K-1") "Derivative of specific volume w.r.t. temperature";
  Real vp(unit = "m4.kg-2.s2") "Derivative of specific volume w.r.t. pressure";
  Modelica.Units.SI.Density d;
algorithm
  pro.R_s := g.R_s;
  pro.p := g.p;
  pro.u := g.T * g.R_s * (g.tau * g.gtau - g.pi * g.gpi);
  pro.h := g.R_s * g.T * g.tau * g.gtau;
  pro.s := pro.R_s * (g.tau * g.gtau - g.g);
  pro.cp := -pro.R_s * g.tau * g.tau * g.gtautau;
  pro.cv := pro.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  pro.kappa := -1 / (g.p / (pro.R_s * g.T * g.pi * g.gpi) * g.p) * pro.cp / (vp * pro.cp + vt * vt * g.T);
  pro.a := abs(g.R_s * g.T * (g.gpi * g.gpi / ((g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / (g.tau * g.tau * g.gtautau) - g.gpipi))) ^ 0.5;
  d := g.p / (pro.R_s * g.T * g.pi * g.gpi);
  pro.dudT := (pro.p - g.T * vt / vp) / (d * d);
end gibbsToProps_dT;

modelica://Modelica.Media/gibbsToProps_p:
Modelica.Media: gibbsToProps_pT (function)

Code:
function gibbsToProps_pT "Calculate property record for pressure and temperature as states from dimensionless Gibbs function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.GibbsDerivs g "Dimensionless derivatives of Gibbs function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_pT pro "Property record for pressure and temperature as dynamic states";
protected
  Real vt(unit = "m3.kg-1.K-1") "Derivative of specific volume w.r.t. temperature";
  Real vp(unit = "m4.kg-2.s2") "Derivative of specific volume w.r.t. pressure";
algorithm
  pro.R_s := g.R_s;
  pro.d := g.p / (pro.R_s * g.T * g.pi * g.gpi);
  pro.u := g.T * g.R_s * (g.tau * g.gtau - g.pi * g.gpi);
  pro.h := g.R_s * g.T * g.tau * g.gtau;
  pro.s := pro.R_s * (g.tau * g.gtau - g.g);
  pro.cp := -pro.R_s * g.tau * g.tau * g.gtautau;
  pro.cv := pro.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
  vt := g.R_s / g.p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  vp := g.R_s * g.T / (g.p * g.p) * g.pi * g.pi * g.gpipi;
  pro.kappa := -1 / (pro.d * g.p) * pro.cp / (vp * pro.cp + vt * vt * g.T);
  pro.a := abs(g.R_s * g.T * (g.gpi * g.gpi / ((g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / (g.tau * g.tau * g.gtautau) - g.gpipi))) ^ 0.5;
  pro.ddpT := -pro.d * pro.d * vp;
  pro.ddTp := -pro.d * pro.d * vt;
  pro.duTp := pro.cp - g.p * vt;
  pro.dupT := -g.T * vt - g.p * vp;
end gibbsToProps_pT;

modelica://Modelica.Media/helmholtzToPro:
Modelica.Media: helmholtzToProps_ph (function)

Code:
function helmholtzToProps_ph "Calculate property record for pressure and specific enthalpy as states from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_ph pro "Property record for pressure and specific enthalpy as dynamic states";
protected
  Modelica.Units.SI.Pressure p "Pressure";
  Modelica.Media.Common.DerPressureByDensity pd "Derivative of pressure w.r.t. density";
  Modelica.Media.Common.DerPressureByTemperature pt "Derivative of pressure w.r.t. temperature";
  Modelica.Media.Common.DerPressureBySpecificVolume pv "Derivative of pressure w.r.t. specific volume";
algorithm
  pro.d := f.d;
  pro.T := f.T;
  pro.R_s := f.R_s;
  pro.s := f.R_s * (f.tau * f.ftau - f.f);
  pro.u := f.R_s * f.T * f.tau * f.ftau;
  p := pro.d * pro.R_s * pro.T * f.delta * f.fdelta;
  pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  pv := -pd * f.d * f.d;
  // calculating cp near the critical point may be troublesome (cp -> inf).
  pro.cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
  pro.cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  pro.kappa := 1 / (f.d * f.R_s * f.d * f.T * f.delta * f.fdelta) * ((-pv * pro.cv + pt * pt * f.T) / pro.cv);
  pro.a := abs(f.R_s * f.T * (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta - (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) * (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) / (f.tau * f.tau * f.ftautau))) ^ 0.5;
  pro.ddph := f.d * (pro.cv * f.d + pt) / (f.d * f.d * pd * pro.cv + f.T * pt * pt);
  pro.ddhp := -f.d * f.d * pt / (f.d * f.d * pd * pro.cv + f.T * pt * pt);
  pro.duph := -1 / pro.d + p / (pro.d * pro.d) * pro.ddph;
  pro.duhp := 1 + p / (pro.d * pro.d) * pro.ddhp;
end helmholtzToProps_ph;

Modelica.Media: helmholtzToProps_pT (function)

Code:
function helmholtzToProps_pT "Calculate property record for pressure and temperature as states from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_pT pro "Property record for pressure and temperature as dynamic states";
protected
  Modelica.Media.Common.DerPressureByDensity pd "Derivative of pressure w.r.t. density";
  Modelica.Media.Common.DerPressureByTemperature pt "Derivative of pressure w.r.t. temperature";
  Modelica.Media.Common.DerPressureBySpecificVolume pv "Derivative of pressure w.r.t. specific volume";
  Modelica.Media.Common.IsobaricVolumeExpansionCoefficient alpha "Isobaric volume expansion coefficient";
  // beta in Bejan
  Modelica.Media.Common.IsothermalCompressibility gamma "Isothermal compressibility";
  // kappa in Bejan
  Modelica.Units.SI.Pressure p "Pressure";
algorithm
  pro.d := f.d;
  pro.R_s := f.R_s;
  pro.s := f.R_s * (f.tau * f.ftau - f.f);
  pro.h := f.R_s * f.T * (f.tau * f.ftau + f.delta * f.fdelta);
  pro.u := f.R_s * f.T * f.tau * f.ftau;
  pd := f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  pv := -f.d * f.d * pd;
  alpha := -f.d * pt / pv;
  gamma := -f.d / pv;
  p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  // calculating cp near the critical point may be troublesome (cp -> inf).
  pro.cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
  pro.cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  pro.kappa := 1 / (f.d * f.R_s * f.d * f.T * f.delta * f.fdelta) * ((-pv * pro.cv + pt * pt * f.T) / pro.cv);
  pro.a := abs(f.R_s * f.T * (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta - (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) * (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) / (f.tau * f.tau * f.ftautau))) ^ 0.5;
  pro.ddTp := -pt / pd;
  pro.ddpT := 1 / pd;
  //problem with units in last two lines
  pro.dupT := gamma * p / f.d - alpha * f.T / f.d;
  pro.duTp := pro.cp - alpha * p / f.d;
end helmholtzToProps_pT;

Modelica.Media: helmholtzToProps_dT (function)

Code:
function helmholtzToProps_dT "Calculate property record for density and temperature as states from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_dT pro "Property record for density and temperature as dynamic states";
protected
  Modelica.Media.Common.DerPressureByTemperature pt "Derivative of pressure w.r.t. temperature";
  Modelica.Media.Common.DerPressureBySpecificVolume pv "Derivative of pressure w.r.t. pressure";
algorithm
  pro.p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  pro.R_s := f.R_s;
  pro.s := f.R_s * (f.tau * f.ftau - f.f);
  pro.h := f.R_s * f.T * (f.tau * f.ftau + f.delta * f.fdelta);
  pro.u := f.R_s * f.T * f.tau * f.ftau;
  pv := -f.d * f.d * f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
  pt := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  // calculating cp near the critical point may be troublesome (cp -> inf).
  pro.cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
  pro.cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  pro.kappa := 1 / (f.d * pro.p) * ((-pv * pro.cv + pt * pt * f.T) / pro.cv);
  pro.a := abs(f.R_s * f.T * (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta - (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) * (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) / (f.tau * f.tau * f.ftautau))) ^ 0.5;
  pro.dudT := (pro.p - f.T * pt) / (f.d * f.d);
end helmholtzToProps_dT;

modelica://Modelica.Media/TwoPhaseToProp:
Modelica.Media: TwoPhaseToProps_ph (function)

Code:
function TwoPhaseToProps_ph "Compute property record for pressure and specific enthalpy as states from saturation properties"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.SaturationProperties sat "Saturation property record";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_ph pro "Property record for pressure and specific enthalpy as dynamic states";
protected
  Real dht(unit = "(J/kg)/K") "Derivative of specific enthalpy w.r.t. temperature";
  Real dhd(unit = "(J/kg)/(kg/m3)") "Derivative of specific enthalpy w.r.t. density";
  Real detph(unit = "m4.s4/(K.s8)") "Thermodynamic determinant";
algorithm
  pro.d := sat.d;
  pro.T := sat.T;
  pro.u := sat.u;
  pro.s := sat.s;
  pro.cv := sat.cv;
  pro.R_s := sat.R_s;
  pro.cp := Modelica.Constants.inf;
  pro.kappa := -1 / (sat.d * sat.p) * sat.dpT * sat.dpT * sat.T / sat.cv;
  pro.a := Modelica.Constants.inf;
  dht := sat.cv + sat.dpT / sat.d;
  dhd := -sat.T * sat.dpT / (sat.d * sat.d);
  detph := -sat.dpT * dhd;
  pro.ddph := dht / detph;
  pro.ddhp := -sat.dpT / detph;
end TwoPhaseToProps_ph;

Modelica.Media: TwoPhaseToProps_dT (function)

Code:
function TwoPhaseToProps_dT "Compute property record for density and temperature as states from saturation properties"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.SaturationProperties sat "Saturation properties";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_dT pro "Property record for density and temperature as dynamic states";
algorithm
  pro.p := sat.p;
  pro.h := sat.h;
  pro.u := sat.u;
  pro.s := sat.s;
  pro.cv := sat.cv;
  pro.cp := Modelica.Constants.inf;
  pro.R_s := sat.R_s;
  pro.kappa := -1 / (sat.d * sat.p) * sat.dpT * sat.dpT * sat.T / sat.cv;
  pro.a := Modelica.Constants.inf;
  pro.dudT := (sat.p - sat.T * sat.dpT) / (sat.d * sat.d);
end TwoPhaseToProps_dT;

modelica://Modelica.Media/dynamicViscosi:
Modelica.Media: dynamicViscosity (function)

Dynamic viscosity is computed from temperature using a simple polynomial for dry air. Range of validity is from 123.15 K to 1273.15 K. The influence of pressure is neglected.  
Source: VDI Waermeatlas, 8th edition.

Code:
function dynamicViscosity "Return dynamic viscosity of dry air (simple polynomial, moisture influence small, valid from 123.15 K to 1273.15 K, outside of this range linear extrapolation is used)"
  extends Modelica.Icons.Function;
  input Modelica.Media.Air.DryAirNasa.ThermodynamicState state "Thermodynamic state record";
  output Modelica.Media.Air.DryAirNasa.DynamicViscosity eta "Dynamic viscosity";
  import Modelica.Math.Polynomials;
algorithm
  eta := 1e-6 * Polynomials.evaluateWithRange({9.7391102886305869E-15, -3.1353724870333906E-11, 4.3004876595642225E-08, -3.8228016291758240E-05, 5.0427874367180762E-02, 1.7239260139242528E+01}, Modelica.Units.Conversions.to_degC(123.15), Modelica.Units.Conversions.to_degC(1273.15), Modelica.Units.Conversions.to_degC(state.T));

end dynamicViscosity;

