Code:
model extends BaseProperties(h(stateSelect = if ph_explicit and preferredMediumStates then StateSelect.prefer else StateSelect.default), d(stateSelect = if dT_explicit and preferredMediumStates then StateSelect.prefer else StateSelect.default), T(stateSelect = if (pT_explicit or dT_explicit) and preferredMediumStates then StateSelect.prefer else StateSelect.default), p(stateSelect = if (pT_explicit or ph_explicit) and preferredMediumStates then StateSelect.prefer else StateSelect.default)) "Base properties of air"
  equation
    MM = Air_Utilities.Basic.Constants.MM;
    if dT_explicit then
      p = Modelica.Media.Air.ReferenceAir.Air_Base.pressure_dT(d, T);
      h = Modelica.Media.Air.ReferenceAir.Air_Base.specificEnthalpy_dT(d, T);
    elseif ph_explicit then
      d = Modelica.Media.Air.ReferenceAir.Air_Base.density_ph(p, h);
      T = Modelica.Media.Air.ReferenceAir.Air_Base.temperature_ph(p, h);
    else
      h = Modelica.Media.Air.ReferenceAir.Air_Base.specificEnthalpy_pT(p, T);
      d = Modelica.Media.Air.ReferenceAir.Air_Base.density_pT(p, T);
    end if;
    u = h - p / d;
    R_s = Air_Utilities.Basic.Constants.R_s;
    h = state.h;
    p = state.p;
    T = state.T;
    d = state.d;
end BaseProperties;

