modelica://Modelica.Media/airBaseProp_ps:
Modelica.Media: airBaseProp_ps (function)

Code:
function airBaseProp_ps "Intermediate property record for air"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  output Modelica.Media.Common.AuxiliaryProperties aux "Auxiliary record";
protected
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
algorithm
  aux.p := p;
  aux.s := s;
  aux.R_s := ReferenceAir.Air_Utilities.Basic.Constants.R_s;
  (aux.rho, aux.T) := Modelica.Media.Air.ReferenceAir.Air_Utilities.Inverses.dTofps(p = p, s = s, delp = iter.delp, dels = iter.dels);
  f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(aux.rho, aux.T);
  aux.h := aux.R_s * aux.T * (f.tau * f.ftau + f.delta * f.fdelta) - ReferenceAir.Air_Utilities.Basic.Constants.h_off;
  aux.pd := aux.R_s * aux.T * f.delta * (2 * f.fdelta + f.delta * f.fdeltadelta);
  aux.pt := aux.R_s * aux.rho * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  aux.cv := aux.R_s * (-f.tau * f.tau * f.ftautau);
  aux.cp := aux.cv + aux.T * aux.pt * aux.pt / (aux.rho * aux.rho * aux.pd);
  aux.vp := -1 / (aux.rho * aux.rho) * 1 / aux.pd;
  aux.vt := aux.pt / (aux.rho * aux.rho * aux.pd);
end airBaseProp_ps;

