modelica://Modelica.Media/airBaseProp_pT:
Modelica.Media: airBaseProp_pT (function)

Code:
function airBaseProp_pT "Intermediate property record for air (p and T preferred states)"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Media.Common.AuxiliaryProperties aux "Auxiliary record";
protected
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
algorithm
  aux.p := p;
  aux.T := T;
  aux.R_s := ReferenceAir.Air_Utilities.Basic.Constants.R_s;
  (aux.rho) := Modelica.Media.Air.ReferenceAir.Air_Utilities.Inverses.dofpT(p = p, T = T, delp = iter.delp);
  f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(aux.rho, T);
  aux.h := aux.R_s * T * (f.tau * f.ftau + f.delta * f.fdelta) - ReferenceAir.Air_Utilities.Basic.Constants.h_off;
  aux.s := aux.R_s * (f.tau * f.ftau - f.f) - ReferenceAir.Air_Utilities.Basic.Constants.s_off;
  aux.pd := aux.R_s * T * f.delta * (2 * f.fdelta + f.delta * f.fdeltadelta);
  aux.pt := aux.R_s * aux.rho * f.delta * (f.fdelta - f.tau * f.fdeltatau);
  aux.cv := aux.R_s * (-f.tau * f.tau * f.ftautau);
  aux.cp := aux.cv + aux.T * aux.pt * aux.pt / (aux.rho * aux.rho * aux.pd);
  aux.vp := -1 / (aux.rho * aux.rho) * 1 / aux.pd;
  aux.vt := aux.pt / (aux.rho * aux.rho * aux.pd);
end airBaseProp_pT;

