modelica://Modelica.Media/dofpT:
Modelica.Media: dofpT (function)

Code:
function dofpT "Compute d for given p and T"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature (K)";
  input Modelica.Units.SI.Pressure delp "Iteration converged if (p-pre(p) < delp)";
  output Modelica.Units.SI.Density d "Density";
protected
  Integer i = 0 "Loop counter";
  Real dp "Pressure difference";
  Modelica.Units.SI.Density deld "Density step";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.NewtonDerivatives_pT nDerivs "Derivatives needed in Newton iteration";
  Boolean found = false "Flag for iteration success";
algorithm
  d := p / (ReferenceAir.Air_Utilities.Basic.Constants.R_s * T);
  while i < 100 and not found loop
    f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(d, T);
    nDerivs := Modelica.Media.Common.Helmholtz_pT(f);
    dp := nDerivs.p - p;
    if abs(dp) <= delp then
      found := true;
    end if;
    deld := dp / nDerivs.pd;
    d := d - deld;
    i := i + 1;
  end while;
end dofpT;

modelica://Modelica.Media/dTofph:
Modelica.Media: dTofph (function)

Code:
function dTofph "Return d and T as a function of p and h"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy";
  input Modelica.Units.SI.Pressure delp "Iteration accuracy";
  input Modelica.Units.SI.SpecificEnthalpy delh "Iteration accuracy";
  output Modelica.Units.SI.Density d "Density";
  output Modelica.Units.SI.Temperature T "Temperature (K)";
protected
  Modelica.Units.SI.Temperature Tguess "Initial temperature";
  Modelica.Units.SI.Density dguess "Initial density";
  Integer i "Iteration counter";
  Real dh "Newton-error in h-direction";
  Real dp "Newton-error in p-direction";
  Real det "Determinant of directional derivatives";
  Real deld "Newton-step in d-direction";
  Real delt "Newton-step in T-direction";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.NewtonDerivatives_ph nDerivs "Derivatives needed in Newton iteration";
  Boolean found = false "Flag for iteration success";
algorithm
  // Stefan Wischhusen: better guess for high temperatures:
  T := h / 1000 + 273.15;
  d := p / (ReferenceAir.Air_Utilities.Basic.Constants.R_s * T);
  i := 0;
  while i < 100 and not found loop
    f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(d, T);
    nDerivs := Modelica.Media.Common.Helmholtz_ph(f);
    dh := nDerivs.h - ReferenceAir.Air_Utilities.Basic.Constants.h_off - h;
    dp := nDerivs.p - p;
    if abs(dh) <= delh and abs(dp) <= delp then
      found := true;
    end if;
    det := nDerivs.ht * nDerivs.pd - nDerivs.pt * nDerivs.hd;
    delt := (nDerivs.pd * dh - nDerivs.hd * dp) / det;
    deld := (nDerivs.ht * dp - nDerivs.pt * dh) / det;
    T := T - delt;
    d := d - deld;
    i := i + 1;
  end while;
end dTofph;

modelica://Modelica.Media/dTofps:
Modelica.Media: dTofps (function)

Code:
function dTofps "Return d and T as a function of p and s"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  input Modelica.Units.SI.Pressure delp "Iteration accuracy";
  input Modelica.Units.SI.SpecificEntropy dels "Iteration accuracy";
  output Modelica.Units.SI.Density d "Density";
  output Modelica.Units.SI.Temperature T "Temperature (K)";
protected
  Modelica.Units.SI.Temperature Tguess "Initial temperature";
  Modelica.Units.SI.Density dguess "Initial density";
  Integer i "Iteration counter";
  Real ds "Newton-error in s-direction";
  Real dp "Newton-error in p-direction";
  Real det "Determinant of directional derivatives";
  Real deld "Newton-step in d-direction";
  Real delt "Newton-step in T-direction";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.NewtonDerivatives_ps nDerivs "Derivatives needed in Newton iteration";
  Boolean found = false "Flag for iteration success";
algorithm
  T := 273.15;
  d := p / (ReferenceAir.Air_Utilities.Basic.Constants.R_s * T);
  i := 0;
  while i < 100 and not found loop
    f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(d, T);
    nDerivs := Modelica.Media.Common.Helmholtz_ps(f);
    ds := nDerivs.s - ReferenceAir.Air_Utilities.Basic.Constants.s_off - s;
    dp := nDerivs.p - p;
    if abs(ds) <= dels and abs(dp) <= delp then
      found := true;
    end if;
    det := nDerivs.st * nDerivs.pd - nDerivs.pt * nDerivs.sd;
    delt := (nDerivs.pd * ds - nDerivs.sd * dp) / det;
    deld := (nDerivs.st * dp - nDerivs.pt * ds) / det;
    T := T - delt;
    d := d - deld;
    i := i + 1;
  end while;
end dTofps;

modelica://Modelica.Media/eta_dT:
Modelica.Media: eta_dT (function)

Code:
function eta_dT "Return dynamic viscosity as a function of d and T"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.DynamicViscosity eta "Dynamic viscosity";
protected
  Real delta = d / (ReferenceAir.Air_Utilities.Basic.Constants.MM * ReferenceAir.Air_Utilities.Basic.Constants.rhored) "Reduced density";
  Real tau = ReferenceAir.Air_Utilities.Basic.Constants.Tred / T "Reciprocal reduced temperature";
  Real Omega "Collision integral";
  Modelica.Units.SI.DynamicViscosity eta_0 = 0 "Dilute gas viscosity";
  Modelica.Units.SI.DynamicViscosity eta_r = 0 "Residual fluid viscosity";
  final constant Real[5] b = {0.431, -0.4623, 0.08406, 0.005341, -0.00331};
  final constant Real[5] Nvis = {10.72, 1.122, 0.002019, -8.876, -0.02916};
  final constant Real[5] tvis = {0.2, 0.05, 2.4, 0.6, 3.6};
  final constant Integer[5] dvis = {1, 4, 9, 1, 8};
  final constant Integer[5] lvis = {0, 0, 0, 1, 1};
  final constant Integer[5] gammavis = {0, 0, 0, 1, 1};
algorithm
  Omega := exp(Modelica.Math.Polynomials.evaluate({b[5], b[4], b[3], b[2], b[1]}, log(T / 103.3)));
  eta_0 := 0.0266958 * sqrt(1000 * ReferenceAir.Air_Utilities.Basic.Constants.MM * T) / (0.36 ^ 2 * Omega);
  for i in 1:5 loop
    eta_r := eta_r + Nvis[i] * tau ^ tvis[i] * delta ^ dvis[i] * exp(-gammavis[i] * delta ^ lvis[i]);
  end for;
  eta := (eta_0 + eta_r) * 1E-006;
end eta_dT;

modelica://Modelica.Media/lambda_dT:
Modelica.Media: lambda_dT (function)

Code:
function lambda_dT "Return thermal conductivity as a function of d and T"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.ThermalConductivity lambda "Thermal conductivity";
protected
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Units.SI.ThermalConductivity lambda_0 = 0 "Dilute gas thermal conductivity";
  Modelica.Units.SI.ThermalConductivity lambda_r = 0 "Residual fluid thermal conductivity";
  Modelica.Units.SI.ThermalConductivity lambda_c = 0 "Thermal conductivity critical enhancement";
  Real Omega "Collision integral";
  Modelica.Units.SI.DynamicViscosity eta_0 = 0 "Dilute gas viscosity";
  Real pddT;
  Real pddTref;
  Real pdTp;
  Real xi;
  Real xiref;
  Real Omega_tilde;
  Real Omega_0_tilde;
  Real cv;
  Real cp;
  final constant Real[5] b = {0.431, -0.4623, 0.08406, 0.005341, -0.00331};
  final constant Real[9] Ncon = {1.308, 1.405, -1.036, 8.743, 14.76, -16.62, 3.793, -6.142, -0.3778};
  final constant Real[9] tcon = {0.0, -1.1, -0.3, 0.1, 0.0, 0.5, 2.7, 0.3, 1.3};
  final constant Integer[9] dcon = {0, 0, 0, 1, 2, 3, 7, 7, 11};
  final constant Integer[9] lcon = {0, 0, 0, 0, 0, 2, 2, 2, 2};
  final constant Integer[9] gammacon = {0, 0, 0, 0, 0, 1, 1, 1, 1};
algorithm
  //chi_tilde in at the reference temperature 265.262
  f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(d, 265.262);
  pddTref := ReferenceAir.Air_Utilities.Basic.Constants.R_bar * 265.262 * (1 + 2 * f.delta * (f.fdelta - 1 / f.delta) + f.delta ^ 2 * (f.fdeltadelta + 1 / f.delta ^ 2));
  xiref := ReferenceAir.Air_Utilities.Basic.Constants.pred * (d / ReferenceAir.Air_Utilities.Basic.Constants.MM) / ReferenceAir.Air_Utilities.Basic.Constants.rhored ^ 2 / pddTref;
  //calculating f at the given state
  f := Modelica.Media.Air.ReferenceAir.Air_Utilities.Basic.Helmholtz(d, T);
  Omega := exp(Modelica.Math.Polynomials.evaluate({b[5], b[4], b[3], b[2], b[1]}, log(T / 103.3)));
  //Ideal-gas part of dynamic viscosity
  eta_0 := 0.0266958 * sqrt(1000 * ReferenceAir.Air_Utilities.Basic.Constants.MM * T) / (0.36 ^ 2 * Omega);
  //Ideal-gas part of thermal conductivity
  lambda_0 := Ncon[1] * eta_0 + Ncon[2] * f.tau ^ tcon[2] + Ncon[3] * f.tau ^ tcon[3];
  //Residual part of thermal conductivity
  for i in 4:9 loop
    lambda_r := lambda_r + Ncon[i] * f.tau ^ tcon[i] * f.delta ^ dcon[i] * exp(-gammacon[i] * f.delta ^ lcon[i]);
  end for;
  //Derivative of p w.r.t. d at constant temperature
  pddT := ReferenceAir.Air_Utilities.Basic.Constants.R_s * T * (1 + 2 * f.delta * (f.fdelta - 1 / f.delta) + f.delta ^ 2 * (f.fdeltadelta + 1 / f.delta ^ 2));
  //chi_tilde at the given state
  xi := ReferenceAir.Air_Utilities.Basic.Constants.pred * (d / ReferenceAir.Air_Utilities.Basic.Constants.MM) / ReferenceAir.Air_Utilities.Basic.Constants.rhored ^ 2 / (pddT * ReferenceAir.Air_Utilities.Basic.Constants.MM);
  //Thermal conductivity critical enhancement
  xi := xi - xiref * 265.262 / T;
  if xi <= 0 then
    lambda_c := 0;
  else
    xi := 0.11 * (xi / 0.055) ^ (0.63 / 1.2415);
    //Derivative of p w.r.t. T at constant p
    pdTp := ReferenceAir.Air_Utilities.Basic.Constants.R_s * d * (1 + f.delta * (f.fdelta - 1 / f.delta) - f.delta * f.tau * f.fdeltatau);
    //Specific isochoric heat capacity
    cv := ReferenceAir.Air_Utilities.Basic.Constants.R_s * (-f.tau * f.tau * f.ftautau);
    //Specific isobaric heat capacity
    cp := cv + T * pdTp * pdTp / (d * d * pddT);
    Omega_tilde := 2 / Modelica.Constants.pi * ((cp - cv) / cp * atan(xi / 0.31) + cv / cp * xi / 0.31);
    Omega_0_tilde := 2 / Modelica.Constants.pi * (1 - exp(-1 / (0.31 / xi + 1 / 3 * (xi / 0.31) ^ 2 * (ReferenceAir.Air_Utilities.Basic.Constants.rhored / (d / ReferenceAir.Air_Utilities.Basic.Constants.MM)) ^ 2)));
    lambda_c := d * cp * 1.380658E-023 * 1.01 * T / (6 * Modelica.Constants.pi * xi * Modelica.Media.Air.ReferenceAir.Air_Utilities.Transport.eta_dT(d, T)) * (Omega_tilde - Omega_0_tilde) * 1E012;
  end if;
  lambda := (lambda_0 + lambda_r + lambda_c) / 1000;
end lambda_dT;

