end T_phX;

modelica://Modelica.Media/h_pTX:
Modelica.Media: h_pTX (function)

Specific enthalpy of moist air is computed from pressure, temperature and composition with X[1] as the total water mass fraction. The fog region is included for both, ice and liquid fog.

Code:
function h_pTX "Return specific enthalpy of moist air as a function of pressure p, temperature T and composition X"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] "Mass fractions of moist air";
  output Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy at p, T, X";
protected
  Modelica.Units.SI.AbsolutePressure p_steam_sat "Partial saturation pressure of steam";
  Modelica.Units.SI.MassFraction X_sat "Absolute humidity per unit mass of moist air";
  Modelica.Units.SI.MassFraction X_liquid "Mass fraction of liquid water";
  Modelica.Units.SI.MassFraction X_steam "Mass fraction of steam water";
  Modelica.Units.SI.MassFraction X_air "Mass fraction of air";
algorithm
  p_steam_sat := Modelica.Media.Air.MoistAir.saturationPressure(T);
  //p_steam_sat :=min(saturationPressure(T), 0.999*p);
  X_sat := min(p_steam_sat * k_mair / max(100 * Constants.eps, p - p_steam_sat) * (1 - X[Modelica.Media.Water]), 1.0);
  X_liquid := max(X[Modelica.Media.Water] - X_sat, 0.0);
  X_steam := X[Modelica.Media.Water] - X_liquid;
  X_air := 1 - X[Modelica.Media.Water];
  /* h        := {SingleGasNasa.h_Tlow(data=steam,  T=T, refChoice=ReferenceEnthalpy.UserDefined, h_off=46479.819+2501014.5),
               SingleGasNasa.h_Tlow(data=dryair, T=T, refChoice=ReferenceEnthalpy.UserDefined, h_off=25104.684)}*
    {X_steam, X_air} + enthalpyOfLiquid(T)*X_liquid;*/
  h := {Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = steam, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 46479.819 + 2501014.5), Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = dryair, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 25104.684)} * {X_steam, X_air} + Modelica.Media.Air.MoistAir.enthalpyOfWater(T) * X_liquid;

end h_pTX;

modelica://Modelica.Media/h_pTX_der:
Modelica.Media: h_pTX_der (function)

Derivative function for h_pTX .

Code:
function h_pTX_der "Derivative function of h_pTX"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] "Mass fractions of moist air";
  input Real dp(unit = "Pa/s") "Pressure derivative";
  input Real dT(unit = "K/s") "Temperature derivative";
  input Real dX[:](each unit = "1/s") "Composition derivative";
  output Real h_der(unit = "J/(kg.s)") "Time derivative of specific enthalpy";
protected
  Modelica.Units.SI.AbsolutePressure p_steam_sat "Partial saturation pressure of steam";
  Modelica.Units.SI.MassFraction X_sat "Absolute humidity per unit mass of moist air";
  Modelica.Units.SI.MassFraction X_liquid "Mass fraction of liquid water";
  Modelica.Units.SI.MassFraction X_steam "Mass fraction of steam water";
  Modelica.Units.SI.MassFraction X_air "Mass fraction of air";
  Modelica.Units.SI.MassFraction x_sat "Absolute humidity per unit mass of dry air at saturation";
  Real dX_steam(unit = "1/s") "Time derivative of steam mass fraction";
  Real dX_air(unit = "1/s") "Time derivative of dry air mass fraction";
  Real dX_liq(unit = "1/s") "Time derivative of liquid/solid water mass fraction";
  Real dps(unit = "Pa/s") "Time derivative of saturation pressure";
  Real dx_sat(unit = "1/s") "Time derivative of absolute humidity per unit mass of dry air";
algorithm
  p_steam_sat := Modelica.Media.Air.MoistAir.saturationPressure(T);
  x_sat := p_steam_sat * k_mair / max(100 * Modelica.Constants.eps, p - p_steam_sat);
  X_sat := min(x_sat * (1 - X[Modelica.Media.Water]), 1.0);
  X_liquid := Modelica.Media.Air.MoistAir.Utilities.smoothMax(X[Modelica.Media.Water] - X_sat, 0.0, 1e-5);
  X_steam := X[Modelica.Media.Water] - X_liquid;
  X_air := 1 - X[Modelica.Media.Water];
  dX_air := -dX[Modelica.Media.Water];
  dps := Modelica.Media.Air.MoistAir.saturationPressure_der(Tsat = T, dTsat = dT);
  dx_sat := k_mair * (dps * (p - p_steam_sat) - p_steam_sat * (dp - dps)) / (p - p_steam_sat) / (p - p_steam_sat);
  dX_liq := Modelica.Media.Air.MoistAir.Utilities.smoothMax_der(X[Modelica.Media.Water] - X_sat, 0.0, 1e-5, (1 + x_sat) * dX[Modelica.Media.Water] - (1 - X[Modelica.Media.Water]) * dx_sat, 0, 0);
  dX_steam := dX[Modelica.Media.Water] - dX_liq;
  h_der := X_steam * Modelica.Media.IdealGases.Common.Functions.h_Tlow_der(data = steam, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 46479.819 + 2501014.5, dT = dT) + dX_steam * Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = steam, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 46479.819 + 2501014.5) + X_air * Modelica.Media.IdealGases.Common.Functions.h_Tlow_der(data = dryair, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 25104.684, dT = dT) + dX_air * Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = dryair, T = T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 25104.684) + X_liquid * Modelica.Media.Air.MoistAir.enthalpyOfWater_der(T = T, dT = dT) + dX_liq * Modelica.Media.Air.MoistAir.enthalpyOfWater(T);

end h_pTX_der;

