modelica://Modelica.Media/isentropicEnth:
Modelica.Media: isentropicEnthalpyApproximation (function)

Code:
function isentropicEnthalpyApproximation "Approximate calculation of h_is from upstream properties, downstream pressure, gas part only"
  extends Modelica.Icons.Function;
  input Modelica.Media.Air.MoistAir.AbsolutePressure p2 "Downstream pressure";
  input Modelica.Media.Air.MoistAir.ThermodynamicState state "Thermodynamic state at upstream location";
  output Modelica.Media.Air.MoistAir.SpecificEnthalpy h_is "Isentropic enthalpy";
protected
  Modelica.Media.Air.MoistAir.SpecificEnthalpy h "Specific enthalpy at upstream location";
  Modelica.Media.Air.MoistAir.IsentropicExponent gamma = Modelica.Media.Air.MoistAir.isentropicExponent(state) "Isentropic exponent";
protected
  Modelica.Media.Air.MoistAir.MassFraction[nX] X "Complete X-vector";
algorithm
  X := state.X;
  //  X := if reducedX then cat(1,state.X,{1-sum(state.X)}) else state.X;
  h := {Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = steam, T = state.T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 46479.819 + 2501014.5), Modelica.Media.IdealGases.Common.Functions.h_Tlow(data = dryair, T = state.T, refChoice = Modelica.Media.Interfaces.Choices.ReferenceEnthalpy.UserDefined, h_off = 25104.684)} * X;
  h_is := h + gamma / (gamma - 1.0) * (state.T * Modelica.Media.Air.MoistAir.gasConstant(state)) * ((p2 / state.p) ^ ((gamma - 1) / gamma) - 1.0);
end isentropicEnthalpyApproximation;

