model extends BaseProperties(T(stateSelect = if preferredMediumStates then StateSelect.prefer else StateSelect.default), p(stateSelect = if preferredMediumStates then StateSelect.prefer else StateSelect.default), Xi(each stateSelect = if preferredMediumStates then StateSelect.prefer else StateSelect.default), final standardOrderComponents = true) "Moist air base properties record"
    Real x_water "Mass of total water/mass of dry air";
    Real phi "Relative humidity";

  protected
  Modelica.Media.Air.ReferenceMoistAir.MassFraction X_liquid "Mass fraction of liquid or solid water";
  Modelica.Media.Air.ReferenceMoistAir.MassFraction X_steam "Mass fraction of steam water";
  Modelica.Media.Air.ReferenceMoistAir.MassFraction X_air "Mass fraction of air";
  Modelica.Media.Air.ReferenceMoistAir.    MassFraction X_sat "Steam water mass fraction of saturation boundary in kg_water/kg_moistair";
    Real x_sat "Steam water mass content of saturation boundary in kg_water/kg_dryair";
  Modelica.Media.Air.ReferenceMoistAir.AbsolutePressure p_steam_sat "Partial saturation pressure of steam";

  equation
    assert(T >= 143.15 and T <= 2000, "Temperature T is not in the allowed range 143.15 K <= (T =" + String(T) + " K) <= 2000 K required from medium model \"" + mediumName + "\".");
    MM = 1 / (Xi[Modelica.Media.Water] / MMX[Modelica.Media.Water] + (1.0 - Xi[Modelica.Media.Water]) / MMX[Modelica.Media.Air]);
    p_steam_sat = Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT(p, T);
    X_sat = Modelica.Media.Air.ReferenceMoistAir.Xsaturation(state);
    X_liquid = max(Xi[Modelica.Media.Water] - X_sat, 0.0);
    X_steam = Xi[Modelica.Media.Water] - X_liquid;
    X_air = 1 - Xi[Modelica.Media.Water];
    h = Modelica.Media.Air.ReferenceMoistAir.specificEnthalpy_pTX(p, T, Xi);
    R_s = dryair.R_s * (X_air / (1 - X_liquid)) + steam.R_s * X_steam / (1 - X_liquid);
    u = Modelica.Media.Air.ReferenceMoistAir.Utilities.u_pTX(p, T, Xi);
    d = Modelica.Media.Air.ReferenceMoistAir.Utilities.rho_pTX(p, T, Xi);
    state.p = p;
    state.T = T;
    state.X = X;
    // these x are per unit mass of DRY air!
    x_sat = Modelica.Media.Air.ReferenceMoistAir.xsaturation(state);
    x_water = Modelica.Media.Air.ReferenceMoistAir.waterContent_X(state.X);
    phi = Modelica.Media.Air.ReferenceMoistAir.Utilities.phi_pTX(p, T, Xi);

end BaseProperties;

