Code:
function extends massFraction_pTphi "Return mass fractions as a function of pressure, temperature and relative humidity"
  protected
    Real pds;

  algorithm
    assert(phi < 1.0 and phi > 0, "Illegal input phi = " + String(phi) + ". Relative humidity is only defined in the range\n 0 <= phi <= 1.0.");
    pds := Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT(p, T);
    assert(pds > -1, "Calculation of mass fraction of steam is meaningless\nfor input pressure p = " + String(p) + " Pa and temperature T = " + String(T) + " K.");
