modelica://Modelica.Media/massFractionWa:
Modelica.Media: massFractionWaterVapor (function)

Code:
function massFractionWaterVapor "Return mass fraction of water vapor"
  extends Modelica.Icons.Function;
  input Modelica.Media.Air.ReferenceMoistAir.ThermodynamicState state "Thermodynamic state record";
  output Modelica.Media.Air.ReferenceMoistAir.MassFraction X "Mass fraction of water vapor";
protected
  Real xw;
  Real xws;
algorithm
  xw := state.X[1] / max(100 * Modelica.Constants.eps, 1 - state.X[1]);
  xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(state.p, state.T);
  X := if xw <= xws then xw / (1 + xw) else xws / (1 + xw);

end massFractionWaterVapor;

