Code:
function extends massFractionSaturation "Return saturation mass fractions"
  protected
  Modelica.Media.Air.ReferenceMoistAir.    AbsolutePressure pds;

  algorithm
    pds := Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT(state.p, state.T);
    Xsat := {k_mair / (state.p / pds - 1 + k_mair), (state.p / pds - 1) / (state.p / pds - 1 + k_mair)};
    assert(Xsat[1] > -1, "Calculation of saturation mass fraction is meaningless\nfor input pressure p = " + String(state.p) + " Pa and temperature T = " + String(state.T) + " K.");
end massFractionSaturation;

