    Real xws;

  algorithm
    xw := state.X[1] / (1 - state.X[1]);
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(state.p, state.T);
    if xws > xw and state.T > 273.15 then
      h := Modelica.Media.Water.IF97_Utilities.h_pT(state.p, state.T, region = 1);
    else
      h := 0;
    end if;
end enthalpyOfLiquid;

modelica://Modelica.Media/enthalpyOfGas-:
Modelica.Media: enthalpyOfGas (function)

Code:
function extends enthalpyOfGas "Return specific enthalpy of gas (air and steam)"
  protected
    Real xw;
    Real xws;
    Real pd;
    Real pl;

  algorithm
    pd := Modelica.Media.Air.ReferenceMoistAir.Utilities.pd_pTX(state.p, state.T, state.X);
    pl := state.p - pd;
    xw := state.X[1] / (1 - state.X[1]);
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(state.p, state.T);
    if xw <= xws or xws == -1 then
      h := Modelica.Media.Air.ReferenceAir.Air_Utilities.h_pT(pl, state.T) + xw * Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.h_pT(pd, state.T);
    else
      if state.T < 273.16 then
        h := Modelica.Media.Air.ReferenceAir.Air_Utilities.h_pT(pl, state.T) + xws * Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.h_pT(pd, state.T);
      else
        h := Modelica.Media.Air.ReferenceAir.Air_Utilities.h_pT(pl, state.T) + xws * Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.h_pT(pd, state.T);
      end if;
    end if;

end enthalpyOfGas;

