function beta_H "Henry's law constant"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Real beta_H(unit = "1/Pa") "Henry's law constant";
protected
  Real[3] A = {-9.67578, -9.44833, -8.40954};
  Real[3] B = {4.72162, 4.43822, 4.29587};
  Real[3] C = {11.70585, 11.42005, 10.52779};
  Real[3] psi = {0.7812, 0.2095, 0.0093};
  Real[3] beta = fill(0, 3);
  Real Tr = T / 647.096;
  Real tau = 1 - Tr;
algorithm
  if T < 273.15 or T > Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.Tsat(p) then
    beta_H := 0;
  else
    for k in 1:3 loop
      beta[k] := Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.psat(T) * exp(A[k] / Tr + B[k] * tau ^ 0.355 / Tr + C[k] * Tr ^ (-0.41) * exp(tau));
    end for;
    beta_H := 1 / 1.01325 * (psi[1] / Modelica.Media.Air.ReferenceMoistAir.beta[1] + psi[2] / Modelica.Media.Air.ReferenceMoistAir.beta[2] + psi[3] / Modelica.Media.Air.ReferenceMoistAir.beta[3]);
  end if;
end beta_H;

