function rho_pTX "Return density as a function of pressure p, temperature T and composition X"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  output Modelica.Units.SI.Density d "Density";
protected
  Real pd;
  Real pl;
  Real xw;
  Real xws;
algorithm
  if X[1] == 0 then
    d := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(p, T);
  else
    xw := X[1] / (1 - X[1]);
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(p, T);
    pd := Modelica.Media.Air.ReferenceMoistAir.Utilities.pd_pTX(p, T, X);
    pl := p - pd;
    if xw <= xws or xws == -1 then
      if T < 273.16 then
        d := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + pd / (Modelica.Media.Air.ReferenceMoistAir.steam.R_s * T);
      else
        d := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT(pd, T);
      end if;
    else
      if T < 273.16 then
        d := (1 + xw) / ((1 + xws) / (Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + pd / (Modelica.Media.Air.ReferenceMoistAir.steam.R_s * T)) + (xw - xws) / Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT(p, T));
      else
        d := (1 + xw) / ((1 + xws) / (Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT(pd, T)) + (xw - xws) / Modelica.Media.Water.IF97_Utilities.rho_pT(p, T));
      end if;
    end if;
  end if;

end rho_pTX;

