function phi_pTX "Relative humidity"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  output Real phi "Relative humidity";
protected
  Real xw;
  Real pd;
  Real pds;
algorithm
  if X[1] == 0 then
    phi := 0;
  else
    xw := X[1] / (1 - X[1]);
    if T >= 273.16 then
      pds := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.psat(T);
    else
      pds := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.psub(T);
    end if;
    pds := Modelica.Media.Air.ReferenceMoistAir.Utilities.f_pT(p, T) * pds;
    pd := xw / (Modelica.Media.Air.ReferenceMoistAir.k_mair + xw) * p;
    //     if (pd <= pds) then
    //       phi := pd/pds;
    //     else
    //       phi := -1;
    //     end if;
    phi := pd / max(100 * Modelica.Constants.eps, pds);
  end if;

end phi_pTX;

