function cp_pTX "Specific isobaric heat capacity"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  output Modelica.Units.SI.SpecificHeatCapacity cp "Specific heat capacity";
protected
  Real xw;
  Real xws;
  Real pd;
  Real pl;
algorithm
  if X[1] == 0.0 then
    if T >= 773.15 then
      cp := Modelica.Media.Air.ReferenceAir.Air_Utilities.cp_pT(p, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.cp_dis_pTX(p, T, X);
    else
      cp := Modelica.Media.Air.ReferenceAir.Air_Utilities.cp_pT(p, T);
    end if;
  else
    pd := Modelica.Media.Air.ReferenceMoistAir.Utilities.pd_pTX(p, T, X);
    pl := p - pd;
    xw := X[1] / (1 - X[1]);
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(p, T);
    if xw <= xws or xws == -1 then
      if T >= 773.15 then
        cp := X[1] * Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.cp_pT(pd, T) + X[2] * Modelica.Media.Air.ReferenceAir.Air_Utilities.cp_pT(pl, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.cp_dis_pTX(p, T, X);
      else
        cp := X[1] * Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.cp_pT(pd, T) + X[2] * Modelica.Media.Air.ReferenceAir.Air_Utilities.cp_pT(pl, T);
      end if;
    else
      cp := -1;
    end if;
  end if;

end cp_pTX;

