Code:
function h_dis_pTX
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  output Real u "Reaction index";
protected
  Real uges;
  Real invMMX[4] "Inverses of molar weights";
  Modelica.Units.SI.MolarMass Mmix "Molar mass of mixture";
  Modelica.Media.Air.ReferenceMoistAir.MassFraction[4] massFraction "Mass fractions of components";
  Modelica.Units.SI.MoleFraction[4] Y "Mole fractions of individual components (H2O, N2, O2, Ar) of moist air";
algorithm
  if useDissociation == false then
    u := 0;
  else
    massFraction := {X[1], X[2] * Xi_Air[1], X[2] * Xi_Air[2], X[2] * Xi_Air[3]};
    for i in 1:4 loop
      invMMX[i] := 1 / MMX[i];
    end for;
    Mmix := 1 / (massFraction * invMMX);
    for i in 1:4 loop
      Y[i] := Mmix * massFraction[i] / MMX[i];
    end for;
    uges := 1 + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U2(p, T, Y) + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U3(p, T, Y) + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U4(p, T, Y) + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U5(p, T, Y) + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U6(p, T, Y);
    u := -T ^ 2 * (Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U2(p, T, Y) * Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.V2(T) / Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.BB[2] + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U3(p, T, Y) * Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.V3(T) / Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.BB[3] + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U4(p, T, Y) * Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.V4(T) / Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.BB[4] + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U5(p, T, Y) * Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.V5(T) / Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.BB[5] + Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.U6(p, T, Y) * Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.V6(T) / Modelica.Media.Air.ReferenceMoistAir.Utilities.ReactionIndices.BB[6]) / uges * sum(massFraction[j] / MMX[j] for j in 1:4);
  end if;
end h_dis_pTX;

