function pd_pTX_der "Derivative of partial pressure of steam"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  input Real X_der[:] "Derivative of mass fractions";
  output Real pd_der "Derivative of partial pressure";
protected
  Real xw, xw_der;
  Real xws;
  Real pds, pds_der;
algorithm
  if X[1] == 0 then
    //pd := 0;
    pd_der := 0;
  else
    xw := X[1] / (1 - X[1]) "d(xw)/dt = d(xw)/dX[1] * dX[1]/dt";
    xw_der := (X_der[1] * (1 - X[1]) + X[1] * X_der[1]) / (1 - X[1]) ^ 2;
    pds_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT_der(p, T, p_der, T_der);
    //pd := xw/(Modelica.Media.Air.ReferenceMoistAir.k_mair + xw)*p;
    pd_der := (xw_der * (Modelica.Media.Air.ReferenceMoistAir.k_mair + xw) - xw * xw_der) * p + xw / (Modelica.Media.Air.ReferenceMoistAir.k_mair + xw) * p_der;
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(p, T);
    pd_der := if xw <= xws then pd_der else pds_der;
  end if;

end pd_pTX_der;

