Code:
function xws_pT_der "Derivative of humidity ration (absolute) of saturated humid air"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  output Real xws_der "Derivative of absolute humidity ratio";
protected
  Real pds, pds_der;
  Real Tlim;
algorithm
  pds := Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT(p, T);
  pds_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.pds_pT_der(p, T, p_der, T_der);
  Tlim := if T <= 273.16 then Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Tsub(p) else Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.Tsat(p);
  if pds < p then
    xws_der := Modelica.Media.Air.ReferenceMoistAir.k_mair * ((pds_der * (p - pds) + pds * pds_der) / (p - pds) ^ 2);
  else
    xws_der := 0;
  end if;

end xws_pT_der;

modelica://Modelica.Media/pds_pT_der:
Modelica.Media: pds_pT_der (function)

Code:
function pds_pT_der "Derivative of saturation partial pressure of steam"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  output Real pds_der "Derivative of pressure";
protected
  Real Tlim;
algorithm
  if T >= 273.16 then
    pds_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.psat_der(T, T_der);
    Tlim := Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.Tsat(p);
  else
    pds_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.psub_der(T, T_der);
    Tlim := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Tsub(p);
  end if;
  if T <= Tlim then
    pds_der := pds_der;
  else
    pds_der := p_der;
  end if;

end pds_pT_der;

