Code:
function rho_pTX_der "Derivative of density as a function of pressure p, temperature T and composition X"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  input Real X_der[:] "Derivative of mass fractions";
  output Real d_der "Derivative of density";
protected
  Real pd, pd_der;
  Real pl, pl_der;
  Real xw, xw_der;
  Real xws, xws_der;
  Real o[5];
algorithm
  if X[1] == 0 then
    d_der := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT_der(p, T, Modelica.Media.Air.ReferenceAir.Air_Utilities.airBaseProp_pT(p, T), p_der, T_der);
  else
    xw := X[1] / (1 - X[1]);
    xw_der := X_der[1] / (1 - X[1]) ^ 2;
    xws := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT(p, T);
    xws_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.xws_pT_der(p, T, p_der, T_der);
    pd := Modelica.Media.Air.ReferenceMoistAir.Utilities.pd_pTX(p, T, X);
    pd_der := Modelica.Media.Air.ReferenceMoistAir.Utilities.pd_pTX_der(p, T, X, p_der, T_der, X_der);
    pl := p - pd;
    pl_der := p_der - pd_der;
    if xw <= xws or xws == -1 then
      if T < 273.16 then
        d_der := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT_der(pl, T, Modelica.Media.Air.ReferenceAir.Air_Utilities.airBaseProp_pT(pl, T), pl_der, T_der) + Modelica.Media.Air.ReferenceMoistAir.steam.R_s * (pd_der * T - pd * T_der) / (Modelica.Media.Air.ReferenceMoistAir.steam.R_s * T) ^ 2;
      else
        d_der := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT_der(pl, T, Modelica.Media.Air.ReferenceAir.Air_Utilities.airBaseProp_pT(pl, T), pl_der, T_der) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT_der(pd, T, pd_der, T_der);
      end if;
    else
      if T < 273.16 then
        o[1] := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T);
        o[2] := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT(p, T);
        o[3] := (1 + xws) / (Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + pd / (Modelica.Media.Air.ReferenceMoistAir.steam.R_s * T)) + (xw - xws) / Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT(p, T);
        o[4] := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT_der(pl, T, Modelica.Media.Air.ReferenceAir.Air_Utilities.airBaseProp_pT(p, T), p_der, T_der);
        o[5] := (xws_der * o[1] - (1 + xws) * o[4]) / o[1] ^ 2 + (pd_der * T - pd * T_der) / Modelica.Media.Air.ReferenceMoistAir.steam.R_s / T ^ 2 + (xw_der * o[2] - xw * Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT_der(p, T, Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.ice09BaseProp_pT(p, T), p_der, T_der)) / o[2] ^ 2 - (xws_der * o[2] - xws * Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT_der(p, T, Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.ice09BaseProp_pT(p, T), p_der, T_der)) / o[2] ^ 2;
        d_der := (xw_der * o[3] - (1 + xw) * o[5]) / o[3] ^ 2;
      else
        o[1] := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT(pd, T);
        o[2] := Modelica.Media.Water.IF97_Utilities.rho_pT(p, T);
        o[3] := (1 + xws) / (Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT(pl, T) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT(pd, T)) + (xw - xws) / Modelica.Media.Water.IF97_Utilities.rho_pT(p, T);
        o[4] := Modelica.Media.Air.ReferenceAir.Air_Utilities.rho_pT_der(pl, T, Modelica.Media.Air.ReferenceAir.Air_Utilities.airBaseProp_pT(p, T), p_der, T_der) + Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.rho_pT_der(pd, T, pd_der, T_der);
        o[5] := (xws_der * o[1] - (1 + xws) * o[4]) / o[1] ^ 2 + (xw_der * o[2] - xw * Modelica.Media.Water.IF97_Utilities.rho_pT_der(p, T, Modelica.Media.Water.IF97_Utilities.waterBaseProp_pT(p, T), p_der, T_der)) / o[2] ^ 2 - (xws_der * o[2] - xws * Modelica.Media.Water.IF97_Utilities.rho_pT_der(p, T, Modelica.Media.Water.IF97_Utilities.waterBaseProp_pT(p, T), p_der, T_der)) / o[2] ^ 2;
        d_der := (xw_der * o[3] - (1 + xw) * o[5]) / o[3] ^ 2;
      end if;
    end if;
  end if;
end rho_pTX_der;

modelica://Modelica.Media/h_dis_pTX_der:
Modelica.Media: h_dis_pTX_der (function)

Code:
function h_dis_pTX_der
  extends Modelica.Icons.Function;
  import Modelica.Media.Air.ReferenceMoistAir.Utilities;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MassFraction X[:] = Modelica.Media.Air.ReferenceMoistAir.reference_X "Mass fractions";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  input Real X_der[:] "Derivative of mass fractions";
  output Real u_der "Derivative of reaction index";
protected
  Real uges, uges_der, o[7], l;
  Real invMMX[4] "Inverses of molar weights";
  Modelica.Units.SI.MolarMass Mmix "Molar mass of mixture";
  Real Mmix_der "Derivative of molar mass of mixture";
  Modelica.Media.Air.ReferenceMoistAir.MassFraction[4] massFraction "Mass fractions of components";
  Real[4] massFraction_der "Derivative of mass fractions of components";
  Modelica.Units.SI.MoleFraction[4] Y "Mole fractions of individual components (H2O, N2, O2, Ar) of moist air";
  Real[4] Y_der "Derivative of mole fractions of individual components (H2O, N2, O2, Ar) of moist air";
algorithm
  if useDissociation == false then
    //u := 0;
    u_der := 0;
  else
    massFraction := {X[1], X[2] * Xi_Air[1], X[2] * Xi_Air[2], X[2] * Xi_Air[3]};
    massFraction_der := {X_der[1], X_der[2] * Xi_Air[1], X_der[2] * Xi_Air[2], X_der[2] * Xi_Air[3]};
    for i in 1:4 loop
      invMMX[i] := 1 / MMX[i];
    end for;
    Mmix := 1 / (massFraction * invMMX);
    Mmix_der := -1 / (massFraction * invMMX) ^ 2 * massFraction_der * invMMX;
    for i in 1:4 loop
      Y[i] := Mmix * massFraction[i] / MMX[i];
      Y_der[i] := (Mmix_der * massFraction[i] + Mmix * massFraction_der[i]) / MMX[i];
    end for;
    uges := 1 + Utilities.ReactionIndices.U2(p, T, Y) + Utilities.ReactionIndices.U3(p, T, Y) + Utilities.ReactionIndices.U4(p, T, Y) + Utilities.ReactionIndices.U5(p, T, Y) + Utilities.ReactionIndices.U6(p, T, Y);
    uges_der := Utilities.ReactionIndices.U2_der(p, T, Y, p_der, T_der, Y_der) + Utilities.ReactionIndices.U3_der(p, T, Y, p_der, T_der, Y_der) + Utilities.ReactionIndices.U4_der(p, T, Y, p_der, T_der, Y_der) + Utilities.ReactionIndices.U5_der(p, T, Y, p_der, T_der, Y_der) + Utilities.ReactionIndices.U6_der(p, T, Y, p_der, T_der, Y_der);
    o[1] := (Utilities.ReactionIndices.U2_der(p, T, Y, p_der, T_der, Y_der) * Utilities.ReactionIndices.V2(T) + Utilities.ReactionIndices.U2(p, T, Y) * Utilities.ReactionIndices.V2_der(T, T_der)) / Utilities.ReactionIndices.BB[2];
    o[2] := (Utilities.ReactionIndices.U3_der(p, T, Y, p_der, T_der, Y_der) * Utilities.ReactionIndices.V3(T) + Utilities.ReactionIndices.U3(p, T, Y) * Utilities.ReactionIndices.V3_der(T, T_der)) / Utilities.ReactionIndices.BB[3];
    o[3] := (Utilities.ReactionIndices.U4_der(p, T, Y, p_der, T_der, Y_der) * Utilities.ReactionIndices.V4(T) + Utilities.ReactionIndices.U4(p, T, Y) * Utilities.ReactionIndices.V4_der(T, T_der)) / Utilities.ReactionIndices.BB[4];
    o[4] := (Utilities.ReactionIndices.U5_der(p, T, Y, p_der, T_der, Y_der) * Utilities.ReactionIndices.V5(T) + Utilities.ReactionIndices.U5(p, T, Y) * Utilities.ReactionIndices.V5_der(T, T_der)) / Utilities.ReactionIndices.BB[5];
    o[5] := (Utilities.ReactionIndices.U6_der(p, T, Y, p_der, T_der, Y_der) * Utilities.ReactionIndices.V6(T) + Utilities.ReactionIndices.U6(p, T, Y) * Utilities.ReactionIndices.V6_der(T, T_der)) / Utilities.ReactionIndices.BB[6];
    l := Utilities.ReactionIndices.U2(p, T, Y) * Utilities.ReactionIndices.V2(T) / Utilities.ReactionIndices.BB[2] + Utilities.ReactionIndices.U3(p, T, Y) * Utilities.ReactionIndices.V3(T) / Utilities.ReactionIndices.BB[3] + Utilities.ReactionIndices.U4(p, T, Y) * Utilities.ReactionIndices.V4(T) / Utilities.ReactionIndices.BB[4] + Utilities.ReactionIndices.U5(p, T, Y) * Utilities.ReactionIndices.V5(T) / Utilities.ReactionIndices.BB[5] + Utilities.ReactionIndices.U6(p, T, Y) * Utilities.ReactionIndices.V6(T) / Utilities.ReactionIndices.BB[6];
    o[6] := -2 * T * (Utilities.ReactionIndices.U2(p, T, Y) * Utilities.ReactionIndices.V2(T) / Utilities.ReactionIndices.BB[2] + Utilities.ReactionIndices.U3(p, T, Y) * Utilities.ReactionIndices.V3(T) / Utilities.ReactionIndices.BB[3] + Utilities.ReactionIndices.U4(p, T, Y) * Utilities.ReactionIndices.V4(T) / Utilities.ReactionIndices.BB[4] + Utilities.ReactionIndices.U5(p, T, Y) * Utilities.ReactionIndices.V5(T) / Utilities.ReactionIndices.BB[5] + Utilities.ReactionIndices.U6(p, T, Y) * Utilities.ReactionIndices.V6(T) / Utilities.ReactionIndices.BB[6]) - T ^ 2 * sum(o[1:5]);
    o[7] := uges_der * sum(massFraction[j] / MMX[j] for j in 1:4) + uges * sum(massFraction_der[j] / MMX[j] for j in 1:4);
    u_der := (o[6] * (uges * sum(massFraction[j] / MMX[j] for j in 1:4)) - l * o[7]) / (uges * sum(massFraction[j] / MMX[j] for j in 1:4)) ^ 2;
  end if;
end h_dis_pTX_der;

