function Baa_dT "Second molar virial coefficient of dry air"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.MolarVolume baa "Second virial coefficient";
protected
  final constant Real[19] N = {0.118160747229, 0.713116392079, -0.161824192067E+001, 0.714140178971E-001, -0.865421396646E-001, 0.134211176704, 0.112626704218E-001, -0.420533228842E-001, 0.349008431982E-001, 0.164957183186E-003, -0.101365037912, -0.173813690970, -0.472103183731E-001, -0.122523554253E-001, -0.146629609713, -0.316055879821E-001, 0.233594806142E-003, 0.148287891978E-001, -0.938782884667E-002};
  final constant Integer[19] i = {1, 1, 1, 2, 3, 3, 4, 4, 4, 6, 1, 3, 5, 6, 1, 3, 11, 1, 3};
  final constant Real[19] j = {0, 0.33, 1.01, 0, 0, 0.15, 0, 0.2, 0.35, 1.35, 1.6, 0.8, 0.95, 1.25, 3.6, 6, 3.25, 3.5, 15};
  Real tau = ReferenceAir.Air_Utilities.Basic.Constants.Tred / T;
algorithm
  baa := 0;
  for k in 1:19 loop
    baa := if i[k] == 1 then baa + N[k] * tau ^ j[k] else baa;
  end for;
  baa := 1 / ReferenceAir.Air_Utilities.Basic.Constants.rhored * baa;
end Baa_dT;

