modelica://Modelica.Media/U2_der:
Modelica.Media: U2_der (function)

Code:
function U2_der "Derivative reaction index for formation of H2"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.MoleFraction[4] moleFraction "Mole fractions";
  input Real p_der "Derivative of pressure";
  input Real T_der "Derivative of temperature";
  input Real[4] moleFraction_der "Derivative of mole fractions";
  output Real u_der "Derivative of reaction index for H2";
protected
  Real o[4];
algorithm
  o[1] := AA[2] * sqrt(moleFraction[3]) * (p / p0) ^ (-0.5) * Modelica.Math.exp(BB[2] / T);
  o[2] := -0.5 * AA[2] * moleFraction[1] / moleFraction[3] ^ 1.5 * (p / p0) ^ (-0.5) * Modelica.Math.exp(BB[2] / T);
  o[3] := -0.5 * AA[2] * moleFraction[1] / sqrt(moleFraction[3]) * sqrt(p0) * p ^ (-1.5) * Modelica.Math.exp(BB[2] / T);
  o[4] := -BB[2] * AA[2] * moleFraction[1] / sqrt(moleFraction[3]) * (p / p0) ^ (-0.5) * Modelica.Math.exp(BB[2] / T) / T ^ 2;
  u_der := o[1] * moleFraction_der[1] + o[2] * moleFraction_der[3] + o[3] * p_der + o[4] * T_der;
end U2_der;

modelica://Modelica.Media/U3_der:
