modelica://Modelica.Media/cv_pT-2:
Modelica.Media: cv_pT (function)

Code:
function cv_pT "Specific heat capacity at constant volume as function of pressure and temperature for region 2"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Integer region = 0 "If 0, region is unknown, otherwise known and this input (unused)";
  output Modelica.Units.SI.SpecificHeatCapacity cv "Specific heat capacity";
protected
  Modelica.Media.Common.GibbsDerivs g;
algorithm
  g := Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.g2(p, T);
  cv := g.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
end cv_pT;

modelica://Modelica.Media/rho_pT-2:
