  Real vt;
algorithm
  g := Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.g2(p, T);
  vt := g.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
  rho := max(p / (g.R_s * T * g.pi * g.gpi), 1e-9);
  h_der := (1 / rho - T * vt) * p_der - g.R_s * g.tau * g.tau * g.gtautau * T_der;
end h_pT_der;

modelica://Modelica.Media/psat:
Modelica.Media: psat (function)

Code:
function psat "Saturation pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.AbsolutePressure p "Pressure";
protected
  Real theta_s;
  Real A;
  Real B;
  Real C;
  final constant Real[10] n = {0.11670521452767E+004, -0.72421316703206E+006, -0.17073846940092E+002, 0.1202082470247E+005, -0.32325550322333E+007, 0.1491510861353E+002, -0.48232657361591E+004, 0.40511340542057E+006, -0.23855557567849, 0.65017534844798E+003};
algorithm
  theta_s := min(T, 553) + n[9] / (min(T, 553) - n[10]);
  A := theta_s ^ 2 + n[1] * theta_s + n[2];
  B := n[3] * theta_s ^ 2 + n[4] * theta_s + n[5];
  C := n[6] * theta_s ^ 2 + n[7] * theta_s + n[8];
  p := (2 * C / (-B + sqrt(B ^ 2 - 4 * A * C))) ^ 4 * 1E+006;

end psat;

modelica://Modelica.Media/Tsat:
Modelica.Media: Tsat (function)

Code:
function Tsat "Saturation temperature"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  output Modelica.Units.SI.Temperature T "Temperature";
protected
  Real beta;
  Real D;
  Real E;
  Real F;
  Real G;
  final constant Real[10] n = {0.11670521452767E+004, -0.72421316703206E+006, -0.17073846940092E+002, 0.1202082470247E+005, -0.32325550322333E+007, 0.1491510861353E+002, -0.48232657361591E+004, 0.40511340542057E+006, -0.23855557567849, 0.65017534844798E+003};
algorithm
  beta := (p * 1E-006) ^ 0.25;
  E := Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[3] * Modelica.Media.Air.ReferenceMoistAir.beta + n[6];
  F := n[1] * Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[4] * Modelica.Media.Air.ReferenceMoistAir.beta + n[7];
  G := n[2] * Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[5] * Modelica.Media.Air.ReferenceMoistAir.beta + n[8];
  D := 2 * G / (-F - sqrt(F ^ 2 - 4 * E * G));
  T := (n[10] + D - sqrt((n[10] + D) ^ 2 - 4 * (n[9] + n[10] * D))) / 2;

end Tsat;

modelica://Modelica.Media/psat_der:
Modelica.Media: psat_der (function)

Code:
function psat_der "Saturation pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Temperature T "Temperature";
  input Real T_der "Derivative of temperature";
  output Real p_der "Derivative of pressure w.r.t. temperature";
protected
  Real theta_s, theta_s_der;
  Real A, A_der;
  Real B, B_der;
  Real C, C_der, o_der[3];
  final constant Real[10] n = {0.11670521452767E+004, -0.72421316703206E+006, -0.17073846940092E+002, 0.1202082470247E+005, -0.32325550322333E+007, 0.1491510861353E+002, -0.48232657361591E+004, 0.40511340542057E+006, -0.23855557567849, 0.65017534844798E+003};
algorithm
  theta_s := min(T, 553) + n[9] / (min(T, 553) - n[10]);
  theta_s_der := 1 - n[9] / (min(T, 553) - n[10]) ^ 2;
  A := theta_s ^ 2 + n[1] * theta_s + n[2];
  B := n[3] * theta_s ^ 2 + n[4] * theta_s + n[5];
  C := n[6] * theta_s ^ 2 + n[7] * theta_s + n[8];
  A_der := 2 * theta_s * theta_s_der + n[1] * theta_s_der;
  B_der := 2 * n[3] * theta_s * theta_s_der + n[4] * theta_s_der;
  C_der := 2 * n[6] * theta_s * theta_s_der + n[7] * theta_s_der;
  o_der[1] := 2 * B * B_der - 4 * (A * C_der + A_der * C);
  o_der[2] := -B_der + 0.5 / sqrt(B ^ 2 - 4 * A * C) * o_der[1];
  o_der[3] := (2 * C_der * (-B + sqrt(B ^ 2 - 4 * A * C)) - 2 * C * o_der[2]) / (-B + sqrt(B ^ 2 - 4 * A * C)) ^ 2;
  p_der := 4 * (2 * C / (-B + sqrt(B ^ 2 - 4 * A * C))) ^ 3 * o_der[3] * 1E+006 * T_der;
end psat_der;

modelica://Modelica.Media/Tsat_der:
Modelica.Media: Tsat_der (function)

Code:
function Tsat_der "Derivative of saturation temperature"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Real p_der "Pressure derivative";
  output Real T_der "Temperature derivative";
protected
  Real beta, beta_der;
  Real D, D_der;
  Real E, E_der;
  Real F, F_der;
  Real G, G_der;
  Real o_der[2];
  final constant Real[10] n = {0.11670521452767E+004, -0.72421316703206E+006, -0.17073846940092E+002, 0.1202082470247E+005, -0.32325550322333E+007, 0.1491510861353E+002, -0.48232657361591E+004, 0.40511340542057E+006, -0.23855557567849, 0.65017534844798E+003};
algorithm
  beta := (p * 1E-006) ^ 0.25;
  beta_der := 0.25 / (p * 1E-006) ^ 0.75 * 1E-006;
  E := Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[3] * Modelica.Media.Air.ReferenceMoistAir.beta + n[6];
  E_der := 2 * Modelica.Media.Air.ReferenceMoistAir.beta * beta_der + n[3];
  F := n[1] * Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[4] * Modelica.Media.Air.ReferenceMoistAir.beta + n[7];
  F_der := 2 * n[1] * Modelica.Media.Air.ReferenceMoistAir.beta * beta_der + n[4];
  G := n[2] * Modelica.Media.Air.ReferenceMoistAir.beta ^ 2 + n[5] * Modelica.Media.Air.ReferenceMoistAir.beta + n[8];
  G_der := 2 * n[2] * Modelica.Media.Air.ReferenceMoistAir.beta * beta_der + n[5];
  D := 2 * G / (-F - sqrt(F ^ 2 - 4 * E * G));
  o_der[1] := 2 * F * F_der - 4 * (E * G_der + E_der * G);
  o_der[2] := -F_der - 0.5 / sqrt(F ^ 2 - 4 * E * G) * o_der[1];
  D_der := (2 * G_der * (-F - sqrt(F ^ 2 - 4 * E * G)) - 2 * G * o_der[2]) / (-F - sqrt(F ^ 2 - 4 * E * G)) ^ 2;
  T_der := (D_der - 0.5 / sqrt((n[10] + D) ^ 2 - 4 * (n[9] + n[10] * D)) * (2 * D * D_der - 2 * n[10] * D_der)) / 2 * p_der;
end Tsat_der;

modelica://Modelica.Media/ice09BaseProp_:
Modelica.Media: ice09BaseProp_pT (function)

Code:
function ice09BaseProp_pT "Intermediate property record for water (p and T preferred states)"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Media.Common.AuxiliaryProperties aux "Auxiliary record";
protected
  Modelica.Media.Common.GibbsDerivs2 g "Gibbs function and derivatives w.r.t. p and T";
algorithm
  aux.p := p;
  aux.T := T;
  aux.R_s := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Constants.R_s;
  g := Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Gibbs(aux.p, T);
  aux.rho := 1 / g.gp;
  aux.h := g.g - g.T * g.gT - Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Constants.h_off;
  aux.s := -g.gT - Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Constants.s_off;
  aux.cp := -g.T * g.gTT;
  aux.cv := aux.cp - g.T / g.gpp * g.gTp ^ 2;
  aux.vt := 1 / aux.rho * g.gTp / g.gp;
  aux.vp := 1 / aux.rho * g.gpp / g.gp;
  aux.pd := -1 / (aux.rho * aux.rho * aux.vp);
  aux.pt := -aux.vt / aux.vp;
end ice09BaseProp_pT;

