modelica://Modelica.Media/f_res:
Modelica.Media: f_res (function)

Code:
function f_res
  extends Modelica.Math.Nonlinear.Interfaces.partialScalarFunction;
  input Modelica.Units.SI.AbsolutePressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature";
protected
  Real x = u;
  Real p_ws = 0;
  Real kappa_T = 0;
  Real v_ws = 0;
  Real beta_H = 0;
  Real psi_ws = 0;
  Real baa = 0;
  Real baw = 0;
  Real bww = 0;
  Real caaa = 0;
  Real caaw = 0;
  Real caww = 0;
  Real cwww = 0;
  final constant Real R_bar = 8.314472;
algorithm
  //p_ws is the saturation pressure of water
  p_ws := if T >= 273.16 then Modelica.Media.Air.ReferenceMoistAir.Utilities.Water95_Utilities.psat(T) else Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.psub(T);
  //kappa_T is the isothermal compressibility
  if p < p_ws then
    kappa_T := 0;
  else
    kappa_T := if T >= 273.16 then Modelica.Media.Water.IF97_Utilities.kappa_pT(p, T) else Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.kappa_pT(p, T);
  end if;
  //v_ws is the molar volume of saturated water
  v_ws := if T >= 273.16 then Modelica.Media.Air.ReferenceMoistAir.Utilities.IF97_new.molarMass / Modelica.Media.Water.IF97_Utilities.rho_pT(p, T) else Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.Basic.Constants.MM / Modelica.Media.Air.ReferenceMoistAir.Utilities.Ice09_Utilities.rho_pT(p, T);
  //beta_H is Henry's law constant
  beta_H := Modelica.Media.Air.ReferenceMoistAir.Utilities.beta_H(p, T);
  //calculating the virial coefficients baa, baw, bww, caaa, caaw, caww, cwww
  baa := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Baa_dT(0, T);
  baw := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Baw_dT(0, T);
  bww := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Bww_dT(0, T);
  caaa := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Caaa_dT(0, T);
  caaw := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Caaw_dT(0, T);
  caww := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Caww_dT(0, T);
  cwww := Modelica.Media.Air.ReferenceMoistAir.Utilities.VirialCoefficients.Cwww_dT(0, T);
  y := ((1 + kappa_T * p_ws) * (p - p_ws) - kappa_T * (p ^ 2 - p_ws ^ 2) / 2) / (R_bar * T) * v_ws + log(1 - Modelica.Media.Air.ReferenceMoistAir.Utilities.beta_H * (1 - x * p_ws / p) * p) + (1 - x * p_ws / p) ^ 2 * p / (R_bar * T) * baa - 2 * (1 - x * p_ws / p) ^ 2 * p / (R_bar * T) * baw - (p - p_ws - (1 - x * p_ws / p) ^ 2 * p) / (R_bar * T) * bww + (1 - x * p_ws / p) ^ 3 * p ^ 2 / (R_bar * T) ^ 2 * caaa + 3 * (1 - x * p_ws / p) ^ 2 * (1 - 2 * (1 - x * p_ws / p)) * p ^ 2 / (2 * (R_bar * T) ^ 2) * caaw - 3 * (1 - x * p_ws / p) ^ 2 * x * p_ws / p * p ^ 2 / (R_bar * T) ^ 2 * caww - ((3 - 2 * x * p_ws / p) * (x * p_ws / p) ^ 2 * p ^ 2 - p_ws ^ 2) / (2 * (R_bar * T) ^ 2) * cwww - (1 - x * p_ws / p) ^ 2 * (-2 + 3 * x * p_ws / p) * x * p_ws / p * p ^ 2 / (R_bar * T) ^ 2 * baa * bww - 2 * (1 - x * p_ws / p) ^ 3 * (-1 + 3 * x * p_ws / p) * p ^ 2 / (R_bar * T) ^ 2 * baa * baw + 6 * (1 - x * p_ws / p) ^ 2 * (x * p_ws / p) ^ 2 * p ^ 2 / (R_bar * T) ^ 2 * bww * baw - 3 * (1 - x * p_ws / p) ^ 4 * p ^ 2 / (2 * (R_bar * T) ^ 2) * baa ^ 2 - 2 * (1 - x * p_ws / p) ^ 2 * x * p_ws / p * (-2 + 3 * x * p_ws / p) * p ^ 2 / (R_bar * T) ^ 2 * baw ^ 2 - (p_ws ^ 2 - (4 - 3 * x * p_ws / p) * (x * p_ws / p) ^ 3 * p ^ 2) / (2 * (R_bar * T) ^ 2) * bww ^ 2 - log(x);
end f_res;

