modelica://Modelica.Media/DataRecord:
Modelica.Media: DataRecord (record)

This data record contains the coefficients for the ideal gas equations according to:     
McBride B.J., Zehe M.J., and Gordon S. (2002): NASA Glenn Coefficients for Calculating Thermodynamic Properties of Individual Species . NASA report TP-2002-211556    
 The equations have the following structure:   

 The polynomials for h(T) and s0(T) are derived via integration from the one for cp(T) and contain the integration constants b1, b2 that define the reference specific enthalpy and entropy. For entropy differences the reference pressure p0 is arbitrary, but not for absolute entropies. It is chosen as 1 standard atmosphere (101325 Pa).   
 For most gases, the region of validity is from 200 K to 6000 K. The equations are split into two regions that are separated by Tlimit (usually 1000 K). In both regions the gas is described by the data above. The two branches are continuous and in most gases also differentiable at Tlimit.

Code:
record DataRecord "Coefficient data record for properties of ideal gases based on NASA source"
  extends Modelica.Icons.Record;
  String name "Name of ideal gas";
  Modelica.Units.SI.MolarMass MM "Molar mass";
  Modelica.Units.SI.SpecificEnthalpy Hf "Enthalpy of formation at 298.15K";
  Modelica.Units.SI.SpecificEnthalpy H0 "H0(298.15K) - H0(0K)";
  Modelica.Units.SI.Temperature Tlimit "Temperature limit between low and high data sets";
  Real alow[7] "Low temperature coefficients a";
  Real blow[2] "Low temperature constants b";
  Real ahigh[7] "High temperature coefficients a";
  Real bhigh[2] "High temperature constants b";
  Modelica.Units.SI.SpecificHeatCapacity R_s "Gas constant";

end DataRecord;

modelica://Modelica.Media/cp_T:
Modelica.Media: cp_T (function)

Code:
function cp_T "Compute specific heat capacity at constant pressure from temperature and gas data"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.DataRecord data "Ideal gas data";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.SpecificHeatCapacity cp "Specific heat capacity at temperature T";
algorithm
  cp := smooth(0, if T < data.Tlimit then data.R_s * (1 / (T * T) * (data.alow[1] + T * (data.alow[2] + T * (1. * data.alow[3] + T * (data.alow[4] + T * (data.alow[5] + T * (data.alow[6] + data.alow[7] * T))))))) else data.R_s * (1 / (T * T) * (data.ahigh[1] + T * (data.ahigh[2] + T * (1. * data.ahigh[3] + T * (data.ahigh[4] + T * (data.ahigh[5] + T * (data.ahigh[6] + data.ahigh[7] * T))))))));

end cp_T;

modelica://Modelica.Media/cp_Tlow:
Modelica.Media: cp_Tlow (function)

Code:
function cp_Tlow "Compute specific heat capacity at constant pressure, low T region"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.DataRecord data "Ideal gas data";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Units.SI.SpecificHeatCapacity cp "Specific heat capacity at temperature T";
algorithm
  cp := data.R_s * (1 / (T * T) * (data.alow[1] + T * (data.alow[2] + T * (1. * data.alow[3] + T * (data.alow[4] + T * (data.alow[5] + T * (data.alow[6] + data.alow[7] * T)))))));

end cp_Tlow;

modelica://Modelica.Media/cp_Tlow_der:
Modelica.Media: cp_Tlow_der (function)

Code:
function cp_Tlow_der "Compute derivative of specific heat capacity at constant pressure, low T region"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.DataRecord data "Ideal gas data";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Real dT(unit = "K/s") "Temperature derivative";
  output Real cp_der(unit = "J/(kg.K.s)") "Derivative of specific heat capacity";
algorithm
  cp_der := dT * data.R_s / (T * T * T) * (-2 * data.alow[1] + T * (-data.alow[2] + T * T * (data.alow[4] + T * (2. * data.alow[5] + T * (3. * data.alow[6] + 4. * data.alow[7] * T)))));

end cp_Tlow_der;

modelica://Modelica.Media/h_T:
Modelica.Media: h_T (function)

Code:
function h_T "Compute specific enthalpy from temperature and gas data; reference is decided by the
    refChoice input, or by the referenceChoice package constant by default"
  import Modelica.Media.Interfaces.Choices;
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.DataRecord data "Ideal gas data";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Boolean exclEnthForm = excludeEnthalpyOfFormation "If true, enthalpy of formation Hf is not included in specific enthalpy h";
  input Choices.ReferenceEnthalpy refChoice = referenceChoice "Choice of reference enthalpy";
  input Modelica.Units.SI.SpecificEnthalpy h_off = h_offset "User defined offset for reference enthalpy, if referenceChoice = UserDefined";
  output Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy at temperature T";
algorithm
  h := smooth(0, (if T < data.Tlimit then data.R_s * ((-data.alow[1] + T * (data.blow[1] + data.alow[2] * Modelica.Math.log(T) + T * (1. * data.alow[3] + T * (0.5 * data.alow[4] + T * (1 / 3 * data.alow[5] + T * (0.25 * data.alow[6] + 0.2 * data.alow[7] * T)))))) / T) else data.R_s * ((-data.ahigh[1] + T * (data.bhigh[1] + data.ahigh[2] * Modelica.Math.log(T) + T * (1. * data.ahigh[3] + T * (0.5 * data.ahigh[4] + T * (1 / 3 * data.ahigh[5] + T * (0.25 * data.ahigh[6] + 0.2 * data.ahigh[7] * T)))))) / T)) + (if exclEnthForm then -data.Hf else 0.0) + (if refChoice == Choices.ReferenceEnthalpy.ZeroAt0K then data.H0 else 0.0) + (if refChoice == Choices.ReferenceEnthalpy.UserDefined then h_off else 0.0));

end h_T;

