  output Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy at temperature T";
algorithm
  h := data.R_s * ((-data.alow[1] + T * (data.blow[1] + data.alow[2] * Modelica.Math.log(T) + T * (1. * data.alow[3] + T * (0.5 * data.alow[4] + T * (1 / 3 * data.alow[5] + T * (0.25 * data.alow[6] + 0.2 * data.alow[7] * T)))))) / T) + (if exclEnthForm then -data.Hf else 0.0) + (if refChoice == Choices.ReferenceEnthalpy.ZeroAt0K then data.H0 else 0.0) + (if refChoice == Choices.ReferenceEnthalpy.UserDefined then h_off else 0.0);

end h_Tlow;

