Code:
function isentropicEnthalpyApproximation "Approximate method of calculating h_is from upstream properties and downstream pressure"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p2 "Downstream pressure";
  input Modelica.Media.IdealGases.Common.SingleGasNasa.ThermodynamicState state "Properties at upstream location";
  input Boolean exclEnthForm = Functions.excludeEnthalpyOfFormation "If true, enthalpy of formation Hf is not included in specific enthalpy h";
  input Modelica.Media.Interfaces.Choices.ReferenceEnthalpy refChoice = Functions.referenceChoice "Choice of reference enthalpy";
  input Modelica.Media.IdealGases.Common.SingleGasNasa.SpecificEnthalpy h_off = Functions.h_offset "User defined offset for reference enthalpy, if referenceChoice = UserDefined";
  output Modelica.Units.SI.SpecificEnthalpy h_is "Isentropic enthalpy";
protected
  Modelica.Media.IdealGases.Common.SingleGasNasa.IsentropicExponent gamma = Modelica.Media.IdealGases.Common.SingleGasNasa.isentropicExponent(state) "Isentropic exponent";
algorithm
  h_is := Modelica.Media.IdealGases.Common.Functions.h_T(data, state.T, exclEnthForm, refChoice, h_off) + gamma / (gamma - 1.0) * state.p / Modelica.Media.IdealGases.Common.SingleGasNasa.density(state) * ((p2 / state.p) ^ ((gamma - 1) / gamma) - 1.0);

end isentropicEnthalpyApproximation;

