modelica://Modelica.Media/isentropicEnth:
Modelica.Media: isentropicEnthalpyApproximation (function)

Code:
function isentropicEnthalpyApproximation "Approximate method of calculating h_is from upstream properties and downstream pressure"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.AbsolutePressure p2 "Downstream pressure";
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.ThermodynamicState state "Thermodynamic state at upstream location";
  output Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h_is "Isentropic enthalpy";
protected
  Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h "Specific enthalpy at upstream location";
  Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h_component[nX] "Specific enthalpy at upstream location";
  Modelica.Media.IdealGases.Common.MixtureGasNasa.IsentropicExponent gamma = Modelica.Media.IdealGases.Common.MixtureGasNasa.isentropicExponent(state) "Isentropic exponent";
protected
  Modelica.Media.IdealGases.Common.MixtureGasNasa.MassFraction[nX] X "Complete X-vector";
algorithm
  X := if reducedX then cat(1, state.X, {1 - sum(state.X)}) else state.X;
  h_component := array(Modelica.Media.IdealGases.Common.Functions.h_T(data[i], state.T, excludeEnthalpyOfFormation, referenceChoice, h_offset) for i in 1:nX);
  h := h_component * X;
  h_is := h + gamma / (gamma - 1.0) * (state.T * Modelica.Media.IdealGases.Common.MixtureGasNasa.gasConstant(state)) * ((p2 / state.p) ^ ((gamma - 1) / gamma) - 1.0);

end isentropicEnthalpyApproximation;

