function T_hX "Return temperature from specific enthalpy and mass fraction"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h "Specific enthalpy";
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.MassFraction[nX] X "Mass fractions of composition";
  input Boolean exclEnthForm = excludeEnthalpyOfFormation "If true, enthalpy of formation Hf is not included in specific enthalpy h";
  input Modelica.Media.Interfaces.Choices.ReferenceEnthalpy refChoice = referenceChoice "Choice of reference enthalpy";
  input Modelica.Units.SI.SpecificEnthalpy h_off = h_offset "User defined offset for reference enthalpy, if referenceChoice = UserDefined";
  output Modelica.Media.IdealGases.Common.MixtureGasNasa.Temperature T "Temperature";
protected
  function f_nonlinear "Solve h_TX(T,X) for T with given h"
  extends Modelica.Math.Nonlinear.Interfaces.partialScalarFunction;
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h "Specific enthalpy";
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.MassFraction[nX] X "Mass fractions of composition";
  input Boolean exclEnthForm "If true, enthalpy of formation Hf is not included in specific enthalpy h";
  input Modelica.Media.Interfaces.Choices.ReferenceEnthalpy refChoice "Choice of reference enthalpy";
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.SpecificEnthalpy h_off "User defined offset for reference enthalpy, if referenceChoice = UserDefined";
  algorithm
  y := Modelica.Media.IdealGases.Common.MixtureGasNasa.h_TX(T = u, X = X, exclEnthForm = exclEnthForm, refChoice = refChoice, h_off = h_off) - h;
  end f_nonlinear;
algorithm
  T := Modelica.Math.Nonlinear.solveOneNonlinearEquation(function f_nonlinear(h = h, X = X, exclEnthForm = exclEnthForm, refChoice = refChoice, h_off = h_off), 200, 6000);

end T_hX;

