Code:
function specificEntropyOfpTX "Return specific entropy from pressure, temperature and mass fractions"
  extends Modelica.Icons.Function;
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.AbsolutePressure p "Pressure";
  input Modelica.Media.IdealGases.Common.MixtureGasNasa.Temperature T "Temperature";
