modelica://Modelica.Media/cv2Phase-2:
Modelica.Media: cv2Phase (function)

Code:
function cv2Phase "Compute isochoric specific heat capacity inside the two-phase region"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.Common.PhaseBoundaryProperties liq "Properties on the boiling curve";
  input Modelica.Media.R134a.Common.PhaseBoundaryProperties vap "Properties on the condensation curve";
  input Modelica.Units.SI.MassFraction x "Vapour mass fraction";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Modelica.Units.SI.Pressure p "Pressure";
  output Modelica.Units.SI.SpecificHeatCapacity cv "Isochoric specific heat capacity";
  output Real dpT "Derivative of pressure w.r.t. temperature";
protected
  Real dxv "Derivative of vapour mass fraction w.r.t. specific volume";
  Real dvTl "Derivative of liquid specific volume w.r.t. temperature";
  Real dvTv "Derivative of vapour specific volume w.r.t. temperature";
  Real duTl "Derivative of liquid specific inner energy w.r.t. temperature";
  Real duTv "Derivative of vapour specific inner energy w.r.t. temperature";
  Real dxt "Derivative of vapour mass fraction w.r.t. temperature";
algorithm
  dxv := if liq.d <> vap.d then liq.d * vap.d / (liq.d - vap.d) else 0.0;
  dpT := (vap.s - liq.s) * dxv;
  // wrong at critical point
  dvTl := (liq.pt - dpT) / liq.pd / liq.d / liq.d;
  dvTv := (vap.pt - dpT) / vap.pd / vap.d / vap.d;
  dxt := -dxv * (dvTl + x * (dvTv - dvTl));
  duTl := liq.cv + (T * liq.pt - p) * dvTl;
  duTv := vap.cv + (T * vap.pt - p) * dvTv;
  cv := duTl + x * (duTv - duTl) + dxt * (vap.u - liq.u);
end cv2Phase;

modelica://Modelica.Media/FindInterval:
Modelica.Media: FindInterval (function)

Code:
function FindInterval "Half-interval search algorithm"
  extends Modelica.Icons.Function;
  input Real x "Input";
  input Real[:] breaks "Grid points defining the intervals";
  output Integer i "Found interval number";
  output Integer error = 0 "1=did not find interval";
protected
  Integer n = scalar(size(breaks)) - 1 "Max value";
  Integer ix = 1 "Min value";
  Integer m = n "New interval";
algorithm
  i := 1;
  if x < breaks[1] or x >= breaks[n] then
    error := 1;
  end if;
  if x < breaks[1] or x >= breaks[2] then
    while m <> ix loop
      if x < breaks[m] then
        n := m;
      else
        ix := m;
      end if;
      m := integer(div(ix + n, 2));
    end while;
    i := ix;
  end if;
end FindInterval;

modelica://Modelica.Media/helmholtzToBou:
Modelica.Media: helmholtzToBoundaryProps (function)

Code:
function helmholtzToBoundaryProps "Calculate phase boundary property record from dimensionless Helmholtz function"
  extends Modelica.Icons.Function;
  input Modelica.Media.Common.HelmholtzDerivs f "Dimensionless derivatives of Helmholtz function";
  output Modelica.Media.R134a.Common.PhaseBoundaryProperties sat "Phase boundary property record";
protected
  Modelica.Units.SI.Pressure p "Pressure";
algorithm
  p := f.R_s * f.d * f.T * f.delta * f.fdelta;
  sat.d := f.d;
  sat.h := f.R_s * f.T * (f.tau * f.ftau + f.delta * f.fdelta);
  sat.s := f.R_s * (f.tau * f.ftau - f.f);
  sat.u := f.R_s * f.T * f.tau * f.ftau;
  sat.cp := f.R_s * (-f.tau * f.tau * f.ftautau + (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) ^ 2 / (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta));
  sat.cv := f.R_s * (-f.tau * f.tau * f.ftautau);
  sat.pt := f.R_s * f.d * (f.delta * (f.fdelta - f.tau * f.fdeltatau));
  sat.pd := f.R_s * f.T * (f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta));
  sat.a := abs(f.R_s * f.T * (2 * f.delta * f.fdelta + f.delta * f.delta * f.fdeltadelta - (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) * (f.delta * f.fdelta - f.delta * f.tau * f.fdeltatau) / (f.tau * f.tau * f.ftautau))) ^ 0.5;
  sat.kappa := 1 / (f.d * f.R_s * f.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta));
  sat.beta := f.R_s * f.d * f.delta * (f.fdelta - f.tau * f.fdeltatau) * sat.kappa;
  sat.gamma := sat.a ^ 2 / f.R_s / f.T;
end helmholtzToBoundaryProps;

