function extends setDewState "Return the thermodynamic state on the dew line"
  algorithm
    if sat.psat < Modelica.Media.R134a.R134aData.data.FPCRIT then
      state.p := sat.psat;
      state.T := Modelica.Media.R134a.R134a_ph.saturationTemperature(sat.psat);
      state.d := Modelica.Media.R134a.R134a_ph.dewDensity(sat);
      state.h := Modelica.Media.R134a.R134a_ph.dewEnthalpy(sat);
