Code:
function extends isothermalCompressibility "Isothermal compressibility w.r.t. thermodynamic state (only valid for one-phase)"
  protected
    Modelica.Media.Common.HelmholtzDerivs f "Helmholtz derivatives";

  algorithm
    if Modelica.Media.R134a.R134a_ph.getPhase_ph(state.p, state.h) == 2 then
      kappa := 0;
      // assert(getPhase_ph(state.p, state.h)==1, "Function for isothermal compressibility is only valid for one-phase regime!");
    else
      f := Modelica.Media.R134a.R134a_ph.f_R134a(state.d, state.T);
      kappa := 1 / (state.d * R134aData.data.R_s * state.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta));
