    end if;

end isobaricExpansionCoefficient;

modelica://Modelica.Media/density_derh_p:
Modelica.Media: density_derh_p (function)

This function calculates the density derivative w.r.t. specific enthalpy at constant pressure of R134a (e.g., use setState_phX function for input). The derivative is modelled by the fundamental equation of state of Tillner-Roth and Baehr (1994). It can be used for manual state transformations (e.g. from density to specific enthalpy).

Code:
function extends density_derh_p "Density derivative by specific enthalpy | use setState_phX function for input"
  protected
  Modelica.Media.R134a.Common.InverseDerivatives_rhoT derivs "Inverse derivatives for density and temperature";

  algorithm
    derivs := Modelica.Media.R134a.R134a_ph.derivsOf_ph(state.p, state.h, Modelica.Media.R134a.R134a_ph.getPhase_ph(p = state.p, h = state.h));
    ddhp := if Modelica.Media.R134a.R134a_ph.getPhase_ph(p = state.p, h = state.h) == 2 then -state.d * state.d / (derivs.dpT * state.T) else -state.d * state.d * derivs.pt / (state.d * state.d * derivs.pd * derivs.cv + state.T * derivs.pt ^ 2);

end density_derh_p;

modelica://Modelica.Media/density_derp_h:
Modelica.Media: density_derp_h (function)

This function calculates the density derivative w.r.t. absolute pressure at constant specific enthalpy of R134a (e.g., use setState_phX function for input). The derivative is modelled by the fundamental equation of state of Tillner-Roth and Baehr (1994). It can be used for manual state transformations (e.g. from density to pressure).

Code:
function extends density_derp_h "Density derivative by pressure | use setState_phX function for input"
  protected
  Modelica.Media.R134a.Common.InverseDerivatives_rhoT derivs "Inverse derivatives for density and temperature";

  algorithm
    derivs := Modelica.Media.R134a.R134a_ph.derivsOf_ph(state.p, state.h, Modelica.Media.R134a.R134a_ph.getPhase_ph(p = state.p, h = state.h));
    ddph := if Modelica.Media.R134a.R134a_ph.getPhase_ph(p = state.p, h = state.h) == 2 then state.d * (state.d * derivs.cv / derivs.dpT + 1) / (derivs.dpT * state.T) else state.d * (derivs.cv * state.d + derivs.pt) / (state.d * state.d * derivs.pd * derivs.cv + state.T * derivs.pt ^ 2);

end density_derp_h;

modelica://Modelica.Media/derivsOf_ph:
Modelica.Media: derivsOf_ph (function)

This function calculates the derivatives required for an inversion of temperature and density function.

Code:
function derivsOf_ph "Derivatives required for inversion of temperature and density functions"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure p "Pressure";
  input Modelica.Media.R134a.R134a_ph.SpecificEnthalpy h "Specific enthalpy";
  input Integer phase "Number of phases";
  output Modelica.Media.R134a.Common.InverseDerivatives_rhoT derivs "Inverse derivatives for density and temperature";
protected
  Modelica.Media.Common.HelmholtzDerivs f "Helmholtz derivatives";
  Modelica.Media.R134a.R134a_ph.SaturationProperties sat "Saturation temperature and pressure";
  Modelica.Media.R134a.Common.PhaseBoundaryProperties liq "Properties on liquid phase boundary";
  Modelica.Media.R134a.Common.PhaseBoundaryProperties vap "Properties on vapor phase boundary";
  Modelica.Media.Common.NewtonDerivatives_ph newder "Newton derivatives";
  Real x "Vapor quality";
  Real dxv "1/(v_vap - v_liq)";
algorithm
  derivs.p := p;
  derivs.h := h;
  derivs.phase := Modelica.Media.R134a.R134a_ph.getPhase_ph(p, h);
  sat.psat := p;
  sat.Tsat := Modelica.Media.R134a.R134a_ph.saturationTemperature(p);
  (derivs.rho, derivs.T) := Modelica.Media.R134a.R134a_ph.dt_ph(p = p, h = h);
  if derivs.phase == 2 then
    liq := Modelica.Media.R134a.R134a_ph.R134a_liqofdT(T = derivs.T);
    vap := Modelica.Media.R134a.R134a_ph.R134a_vapofdT(T = derivs.T);
    x := if liq.h <> vap.h then (h - liq.h) / (vap.h - liq.h) else if h >= vap.h then 1 else 0;
    derivs.cv := Modelica.Media.R134a.Common.cv2Phase(liq = liq, vap = vap, x = x, p = p, T = derivs.T);
    dxv := if liq.d <> vap.d then liq.d * vap.d / (liq.d - vap.d) else 0.0;
    derivs.dpT := (vap.s - liq.s) * dxv;
  else
    f := Modelica.Media.R134a.R134a_ph.f_R134a(d = derivs.rho, T = derivs.T);
    f.d := derivs.rho;
    f.T := derivs.T;
    f.R_s := R134aData.R_s;
    newder := Modelica.Media.Common.Helmholtz_ph(f = f);
    derivs.cv := -f.R_s * (f.tau * f.tau * f.ftautau);
    derivs.pd := newder.pd;
    derivs.pt := newder.pt;
    //derivs.dpT := 0;
  end if;

end derivsOf_ph;

modelica://Modelica.Media/dt_ph:
Modelica.Media: dt_ph (function)

This function calculates the density and temperature of R134a from absolute pressure and specific enthalpy. In one-phase region the function calls the fundamental Helmholtz equation of Tillner-Roth (1994). In two-phase the density and temperature is computed from cubic splines for saturated pressure, liquid and vapor density.    Restrictions  The function cannot be inverted in a numerical way. Please use functions rho_props_ph and T_props_ph for this purpose.

Code:
function dt_ph "Density and temperature w.r.t. pressure and specific enthalpy"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure p "Pressure";
  input Modelica.Media.R134a.R134a_ph.SpecificEnthalpy h "Specific enthalpy";
  output Modelica.Media.R134a.R134a_ph.Density d "Density";
  output Modelica.Media.R134a.R134a_ph.Temperature T "Temperature";
protected
  Modelica.Media.R134a.R134a_ph.SaturationProperties sat(psat = p, Tsat = 0) "Saturation temperature and pressure";
  Modelica.Units.SI.Pressure delp = 1.0e-2 "Relative error in p in iteration";
  Modelica.Units.SI.SpecificEnthalpy delh = 1.0e-2 "Relative error in h in iteration";
  Modelica.Units.SI.SpecificEnthalpy hvapor = Modelica.Media.R134a.R134a_ph.dewEnthalpy(sat = sat) "Vapor enthalpy";
  Modelica.Units.SI.SpecificEnthalpy hliquid = Modelica.Media.R134a.R134a_ph.bubbleEnthalpy(sat = sat) "Liquid enthalpy";
  Integer error "Iteration error";
  Real x "Vapor quality";
  Real vvap "Specific volume vapor";
  Real vliq "Specific volume liquid";
algorithm
  if h < hliquid or h > hvapor or p > R134aData.data.FPCRIT then
    (d, T, error) := Modelica.Media.R134a.R134a_ph.dtofphOnePhase(p, h, delp, delh);
  else
    vvap := 1 / Modelica.Media.R134a.R134a_ph.dewDensity(sat = sat);
    vliq := 1 / Modelica.Media.R134a.R134a_ph.bubbleDensity(sat = sat);
    x := (h - hliquid) / (hvapor - hliquid);
    error := 0;
    T := Modelica.Media.R134a.R134a_ph.saturationTemperature(p);
    d := 1 / (vliq + x * (vvap - vliq));
  end if;

end dt_ph;

modelica://Modelica.Media/dtofphOnePhase:
Modelica.Media: dtofphOnePhase (function)

This function calculates the density and temperature of R134a from absolute pressure and specific enthalpy in one-phase region. The function calls the fundamental Helmholtz equation of Tillner-Roth (1994) which is requiring density and temperature for input. Thus, a newton iteration is performed to determine density and temperature. The newton iteration stops if the inputs for pressure difference delp and specific enthalpy difference delh are larger than the actual differences derived from the newton iteration.    Restrictions  The function shall only be used for one-phase inputs since the fundamental equation is not valid for two-phase states.

Code:
function dtofphOnePhase "Density and temperature w.r.t. pressure and specific enthalpy in one-phase region"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure p "Pressure";
  input Modelica.Media.R134a.R134a_ph.SpecificEnthalpy h "Enthalpy";
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure delp "Absolute error in p in iteration";
  input Modelica.Media.R134a.R134a_ph.SpecificEnthalpy delh "Absolute error in h in iteration";
  output Modelica.Media.R134a.R134a_ph.Density d "Density";
  output Modelica.Media.R134a.R134a_ph.Temperature T "Temperature";
  output Integer error "1 if did not converged";
protected
  constant Real p_breaks[:] = R134aData.pbreaks "Grid points of reduced pressure";
  constant Real hl_coef[:, 4] = R134aData.hlcoef "Coefficients of cubic spline for h_liq(p)";
  constant Real dl_coef[:, 4] = R134aData.dlcoef "Coefficients of cubic spline for rho_liq(p)";
  constant Real T_coef[:, 4] = R134aData.Tcoef "Coefficients of cubic spline for Tsat(p)";
  constant Real dv_coef[:, 4] = R134aData.dvcoef "Coefficients of cubic spline for rho_vap(p)";
  Modelica.Units.SI.SpecificEnthalpy hl "Liquid enthalpy";
  Boolean liquid "Is liquid";
  Boolean supercritical "Is supercritical";
  Integer int "Interval number";
  Real pred "Reduced pressure";
  Real localx "Abscissa of local spline";
  Integer i "Newton iteration number";
  Real dh "Difference in h";
  Real dp "Difference in p";
  Real damping "Damping constant";
  Real det "Determinant";
  Real deld "Density change";
  Real delt "Temperature change";
  Modelica.Media.Common.HelmholtzDerivs f "Helmholtz derivatives";
  Modelica.Media.Common.NewtonDerivatives_ph nDerivs "Newton derivatives";
  Boolean found "Iteration converged";
algorithm
  i := 0;
  error := 0;
  found := false;
  damping := 1.0;
  //by default no damping
  pred := p / R134aData.data.FPCRIT;
  (int, error) := Modelica.Media.R134a.Common.FindInterval(pred, p_breaks);
  localx := pred - p_breaks[int];
  // set decent initial guesses for d and T
  supercritical := p > R134aData.data.FPCRIT;
  if supercritical then
    // iteration seems to work better if coming from high densities
    d := R134aData.data.FDCRIT * 3.0;
    //      dTR.T := data.TCRIT + 10.0;
    // linear approximation that can be made generic
    T := 270.0 + 120.0 * (h / R134aData.data.HCRIT);
  else
    liquid := h < 1.01 * R134aData.data.HCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, hl_coef[int, 1:4]);
    if liquid then
      damping := 0.3;
      //damping on the liquid side
      d := R134aData.data.FDCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, dl_coef[int, 1:4]) * 1.5;
      T := Modelica.Media.R134a.Common.CubicSplineEval(localx, T_coef[int, 1:4]);
    else
      d := R134aData.data.FDCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, dv_coef[int, 1:4]) * 0.95;
      T := Modelica.Media.R134a.Common.CubicSplineEval(localx, T_coef[int, 1:4]);
    end if;
  end if;
  // the Newton iteration
  while i < 50 and not found loop
    f := Modelica.Media.R134a.R134a_ph.f_R134a(d, T);
    // nDerivs are the symbolic derivatives needed in the iteration
    // for given d and T
    nDerivs := Modelica.Media.Common.Helmholtz_ph(f);
    dh := nDerivs.h - h;
    dp := nDerivs.p - p;
    if abs(dh) <= delh and abs(dp) <= delp then
      found := true;
      error := if not found then 1 else 0;
    end if;
    det := nDerivs.ht * nDerivs.pd - nDerivs.pt * nDerivs.hd;
    if abs(det) < 1e-10 then
      det := sign(det) * 1e-10;
    end if;
    delt := (nDerivs.pd * dh - nDerivs.hd * dp) / det;
    deld := (nDerivs.ht * dp - nDerivs.pt * dh) / det;
    T := T - damping * delt;
    d := d - damping * deld;
    // Check for limit of state variables
    if T < R134aData.triple.TTRIPLE then
      T := R134aData.triple.TTRIPLE + 0.1;
    end if;
    if d <= 0.0 then
      d := R134aData.triple.DVTRIPLE;
    elseif d > 1.5 * R134aData.triple.DLTRIPLE then
      d := R134aData.triple.DLTRIPLE;
    end if;
    i := i + 1;
  end while;

end dtofphOnePhase;

modelica://Modelica.Media/dtofpsOnePhase:
Modelica.Media: dtofpsOnePhase (function)

This function calculates the density and temperature of R134a from absolute pressure and specific entropy in one-phase region. The function calls the fundamental helmholtz equation of Tillner-Roth (1994) which is requiring density and temperature for input. Thus, a newton iteration is performed to determine density and temperature. The newton iteration stops if the inputs for pressure difference delp and specific entropy difference dels are larger than the actual differences derived from the newton iteration.    Restrictions  The function shall only be used for one-phase inputs since the fundamental equation is not valid for two-phase states. The iteration could fail for liquid states with high pressures.

Code:
function dtofpsOnePhase "Inverse iteration in one phase region (d,T) = f(p,s)"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure p "Pressure";
  input Modelica.Media.R134a.R134a_ph.SpecificEntropy s "Specific entropy";
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure delp "Absolute iteration accuracy";
  input Modelica.Media.R134a.R134a_ph.SpecificEntropy dels "Absolute iteration accuracy";
  output Modelica.Media.R134a.R134a_ph.Density d "Density";
  output Modelica.Media.R134a.R134a_ph.Temperature T "Temperature";
  output Integer error "Error flag: trouble if different from 0";
protected
  constant Real p_breaks[:] = R134aData.pbreaks "Grid points of reduced pressure";
  constant Real dl_coef[:, 4] = R134aData.dlcoef "Coefficients of cubic spline for rho_liq(p)";
  constant Real dv_coef[:, 4] = R134aData.dvcoef "Coefficients of cubic spline for rho_vap(p)";
  constant Real sl_coef[:, 4] = R134aData.slcoef "Coefficients of cubic spline for s_liq(p)";
  constant Real sv_coef[:, 4] = R134aData.svcoef "Coefficients of cubic spline for s_vap(p)";
  constant Real T_coef[:, 4] = R134aData.Tcoef "Coefficients of cubic spline for Tsat(p)";
  Integer i "Newton iteration number";
  Real ds "Difference in s";
  Real dp "Difference in p";
  Real det "Determinant";
  Real deld "Density change";
  Real delt "Temperature change";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. dimensionless d and T";
  Modelica.Media.Common.NewtonDerivatives_ps nDerivs "Newton derivatives";
  Boolean liquid "Is liquid";
  Boolean supercritical "Is supercritical";
  Boolean found "Iteration converged";
  Integer int "Interval number";
  Real pred "Reduced pressure";
  Real localx "Abscissa of local spline";
  Real sl "Liquid entropy";
  Real sv "Vapor entropy";
algorithm
  i := 0;
  error := 0;
  found := false;
  pred := p / R134aData.data.FPCRIT;
  (int, error) := Modelica.Media.R134a.Common.FindInterval(pred, p_breaks);
  localx := pred - p_breaks[int];
  // set decent initial guesses for d and T
  supercritical := p > R134aData.data.FPCRIT;
  if supercritical then
    d := R134aData.data.FDCRIT + 500.0;
    T := R134aData.data.FTCRIT + 10.0;
  else
    sl := R134aData.data.SCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, sl_coef[int, 1:4]);
    sv := R134aData.data.SCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, sv_coef[int, 1:4]);
    liquid := s < sl;
    if liquid then
      d := R134aData.data.FDCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, dl_coef[int, 1:4]) * 1.1;
      //1.05
      T := Modelica.Media.R134a.Common.CubicSplineEval(localx, T_coef[int, 1:4]) * 0.9;
      //0.95
    else
      d := R134aData.data.FDCRIT * Modelica.Media.R134a.Common.CubicSplineEval(localx, dv_coef[int, 1:4]) * 0.8;
      //0.9
      T := Modelica.Media.R134a.Common.CubicSplineEval(localx, T_coef[int, 1:4]) * 1.1 + 0.5 * (s - sv);
    end if;
  end if;
  while i < 100 and not found loop
    f := Modelica.Media.R134a.R134a_ph.f_R134a(d = d, T = T);
    nDerivs := Modelica.Media.Common.Helmholtz_ps(f);
    ds := nDerivs.s - s;
    dp := nDerivs.p - p;
    if abs(ds / s) <= dels and abs(dp / p) <= delp then
      found := true;
    end if;
    det := nDerivs.st * nDerivs.pd - nDerivs.pt * nDerivs.sd;
    delt := (nDerivs.pd * ds - nDerivs.sd * dp) / det;
    deld := (nDerivs.st * dp - nDerivs.pt * ds) / det;
    T := T - delt;
    d := d - deld;
    i := i + 1;
  end while;
  if not found then
    error := 1;
  end if;

end dtofpsOnePhase;

modelica://Modelica.Media/f_R134a:
Modelica.Media: f_R134a (function)

This function adds the ideal gas contribution of the fundamental equation to the residual contribution and computes the helmholtz derivatives w.r.t. temperature and density.

Code:
function f_R134a "Calculation of helmholtz derivatives by density and temperature"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.Density d "Density";
  input Modelica.Media.R134a.R134a_ph.Temperature T "Temperature";
  output Modelica.Media.Common.HelmholtzDerivs f "Helmholtz derivatives";
protected
  Real delta "Reduced density";
  Real tau "Reduced temperature";
  Modelica.Media.Common.HelmholtzDerivs fid "Helmholtz derivstives";
algorithm
  delta := d / R134aData.data.DCRIT;
  tau := R134aData.data.TCRIT / T;
  fid := Modelica.Media.R134a.R134a_ph.fid_R134a(delta = delta, tau = tau);
  f := Modelica.Media.R134a.R134a_ph.fres_R134a(delta = delta, tau = tau);
  f.f := f.f + fid.f;
  f.fdelta := f.fdelta + fid.fdelta;
  f.fdeltadelta := f.fdeltadelta + fid.fdeltadelta;
  f.ftau := f.ftau + fid.ftau;
  f.ftautau := f.ftautau + fid.ftautau;
  f.d := d;
  f.T := T;
  f.R_s := R134aData.R_s;

end f_R134a;

modelica://Modelica.Media/fid_R134a:
Modelica.Media: fid_R134a (function)

This function computes the ideal gas helmholtz derivatives of the fundamental equation of Tillner-Roth and Baehr for R134a (1994) w.r.t. to reduced temperature (tau=T_crit/T) and reduced density (delta=rho/rho_crit).

Code:
function fid_R134a "Helmholtz coefficients of ideal part"
  extends Modelica.Icons.Function;
  input Real delta "Reduced density (delta=d/dcrit)";
  input Real tau "Reduced temperature (tau=Tcrit/T)";
  output Modelica.Media.Common.HelmholtzDerivs fid "Helmholtz derivatives of ideal part";
protected
  Modelica.Media.R134a.R134aData.Ideal id "Ideal coefficients";
  Real atau = abs(tau) "|tau|";
  Real adelta = abs(delta) "|delta|";
algorithm
  fid.delta := delta;
  fid.tau := tau;
  fid.f := Modelica.Math.log(adelta) + id.a[1] + id.a[2] * atau + id.a[3] * Modelica.Math.log(atau) + id.a[4] * atau ^ (-0.5) + id.a[5] * atau ^ (-0.75);
  fid.fdelta := 1.0 / adelta;
  fid.fdeltadelta := -1.0 / (adelta * adelta);
  fid.ftau := id.a[2] + id.a[3] / atau - 0.5 * id.a[4] * atau ^ (-1.5) - 0.75 * id.a[5] * atau ^ (-1.75);
  fid.ftautau := -id.a[3] / (atau * atau) + 0.75 * id.a[4] * atau ^ (-2.5) + 1.3125 * id.a[5] * atau ^ (-2.75);
  fid.fdeltatau := 0.0;
  fid.d := fid.delta * R134aData.data.DCRIT;
  fid.T := R134aData.data.TCRIT / fid.tau;
  fid.R_s := R134aData.R_s;

end fid_R134a;

modelica://Modelica.Media/fres_R134a:
Modelica.Media: fres_R134a (function)

This function computes the residual helmholtz derivatives of the fundamental equation of Tillner-Roth and Baehr for R134a (1994) w.r.t. to reduced temperature (tau=T_crit/T) and reduced density (delta=rho/rho_crit). The function can be used for special properties depending just on the residual derivative parts.

Code:
function fres_R134a "Calculation of helmholtz derivatives"
  extends Modelica.Icons.Function;
  input Real delta "Reduced density (delta=d/dcrit)";
  input Real tau "Reduced temperature (tau=Tcrit/T)";
  output Modelica.Media.Common.HelmholtzDerivs f "Helmholtz derivatives";
protected
  Modelica.Media.R134a.R134aData.Residual res "Residual coefficient";
  Real k "Helping var";
  Real dc "Helping var";
  Real cdc "Helping var";
algorithm
  f.tau := abs(tau);
  f.delta := abs(delta);
  f.f := 0.0;
  f.ftau := 0.0;
  f.fdelta := 0.0;
  f.ftautau := 0.0;
  f.fdeltadelta := 0.0;
  f.fdeltatau := 0.0;
  for i in 1:res.ns1 loop
    k := res.n[i] * f.delta ^ res.d[i] * f.tau ^ res.t[i];
    f.f := f.f + k;
    f.fdelta := f.fdelta + k * res.d[i];
    f.fdeltadelta := f.fdeltadelta + k * res.d[i] * (res.d[i] - 1.0);
    f.ftau := f.ftau + k * res.t[i];
    f.ftautau := f.ftautau + k * res.t[i] * (res.t[i] - 1.0);
    f.fdeltatau := f.fdeltatau + k * res.t[i] * res.d[i];
  end for;
  for i in res.ns1 + 1:21 loop
    dc := f.delta ^ res.c[i];
    cdc := res.c[i] * dc;
    k := Modelica.Math.exp(-dc) * res.n[i] * delta ^ res.d[i] * f.tau ^ res.t[i];
    f.f := f.f + k;
    f.fdelta := f.fdelta + k * (res.d[i] - cdc);
    f.fdeltadelta := f.fdeltadelta + k * ((res.d[i] - cdc) * (res.d[i] - 1.0 - cdc) - res.c[i] * cdc);
    f.ftau := f.ftau + k * res.t[i];
    f.ftautau := f.ftautau + k * res.t[i] * (res.t[i] - 1.0);
    f.fdeltatau := f.fdeltatau + k * res.t[i] * (res.d[i] - cdc);
  end for;
  f.fdelta := f.fdelta / delta;
  f.fdeltadelta := f.fdeltadelta / (delta * delta);
  f.ftau := f.ftau / tau;
  f.ftautau := f.ftautau / (tau * tau);
  f.fdeltatau := f.fdeltatau / (delta * tau);
  f.d := f.delta * R134aData.data.DCRIT;
  f.T := R134aData.data.TCRIT / f.tau;
  f.R_s := R134aData.R_s;

end fres_R134a;

modelica://Modelica.Media/getPhase_ph:
Modelica.Media: getPhase_ph (function)

This function computes the number of phases for R134a depending on the inputs for absolute pressure and specific enthalpy. It makes use of cubic spline functions for liquid and vapor specific enthalpy.

Code:
function getPhase_ph "Number of phases by pressure and specific enthalpy"
  extends Modelica.Icons.Function;
  input Modelica.Media.R134a.R134a_ph.AbsolutePressure p "Pressure";
  input Modelica.Media.R134a.R134a_ph.SpecificEnthalpy h "Specific enthalpy";
  output Integer phase "Number of phases";
protected
  Modelica.Media.R134a.R134a_ph.SaturationProperties sat(psat = p, Tsat = 0) "Saturation temperature and pressure";
