  Modelica.Units.SI.SpecificEnthalpy hv = Modelica.Media.R134a.R134a_ph.dewEnthalpy(sat) "Vapor enthalpy";
algorithm
  phase := if h < hl or h > hv or p > R134aData.data.FPCRIT then 1 else 2;

