Modelica.Media: BaseProperties (model)

Code:
model extends BaseProperties(h(stateSelect = if ph_explicit and preferredMediumStates then StateSelect.prefer else StateSelect.default), d(stateSelect = if dT_explicit and preferredMediumStates then StateSelect.prefer else StateSelect.default), T(stateSelect = if (pT_explicit or dT_explicit) and preferredMediumStates then StateSelect.prefer else StateSelect.default), p(stateSelect = if (pT_explicit or ph_explicit) and preferredMediumStates then StateSelect.prefer else StateSelect.default)) "Base properties of water"
    Integer phase(min = 0, max = 2, start = 1, fixed = false) "2 for two-phase, 1 for one-phase, 0 if not known";

  equation
    MM = fluidConstants[1].molarMass;
    if Region > 0 then
      // Fixed region
      phase = if Region == 4 then 2 else 1;
    elseif smoothModel then
      if onePhase then
        phase = 1;
        if ph_explicit then
          assert(h < Modelica.Media.Water.WaterIF97_base.bubbleEnthalpy(sat) or h > Modelica.Media.Water.WaterIF97_base.dewEnthalpy(sat) or p > fluidConstants[1].criticalPressure, "With onePhase=true this model may only be called with one-phase states h < hl or h > hv!" + "(p = " + String(p) + ", h = " + String(h) + ")");
        else
          if dT_explicit then
            assert(not (d < Modelica.Media.Water.WaterIF97_base.bubbleDensity(sat) and d > Modelica.Media.Water.WaterIF97_base.dewDensity(sat) and T < fluidConstants[1].criticalTemperature), "With onePhase=true this model may only be called with one-phase states d > dl or d < dv!" + "(d = " + String(d) + ", T = " + String(T) + ")");
          end if;
        end if;
      else
        phase = 0;
      end if;
    else
      if ph_explicit then
        phase = if h < Modelica.Media.Water.WaterIF97_base.bubbleEnthalpy(sat) or h > Modelica.Media.Water.WaterIF97_base.dewEnthalpy(sat) or p > fluidConstants[1].criticalPressure then 1 else 2;
      elseif dT_explicit then
        phase = if not (d < Modelica.Media.Water.WaterIF97_base.bubbleDensity(sat) and d > Modelica.Media.Water.WaterIF97_base.dewDensity(sat) and T < fluidConstants[1].criticalTemperature) then 1 else 2;
      else
        phase = 1;
        //this is for the one-phase only case pT
      end if;
    end if;
    if dT_explicit then
      p = Modelica.Media.Water.WaterIF97_base.pressure_dT(d, T, phase, Region);
      h = Modelica.Media.Water.WaterIF97_base.specificEnthalpy_dT(d, T, phase, Region);
      sat.Tsat = T;
      sat.psat = Modelica.Media.Water.WaterIF97_base.saturationPressure(T);
    elseif ph_explicit then
      d = Modelica.Media.Water.WaterIF97_base.density_ph(p, h, phase, Region);
      T = Modelica.Media.Water.WaterIF97_base.temperature_ph(p, h, phase, Region);
      sat.Tsat = Modelica.Media.Water.WaterIF97_base.saturationTemperature(p);
      sat.psat = p;
    else
      h = Modelica.Media.Water.WaterIF97_base.specificEnthalpy_pT(p, T, Region);
      d = Modelica.Media.Water.WaterIF97_base.density_pT(p, T, Region);
      sat.psat = p;
      sat.Tsat = Modelica.Media.Water.WaterIF97_base.saturationTemperature(p);
    end if;
    u = h - p / d;
    R_s = Modelica.Constants.R / fluidConstants[1].molarMass;
    h = state.h;
    p = state.p;
    T = state.T;
    d = state.d;
    phase = state.phase;
end BaseProperties;

