modelica://Modelica.Media/waterBaseProp_:
Modelica.Media: waterBaseProp_ph (function)

Code:
function waterBaseProp_ph "Intermediate property record for water"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if unknown";
  input Integer region = 0 "If 0, do region computation, otherwise assume the region is this input";
  output Modelica.Media.Common.IF97BaseTwoPhase aux "Auxiliary record";
protected
  Modelica.Media.Common.GibbsDerivs g "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Integer error "Error flag for inverse iterations";
  Modelica.Units.SI.SpecificEnthalpy h_liq "Liquid specific enthalpy";
  Modelica.Units.SI.Density d_liq "Liquid density";
  Modelica.Units.SI.SpecificEnthalpy h_vap "Vapour specific enthalpy";
  Modelica.Units.SI.Density d_vap "Vapour density";
  Modelica.Media.Common.PhaseBoundaryProperties liq "Phase boundary property record";
  Modelica.Media.Common.PhaseBoundaryProperties vap "Phase boundary property record";
  Modelica.Media.Common.GibbsDerivs gl "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.GibbsDerivs gv "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs fl "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.HelmholtzDerivs fv "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Units.SI.Temperature t1 "Temperature at phase boundary, using inverse from region 1";
  Modelica.Units.SI.Temperature t2 "Temperature at phase boundary, using inverse from region 2";
algorithm
  aux.region := if region == 0 then if phase == 2 then 4 else Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.region_ph(p = p, h = h, phase = phase) else region;
  aux.phase := if phase <> 0 then phase else if aux.region == 4 then 2 else 1;
  aux.p := max(p, 611.657);
  aux.h := max(h, 1e3);
  aux.R_s := BaseIF97.data.RH2O;
  aux.vt := 0.0 "Initialized in case it is not needed";
  aux.vp := 0.0 "Initialized in case it is not needed";
  if aux.region == 1 then
    aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph1(aux.p, aux.h);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, aux.T);
    aux.s := aux.R_s * (g.tau * g.gtau - g.g);
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.x := 0.0;
    aux.dpT := -aux.vt / aux.vp;
  elseif aux.region == 2 then
    aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph2(aux.p, aux.h);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, aux.T);
    aux.s := aux.R_s * (g.tau * g.gtau - g.g);
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.x := 1.0;
    aux.dpT := -aux.vt / aux.vp;
  elseif aux.region == 3 then
    (aux.rho, aux.T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.dtofph3(p = aux.p, h = aux.h, delp = 1.0e-7, delh = 1.0e-6);
    f := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(aux.rho, aux.T);
    aux.h := aux.R_s * aux.T * (f.tau * f.ftau + f.delta * f.fdelta);
    aux.s := aux.R_s * (f.tau * f.ftau - f.f);
    aux.pd := aux.R_s * aux.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
    aux.pt := aux.R_s * aux.rho * f.delta * (f.fdelta - f.tau * f.fdeltatau);
    aux.cv := abs(aux.R_s * (-f.tau * f.tau * f.ftautau)) "Can be close to neg. infinity near critical point";
    aux.cp := (aux.rho * aux.rho * aux.pd * aux.cv + aux.T * aux.pt * aux.pt) / (aux.rho * aux.rho * aux.pd);
    aux.x := 0.0;
    aux.dpT := aux.pt;
    /*safety against div-by-0 in initialization*/
  elseif aux.region == 4 then
    h_liq := Modelica.Media.Water.IF97_Utilities.hl_p(p);
    h_vap := Modelica.Media.Water.IF97_Utilities.hv_p(p);
    aux.x := if h_vap <> h_liq then (h - h_liq) / (h_vap - h_liq) else 1.0;
    if p < BaseIF97.data.PLIMIT4A then
      t1 := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph1(aux.p, h_liq);
      t2 := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph2(aux.p, h_vap);
      gl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(aux.p, t1);
      gv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(aux.p, t2);
      liq := Modelica.Media.Common.gibbsToBoundaryProps(gl);
      vap := Modelica.Media.Common.gibbsToBoundaryProps(gv);
      aux.T := t1 + aux.x * (t2 - t1);
    else
      aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(aux.p);
      // how to avoid ?
      d_liq := Modelica.Media.Water.IF97_Utilities.rhol_T(aux.T);
      d_vap := Modelica.Media.Water.IF97_Utilities.rhov_T(aux.T);
      fl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d_liq, aux.T);
      fv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d_vap, aux.T);
      liq := Modelica.Media.Common.helmholtzToBoundaryProps(fl);
      vap := Modelica.Media.Common.helmholtzToBoundaryProps(fv);
      //  aux.dpT := BaseIF97.Basic.dptofT(aux.T);
    end if;
    aux.dpT := if liq.d <> vap.d then (vap.s - liq.s) * liq.d * vap.d / (liq.d - vap.d) else Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.dptofT(aux.T);
    aux.s := liq.s + aux.x * (vap.s - liq.s);
    aux.rho := liq.d * vap.d / (vap.d + aux.x * (liq.d - vap.d));
    aux.cv := Modelica.Media.Common.cv2Phase(liq, vap, aux.x, aux.T, p);
    aux.cp := liq.cp + aux.x * (vap.cp - liq.cp);
    aux.pt := liq.pt + aux.x * (vap.pt - liq.pt);
    aux.pd := liq.pd + aux.x * (vap.pd - liq.pd);
  elseif aux.region == 5 then
    (aux.T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.tofph5(p = aux.p, h = aux.h, reldh = 1.0e-7);
    assert(error == 0, "Error in inverse iteration of steam tables");
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g5(aux.p, aux.T);
    aux.s := aux.R_s * (g.tau * g.gtau - g.g);
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.dpT := -aux.vt / aux.vp;
  else
    assert(false, "Error in region computation of IF97 steam tables" + "(p = " + String(p) + ", h = " + String(h) + ")");
  end if;
end waterBaseProp_ph;

Modelica.Media: waterBaseProp_ps (function)

Code:
function waterBaseProp_ps "Intermediate property record for water"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if unknown";
  input Integer region = 0 "If 0, do region computation, otherwise assume the region is this input";
  output Modelica.Media.Common.IF97BaseTwoPhase aux "Auxiliary record";
protected
  Modelica.Media.Common.GibbsDerivs g "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Integer error "Error flag for inverse iterations";
  Modelica.Units.SI.SpecificEntropy s_liq "Liquid specific entropy";
  Modelica.Units.SI.Density d_liq "Liquid density";
  Modelica.Units.SI.SpecificEntropy s_vap "Vapour specific entropy";
  Modelica.Units.SI.Density d_vap "Vapour density";
  Modelica.Media.Common.PhaseBoundaryProperties liq "Phase boundary property record";
  Modelica.Media.Common.PhaseBoundaryProperties vap "Phase boundary property record";
  Modelica.Media.Common.GibbsDerivs gl "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.GibbsDerivs gv "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs fl "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.HelmholtzDerivs fv "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Units.SI.Temperature t1 "Temperature at phase boundary, using inverse from region 1";
  Modelica.Units.SI.Temperature t2 "Temperature at phase boundary, using inverse from region 2";
algorithm
  aux.region := if region == 0 then if phase == 2 then 4 else Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.region_ps(p = p, s = s, phase = phase) else region;
  aux.phase := if phase <> 0 then phase else if aux.region == 4 then 2 else 1;
  aux.p := p;
  aux.s := s;
  aux.R_s := BaseIF97.data.RH2O;
  aux.vt := 0.0 "Initialized in case it is not needed";
  aux.vp := 0.0 "Initialized in case it is not needed";
  if aux.region == 1 then
    aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tps1(p, s);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, aux.T);
    aux.h := aux.R_s * aux.T * g.tau * g.gtau;
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.x := 0.0;
    aux.dpT := -aux.vt / aux.vp;
  elseif aux.region == 2 then
    aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tps2(p, s);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, aux.T);
    aux.h := aux.R_s * aux.T * g.tau * g.gtau;
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.x := 1.0;
    aux.dpT := -aux.vt / aux.vp;
  elseif aux.region == 3 then
    (aux.rho, aux.T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.dtofps3(p = p, s = s, delp = 1.0e-7, dels = 1.0e-6);
    f := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(aux.rho, aux.T);
    aux.h := aux.R_s * aux.T * (f.tau * f.ftau + f.delta * f.fdelta);
    aux.s := aux.R_s * (f.tau * f.ftau - f.f);
    aux.pd := aux.R_s * aux.T * f.delta * (2.0 * f.fdelta + f.delta * f.fdeltadelta);
    aux.pt := aux.R_s * aux.rho * f.delta * (f.fdelta - f.tau * f.fdeltatau);
    aux.cv := aux.R_s * (-f.tau * f.tau * f.ftautau);
    aux.cp := (aux.rho * aux.rho * aux.pd * aux.cv + aux.T * aux.pt * aux.pt) / (aux.rho * aux.rho * aux.pd);
    aux.x := 0.0;
    aux.dpT := aux.pt;
    /*safety against div-by-0 in initialization*/
  elseif aux.region == 4 then
    s_liq := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.sl_p(p);
    s_vap := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.sv_p(p);
    aux.x := if s_vap <> s_liq then (s - s_liq) / (s_vap - s_liq) else 1.0;
    if p < BaseIF97.data.PLIMIT4A then
      t1 := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tps1(p, s_liq);
      t2 := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tps2(p, s_vap);
      gl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, t1);
      gv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, t2);
      liq := Modelica.Media.Common.gibbsToBoundaryProps(gl);
      vap := Modelica.Media.Common.gibbsToBoundaryProps(gv);
      aux.T := t1 + aux.x * (t2 - t1);
    else
      aux.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(p);
      d_liq := Modelica.Media.Water.IF97_Utilities.rhol_T(aux.T);
      d_vap := Modelica.Media.Water.IF97_Utilities.rhov_T(aux.T);
      fl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d_liq, aux.T);
      fv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d_vap, aux.T);
      liq := Modelica.Media.Common.helmholtzToBoundaryProps(fl);
      vap := Modelica.Media.Common.helmholtzToBoundaryProps(fv);
    end if;
    aux.dpT := if liq.d <> vap.d then (vap.s - liq.s) * liq.d * vap.d / (liq.d - vap.d) else Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.dptofT(aux.T);
    aux.h := liq.h + aux.x * (vap.h - liq.h);
    aux.rho := liq.d * vap.d / (vap.d + aux.x * (liq.d - vap.d));
    aux.cv := Modelica.Media.Common.cv2Phase(liq, vap, aux.x, aux.T, p);
    aux.cp := liq.cp + aux.x * (vap.cp - liq.cp);
    aux.pt := liq.pt + aux.x * (vap.pt - liq.pt);
    aux.pd := liq.pd + aux.x * (vap.pd - liq.pd);
  elseif aux.region == 5 then
    (aux.T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.tofps5(p = p, s = s, relds = 1.0e-7);
    assert(error == 0, "Error in inverse iteration of steam tables");
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g5(p, aux.T);
    aux.h := aux.R_s * aux.T * g.tau * g.gtau;
    aux.rho := p / (aux.R_s * aux.T * g.pi * g.gpi);
    aux.vt := aux.R_s / p * (g.pi * g.gpi - g.tau * g.pi * g.gtaupi);
    aux.vp := aux.R_s * aux.T / (p * p) * g.pi * g.pi * g.gpipi;
    aux.pt := -g.p / g.T * (g.gpi - g.tau * g.gtaupi) / (g.gpipi * g.pi);
    aux.pd := -g.R_s * g.T * g.gpi * g.gpi / g.gpipi;
    aux.cp := -aux.R_s * g.tau * g.tau * g.gtautau;
    aux.cv := aux.R_s * (-g.tau * g.tau * g.gtautau + (g.gpi - g.tau * g.gtaupi) * (g.gpi - g.tau * g.gtaupi) / g.gpipi);
    aux.dpT := -aux.vt / aux.vp;
    aux.x := 1.0;
  else
    assert(false, "Error in region computation of IF97 steam tables" + "(p = " + String(p) + ", s = " + String(s) + ")");
  end if;
end waterBaseProp_ps;

