  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if unknown";
  output Modelica.Media.Common.ExtraDerivatives dpro "Thermodynamic property collection";
protected
  Modelica.Units.SI.Density d "Density";
  Modelica.Units.SI.Temperature T "Temperature";
  Integer region "IF97 region";
  Integer error "Error flag";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.GibbsDerivs g "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
algorithm
  assert(phase == 1, "ExtraDerivs_ph: properties are not implemented in 2 phase region");
  region := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.region_ph(p = p, h = h, phase = phase);
  if region == 1 then
    T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph1(p, h);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, T);
    dpro := Modelica.Media.Common.gibbsToExtraDerivs(g);
  elseif region == 2 then
    T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tph2(p, h);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, T);
    dpro := Modelica.Media.Common.gibbsToExtraDerivs(g);
  elseif region == 3 then
    (d, T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.dtofph3(p = p, h = h, delp = 1.0e-7, delh = 1.0e-6);
    f := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d, T);
    dpro := Modelica.Media.Common.helmholtzToExtraDerivs(f);
  elseif region == 5 then
    // region assumed to be 5
    (T, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.tofph5(p = p, h = h, reldh = 1.0e-7);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g5(p, T);
    dpro := Modelica.Media.Common.gibbsToExtraDerivs(g);
  end if;
end extraDerivs_ph;

