modelica://Modelica.Media/region_ph:
Modelica.Media: region_ph (function)

Code:
function region_ph "Return the current region (valid values: 1,2,3,4,5) in IF97 for given pressure and specific enthalpy"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if not known";
  input Integer mode = 0 "Mode: 0 means check, otherwise assume region=mode";
  output Integer region "Region (valid values: 1,2,3,4,5) in IF97";
  // If mode is different from 0, no checking for the region is done and
  // the mode is assumed to be the correct region. This can be used to
  // implement e.g., water-only steam tables when mode == 1
protected
  Boolean hsubcrit;
  Modelica.Units.SI.Temperature Ttest;
  constant Real[5] n = data.n;
  Modelica.Units.SI.SpecificEnthalpy hl "Bubble enthalpy";
  Modelica.Units.SI.SpecificEnthalpy hv "Dew enthalpy";
algorithm
  if mode <> 0 then
    region := mode;
  else
    // check for regions 1, 2, 3 and 4
    hl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hl_p(p);
    hv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hv_p(p);
    if phase == 2 then
      region := 4;
    else
      // phase == 1 or 0, now check if we are in the legal area
      if p < triple.ptriple or p > data.PLIMIT1 or h < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hlowerofp1(p) or p < 10.0e6 and h > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hupperofp5(p) or p >= 10.0e6 and h > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hupperofp2(p) then
        // outside of valid range
        region := -1;
      else
        //region 5 and -1 check complete
        hsubcrit := h < data.HCRIT;
        // simple precheck: very simple if pressure < PLIMIT4A
        if p < data.PLIMIT4A then
          // we can never be in region 3, so test for others
          if hsubcrit then
            if phase == 1 then
              region := 1;
            else
              if h < Modelica.Media.Water.IF97_Utilities.BaseIF97.Isentropic.hofpT1(p, Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(p)) then
                region := 1;
              else
                region := 4;
              end if;
            end if;
            // external or internal phase check
          else
            if h > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hlowerofp5(p) then
              // check for region 5
              if p < data.PLIMIT5 and h < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hupperofp5(p) then
                region := 5;
              else
                region := -2;
                // pressure and specific enthalpy too high, but this should
              end if;
              // never happen
            else
              if phase == 1 then
                region := 2;
              else
                if h > Modelica.Media.Water.IF97_Utilities.BaseIF97.Isentropic.hofpT2(p, Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(p)) then
                  region := 2;
                else
                  region := 4;
                end if;
              end if;
              // external or internal phase check
            end if;
            // tests for region 2 or 5
          end if;
          // tests for sub or supercritical
        else
          // the pressure is over data.PLIMIT4A
          if hsubcrit then
            // region 1 or 3 or 4
            if h < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hupperofp1(p) then
              region := 1;
            else
              if h < hl or p > data.PCRIT then
                region := 3;
              else
                region := 4;
              end if;
            end if;
            // end of test for region 1, 3 or 4
          else
            // region 2, 3 or 4
            if h > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.hlowerofp2(p) then
              region := 2;
            else
              if h > hv or p > data.PCRIT then
                region := 3;
              else
                region := 4;
              end if;
            end if;
            // test for 2 and 3
          end if;
          // tests above PLIMIT4A
        end if;
        // above or below PLIMIT4A
      end if;
      // check for grand limits of p and h
    end if;
    // all tests with phase == 1
  end if;
  // mode was == 0
  // assert(region > 0,"IF97 function called outside the valid range!");
end region_ph;

modelica://Modelica.Media/region_ps:
Modelica.Media: region_ps (function)

Code:
function region_ps "Return the current region (valid values: 1,2,3,4,5) in IF97 for given pressure and specific entropy"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEntropy s "Specific entropy";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if unknown";
  input Integer mode = 0 "Mode: 0 means check, otherwise assume region=mode";
  output Integer region "Region (valid values: 1,2,3,4,5) in IF97";
  //  If mode is different from 0, no checking for the region is done and
  //    the mode is assumed to be the correct region. This can be used to
  //    implement e.g., water-only steam tables when mode == 1
protected
  Boolean ssubcrit;
  Modelica.Units.SI.Temperature Ttest;
  constant Real[5] n = data.n;
  Modelica.Units.SI.SpecificEntropy sl "Bubble entropy";
  Modelica.Units.SI.SpecificEntropy sv "Dew entropy";
algorithm
  if mode <> 0 then
    region := mode;
  else
    // check for regions 1, 2, 3, and 4
    sl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.sl_p(p);
    sv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.sv_p(p);
    // check all cases two-phase
    if phase == 2 or phase == 0 and s > sl and s < sv and p < data.PCRIT then
      region := 4;
    else
      // phase == 1
      region := 0;
      if p < triple.ptriple then
        region := -2;
      end if;
      if p > data.PLIMIT1 then
        region := -3;
      end if;
      if p < 10.0e6 and s > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.supperofp5(p) then
        region := -5;
      end if;
      if p >= 10.0e6 and s > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.supperofp2(p) then
        region := -6;
      end if;
      if region < 0 then
        assert(false, "Region computation from p and s failed: function called outside the legal region");
      else
        ssubcrit := s < data.SCRIT;
        // simple precheck: very simple if pressure < PLIMIT4A
        if p < data.PLIMIT4A then
          // we can never be in region 3, so test for 1 and 2
          if ssubcrit then
            region := 1;
          else
            if s > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.slowerofp5(p) then
              // check for region 5
              if p < data.PLIMIT5 and s < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.supperofp5(p) then
                region := 5;
              else
                region := -1;
                // pressure and specific entropy too high, should never happen!
              end if;
            else
              region := 2;
            end if;
            // tests for region 2 or 5
          end if;
          // tests for sub or supercritical
        else
          // the pressure is over data.PLIMIT4A
          if ssubcrit then
            // region 1 or 3
            if s < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.supperofp1(p) then
              region := 1;
            else
              if s < sl or p > data.PCRIT then
                region := 3;
              else
                region := 4;
              end if;
            end if;
            // test for region 1, 3 or 4
          else
            // region 2, 3 or 4
            if s > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.slowerofp2(p) then
              region := 2;
            else
              if s > sv or p > data.PCRIT then
                region := 3;
              else
                region := 4;
              end if;
            end if;
            // test for 2,3 and 4
          end if;
          // tests above PLIMIT4A
        end if;
        // above or below PLIMIT4A
      end if;
      // grand test for limits of p and s
    end if;
    // all tests with phase == 1
  end if;
  // mode was == 0
end region_ps;

modelica://Modelica.Media/region_pT:
Modelica.Media: region_pT (function)

Code:
function region_pT "Return the current region (valid values: 1,2,3,5) in IF97, given pressure and temperature"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature (K)";
  input Integer mode = 0 "Mode: 0 means check, otherwise assume region=mode";
  output Integer region "Region (valid values: 1,2,3,5) in IF97, region 4 is impossible!";
algorithm
  if mode <> 0 then
    region := mode;
  else
    if p < data.PLIMIT4A then
      //test for regions 1,2,5
      if T > data.TLIMIT2 then
        region := 5;
      elseif T > Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(p) then
        region := 2;
      else
        region := 1;
      end if;
    else
      //test for regions 1,2,3
      if T < data.TLIMIT1 then
        region := 1;
      elseif T < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.boundary23ofp(p) then
        region := 3;
      else
        region := 2;
      end if;
    end if;
  end if;
  // mode was == 0
end region_pT;

modelica://Modelica.Media/region_dT:
Modelica.Media: region_dT (function)

Code:
function region_dT "Return the current region (valid values: 1,2,3,4,5) in IF97, given density and temperature"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature (K)";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if not known";
  input Integer mode = 0 "Mode: 0 means check, otherwise assume region=mode";
  output Integer region "(valid values: 1,2,3,4,5) in IF97";
protected
  Boolean Tovercrit "Flag if overcritical temperature";
  Modelica.Units.SI.Pressure p23 "Pressure needed to know if region 2 or 3";
algorithm
  Tovercrit := T > data.TCRIT;
  if mode <> 0 then
    region := mode;
  else
    p23 := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.boundary23ofT(T);
    if T > data.TLIMIT2 then
      if d < 20.5655874106483 then
        // check for the density in the upper corner of validity!
        region := 5;
      else
        assert(false, "Out of valid region for IF97, pressure above region 5!");
      end if;
    elseif Tovercrit then
      //check for regions 1, 2 or 3
      if d > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.d2n(p23, T) and T > data.TLIMIT1 then
        region := 3;
      elseif T < data.TLIMIT1 then
        region := 1;
      else
        // d  < d2n(p23, T) and T > data.TLIMIT1
        region := 2;
      end if;
      // below critical, check for regions 1, 2, 3 or 4
    elseif d > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhol_T(T) then
      // either 1 or 3
      if T < data.TLIMIT1 then
        region := 1;
      else
        region := 3;
      end if;
    elseif d < Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhov_T(T) then
      // not liquid, not 2-phase, and not region 5, so either 2 or 3 or illegal
      if d > Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.d2n(p23, T) and T > data.TLIMIT1 then
        region := 3;
      else
        region := 2;
      end if;
    else
      region := 4;
    end if;
  end if;
end region_dT;

modelica://Modelica.Media/hvl_dp:
Modelica.Media: hvl_dp (function)

Code:
function hvl_dp "Derivative function for the specific enthalpy along the phase boundary"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Media.Common.IF97PhaseBoundaryProperties bpro "Property record";
  output Real dh_dp "Derivative of specific enthalpy along the phase boundary";
algorithm
  if bpro.region3boundary then
    dh_dp := (bpro.d * bpro.pd - bpro.T * bpro.pt + (bpro.T * bpro.pt * bpro.pt + bpro.d * bpro.d * bpro.pd * bpro.cv) / bpro.dpT) / (bpro.pd * bpro.d * bpro.d);
  else
    dh_dp := 1 / bpro.d - bpro.T * bpro.vt + bpro.cp / bpro.dpT;
  end if;
end hvl_dp;

