Code:
function gibbs "Gibbs function for region 1, 2 or 5: g(p,T,region)"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.Temperature T "Temperature (K)";
  input Integer region "IF97 region, 1, 2 or 5";
  output Real g "Dimensionless Gibbs function";
protected
  Modelica.Media.Common.GibbsDerivs gibbs "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
algorithm
  assert(region == 1 or region == 2 or region == 5, "IF97 medium function gibbs called with wrong region (= " + String(region) + ").\n" + "Only regions 1, 2 or 5 are possible");
  if region == 1 then
    gibbs := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, T);
  elseif region == 2 then
    gibbs := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, T);
  else
    gibbs := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g5(p, T);
  end if;
  g := gibbs.g;
end gibbs;

