protected
  Real[3] o "Vector of auxiliary variables";
algorithm
  assert(p > 0.0, "IF97 medium function g5pitau called with too low pressure\n" + "p = " + String(p) + " Pa <= " + String(triple.ptriple) + " Pa (triple point pressure)");
