function waterR4_ph "Water/Steam properties in region 4 of IAPWS/IF97 (two-phase)"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Pressure p "Pressure";
  input Modelica.Units.SI.SpecificEnthalpy h "Specific enthalpy";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_ph pro "Thermodynamic property collection";
protected
  Modelica.Units.SI.Density dl "Liquid density";
  Modelica.Units.SI.Density dv "Vapour density";
  Modelica.Media.Common.PhaseBoundaryProperties liq "Phase boundary property record";
  Modelica.Media.Common.PhaseBoundaryProperties vap "Phase boundary property record";
  Modelica.Media.Common.GibbsDerivs gl "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.GibbsDerivs gv "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs fl "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.HelmholtzDerivs fv "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Real x "Dryness fraction";
  Real dpT "Derivative of saturation curve";
algorithm
  pro.T := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.tsat(p);
  dpT := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.dptofT(pro.T);
  dl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhol_p_R4b(p);
  dv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhov_p_R4b(p);
  if p < data.PLIMIT4A then
    gl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, pro.T);
    gv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, pro.T);
    liq := Modelica.Media.Common.gibbsToBoundaryProps(gl);
    vap := Modelica.Media.Common.gibbsToBoundaryProps(gv);
  else
    fl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(dl, pro.T);
    fv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(dv, pro.T);
    liq := Modelica.Media.Common.helmholtzToBoundaryProps(fl);
    vap := Modelica.Media.Common.helmholtzToBoundaryProps(fv);
  end if;
  x := if vap.h <> liq.h then (h - liq.h) / (vap.h - liq.h) else 1.0;
  pro.d := liq.d * vap.d / (vap.d + x * (liq.d - vap.d));
  pro.u := x * vap.u + (1 - x) * liq.u;
  pro.s := x * vap.s + (1 - x) * liq.s;
  pro.cp := Modelica.Constants.inf;
  pro.cv := Modelica.Media.Common.cv2Phase(liq, vap, x, pro.T, p);
  pro.kappa := 1 / (pro.d * p) * dpT * dpT * pro.T / pro.cv;
  pro.a := Modelica.Constants.inf;
  pro.R_s := data.RH2O;
  pro.ddph := pro.d * (pro.d * pro.cv / dpT + 1.0) / (dpT * pro.T);
  pro.ddhp := -pro.d * pro.d / (dpT * pro.T);
end waterR4_ph;

