Modelica.Media: waterR4_dT (function)

Code:
function waterR4_dT "Water properties in region 4 as function of d and T"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_dT pro "Thermodynamic property collection";
protected
  Modelica.Units.SI.Density dl "Liquid density";
  Modelica.Units.SI.Density dv "Vapour density";
  Modelica.Media.Common.PhaseBoundaryProperties liq "Phase boundary property record";
  Modelica.Media.Common.PhaseBoundaryProperties vap "Phase boundary property record";
  Modelica.Media.Common.GibbsDerivs gl "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.GibbsDerivs gv "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs fl "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Modelica.Media.Common.HelmholtzDerivs fv "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Real x "Dryness fraction";
  Real dpT "Derivative of saturation curve";
algorithm
  pro.p := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.psat(T);
  dpT := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.dptofT(T);
  dl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhol_p_R4b(pro.p);
  dv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.rhov_p_R4b(pro.p);
  if pro.p < data.PLIMIT4A then
    gl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(pro.p, T);
    gv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(pro.p, T);
    liq := Modelica.Media.Common.gibbsToBoundaryProps(gl);
    vap := Modelica.Media.Common.gibbsToBoundaryProps(gv);
  else
    fl := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(dl, T);
    fv := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(dv, T);
    liq := Modelica.Media.Common.helmholtzToBoundaryProps(fl);
    vap := Modelica.Media.Common.helmholtzToBoundaryProps(fv);
  end if;
  x := if vap.d <> liq.d then (1 / d - 1 / liq.d) / (1 / vap.d - 1 / liq.d) else 1.0;
  pro.u := x * vap.u + (1 - x) * liq.u;
  pro.h := x * vap.h + (1 - x) * liq.h;
  pro.cp := Modelica.Constants.inf;
  pro.cv := Modelica.Media.Common.cv2Phase(liq, vap, x, T, pro.p);
  pro.kappa := 1 / (d * pro.p) * dpT * dpT * T / pro.cv;
  pro.a := Modelica.Constants.inf;
  pro.R_s := data.RH2O;
  pro.dudT := (pro.p - T * dpT) / (d * d);
end waterR4_dT;

