function water_dT "Calculate property record for dynamic simulation properties using d and T as dynamic states"
  extends Modelica.Icons.Function;
  input Modelica.Units.SI.Density d "Density";
  input Modelica.Units.SI.Temperature T "Temperature";
  input Integer phase = 0 "Phase: 2 for two-phase, 1 for one phase, 0 if unknown";
  output Modelica.Media.Common.ThermoFluidSpecial.ThermoProperties_dT pro "Property record for dynamic simulation";
protected
  Modelica.Units.SI.Pressure p "Pressure";
  Integer region(min = 1, max = 5) "IF97 region";
  Modelica.Media.Common.GibbsDerivs g "Dimensionless Gibbs function and derivatives w.r.t. pi and tau";
  Modelica.Media.Common.HelmholtzDerivs f "Dimensionless Helmholtz function and derivatives w.r.t. delta and tau";
  Integer error "Error flag";
algorithm
  region := Modelica.Media.Water.IF97_Utilities.BaseIF97.Regions.region_dT(d, T, phase);
  if region == 1 then
    (p, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.pofdt125(d = d, T = T, reldd = iter.DELD, region = 1);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g1(p, T);
    pro := Modelica.Media.Common.ThermoFluidSpecial.gibbsToProps_dT(g);
  elseif region == 2 then
    (p, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.pofdt125(d = d, T = T, reldd = iter.DELD, region = 2);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g2(p, T);
    pro := Modelica.Media.Common.ThermoFluidSpecial.gibbsToProps_dT(g);
  elseif region == 3 then
    f := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.f3(d, T);
    pro := Modelica.Media.Common.ThermoFluidSpecial.helmholtzToProps_dT(f);
  elseif region == 4 then
    pro := Modelica.Media.Water.IF97_Utilities.BaseIF97.TwoPhase.waterR4_dT(d = d, T = T);
  elseif region == 5 then
    (p, error) := Modelica.Media.Water.IF97_Utilities.BaseIF97.Inverses.pofdt125(d = d, T = T, reldd = iter.DELD, region = 5);
    g := Modelica.Media.Water.IF97_Utilities.BaseIF97.Basic.g5(p, T);
    pro := Modelica.Media.Common.ThermoFluidSpecial.gibbsToProps_dT(g);
  end if;
end water_dT;

