Code:
block Parallel "Parallel splitting of execution path (use component between two transitions)"
  parameter Integer nBranches(min = 1) = 2 "Number of parallel branches that are executed in parallel";
  Modelica.StateGraph.Interfaces.Step_in inPort ;
  Modelica.StateGraph.Interfaces.Step_out outPort ;
  Transition_in_forParallel join[nBranches] ;
  Transition_out_forParallel split[nBranches] ;
protected
  connector Transition_in_forParallel "Input port of a transition (has special icon for usage in component 'Parallel')"
  input Boolean available "= true, if step connected to the transition input is active" ;
  output Boolean reset "= true, if transition fires and the step connected to the transition input is deactivated" ;

  end Transition_in_forParallel;

  connector Transition_out_forParallel "Output port of a transition (has special icon for usage in component 'Parallel')"
  input Boolean occupied "= true, if step connected to the transition output is active" ;
  output Boolean set "= true, if transition fires and step connected to the transition output becomes active" ;

  end Transition_out_forParallel;
equation
  // Check connections of connectors
  assert(cardinality(inPort) == 1, "Connector inPort is not connected to exactly one other connector");
  assert(cardinality(outPort) == 1, "Connector outPort is not connected to exactly one other connector");
  for i in 1:nBranches loop
    assert(cardinality(split[i]) == 1, "Connector is not connected to exactly one other connector");
    assert(cardinality(join[i]) == 1, "Connector is not connected to exactly one other connector");
  end for;
  // Propagate flags between the connectors
  split.set = fill(inPort.set, nBranches);
  join.reset = fill(outPort.reset, nBranches);
  inPort.occupied = Modelica.Math.BooleanVectors.anyTrue(split.occupied);
  outPort.available = Modelica.Math.BooleanVectors.andTrue(join.available);

end Parallel;

modelica://Modelica.StateGraph/PartialCo:
Modelica.StateGraph: PartialCompositeStep (model)

Code:
partial model PartialCompositeStep "Superclass of a subgraph, i.e., a composite step that has internally a StateGraph"
  parameter Integer nSuspend = 1 "Number of suspend ports" ;
  parameter Integer nResume = 1 "Number of resume ports" ;
  /* The modification of stateGraphRoot is with respect to the "inner"
     definition, i.e., it is reported to all components that are
     within the CompositeStep
  */
  inner outer Modelica.StateGraph.Interfaces.CompositeStepState stateGraphRoot(suspend = Modelica.Math.BooleanVectors.anyTrue(suspend.reset) or outerState.subgraphStatePort.suspend, resume = Modelica.Math.BooleanVectors.anyTrue(resume.set) or outerState.subgraphStatePort.resume) "Communication port between the CompositeStep and the steps within the CompositeStep";
  output Boolean active "= true, if step is active, otherwise the step is not active";
  Modelica.StateGraph.Interfaces.Step_in inPort ;
  Modelica.StateGraph.Interfaces.Step_out outPort ;
  Modelica.StateGraph.Interfaces.CompositeStep_suspend suspend[nSuspend] ;
  Modelica.StateGraph.Interfaces.CompositeStep_resume resume[nResume] ;

  model OuterState "Block containing the port that is connected to the outer stateGraphRoot"
    Modelica.StateGraph.Interfaces.CompositeStepStatePort_in subgraphStatePort "Port connected to outer stateGraphRoot";
  input Boolean active;
  equation
  subgraphStatePort.activeSteps = if active then 1.0 else 0.0;
  end OuterState;

  OuterState outerState(active = active);
protected
  model InnerState
  outer Modelica.StateGraph.Interfaces.CompositeStepState stateGraphRoot;
  end InnerState;

  InnerState innerState;
  Boolean newActive "Value of active in the next iteration" ;
  Integer activeSteps "Number of active steps within the CompositeStep";
initial equation
  pre(newActive) = false;
  // pre(active) = pre(newActive);
equation
  // connect to outer CompositeStep
  connect(outerState.subgraphStatePort, stateGraphRoot.subgraphStatePort);
  // set active flag  of CompositeStep
  activeSteps = -integer(innerState.stateGraphRoot.subgraphStatePort.activeSteps);
  active = pre(newActive);
  /* The CompositeStep is active if
     - at least one step within the CompositeStep is active, and
     - the suspend transition does not fire, and
     - the suspend transition of a higher level CompositeStep does not fire or
     - no step within the CompositeStep is active, and
     - the resume transition fires or the resume transition of
       a higher level CompositeStep fires.
  */
  // newActive = activeSteps > 0 and not suspend.reset or resume.set;
  newActive = activeSteps > 0 and not Modelica.Math.BooleanVectors.anyTrue(suspend.reset) and not outerState.subgraphStatePort.suspend or Modelica.Math.BooleanVectors.anyTrue(resume.set) or outerState.subgraphStatePort.resume;
  // Report state to suspend and resume transitions
  for i in 1:nResume loop
    resume[i].occupied = if i == 1 then active else resume[i - 1].occupied or resume[i - 1].set;
  end for;
  for i in 1:nSuspend loop
    suspend[i].available = if i == 1 then active else suspend[i - 1].available and not suspend[i - 1].reset;
  end for;
  /* Check that connections to the connectors are correct
     and set appropriate defaults if necessary
  */
  for i in 1:nSuspend loop
    assert(cardinality(suspend[i]) <= 1, "Connector suspend[" + String(i) + "] of the CompositeStep is connected
to more than one transition");
    if cardinality(suspend[i]) == 0 then
      suspend[i].reset = false;
    end if;
  end for;
  for i in 1:nResume loop
    assert(cardinality(resume[i]) <= 1, "Connector resume[" + String(i) + "] of the CompositeStep is connected
to more than one transition");
    if cardinality(resume[i]) == 0 then
      resume[i].set = false;
    end if;
  end for;
  /* Zero sized connectors are not yet fully supported in
     Dymola. This requires to set the dimension of the connector
     to 1, if it should have a dimension of zero. This requires
     to set the connector variables to a default value in this case
  */
  if cardinality(inPort) < 2 then
    inPort.occupied = false;
    inPort.set = false;
  end if;
  if cardinality(outPort) < 2 then
    outPort.available = false;
    outPort.reset = false;
  end if;
  // Check inPort/outPort connections
  assert(cardinality(inPort) <= 2, "Connector inPort of the CompositeStep has more than 2 connections.
It should have only one connection from the outside to the
inPort and one connection to a step inside the CompositeStep.");
  assert(cardinality(outPort) <= 2, "Connector outPort of the CompositeStep has more than 2 connections.
It should have only one connection from the outPort to the
outside to the CompositeStep and one connection from a step
inside the CompositeStep to the outPort connector.");

end PartialCompositeStep;

