modelica://Modelica.StateGraph/PartialSt:
Modelica.StateGraph: PartialStep (block)

Code:
partial block PartialStep "Partial step with one input and one output transition port"
  parameter Integer nIn(min = 0) = 0 "Number of input connections" ;
  parameter Integer nOut(min = 0) = 0 "Number of output connections" ;
  /* localActive is introduced since component 'Step' has Boolean variable 'active'
     and component 'StepWithSignal' has connector instance 'active' defined
     and both components inherit from PartialStep
  */
  output Boolean localActive "= true, if step is active, otherwise the step is not active" ;
  Modelica.StateGraph.Interfaces.Step_in inPort[nIn] "Vector of step input connectors" ;
  Modelica.StateGraph.Interfaces.Step_out outPort[nOut] "Vector of step output connectors" ;
protected
  outer Modelica.StateGraph.Interfaces.CompositeStepState stateGraphRoot;

  model OuterStatePort
    Modelica.StateGraph.Interfaces.CompositeStepStatePort_in subgraphStatePort;
  input Boolean localActive;
  equation
  subgraphStatePort.activeSteps = if localActive then 1.0 else 0.0;
  end OuterStatePort;

  OuterStatePort outerStatePort(localActive = localActive);
  Boolean newActive "Value of active in the next iteration" ;
  Boolean oldActive "Value of active when CompositeStep was aborted";
initial equation
  pre(newActive) = pre(localActive);
  pre(oldActive) = pre(localActive);
equation
  connect(outerStatePort.subgraphStatePort, stateGraphRoot.subgraphStatePort);
  // Check that connections to the connector are correct
  for i in 1:nIn loop
    assert(cardinality(inPort[i]) <= 1, "Connector is connected to more than one transition (this is not allowed)");
  end for;
  for i in 1:nOut loop
    assert(cardinality(outPort[i]) <= 1, "Connector is connected to more than one transition (this is not allowed)");
  end for;
  // set active state
  localActive = pre(newActive);
  newActive = if outerStatePort.subgraphStatePort.resume then oldActive else (Modelica.Math.BooleanVectors.anyTrue(inPort.set) or localActive and not Modelica.Math.BooleanVectors.anyTrue(outPort.reset)) and not outerStatePort.subgraphStatePort.suspend;
  // Remember state for suspend action
  when outerStatePort.subgraphStatePort.suspend then
    oldActive = localActive;
  end when;
  // Report state to input and output transitions
  for i in 1:nIn loop
    inPort[i].occupied = if i == 1 then localActive else inPort[i - 1].occupied or inPort[i - 1].set;
  end for;
  for i in 1:nOut loop
    outPort[i].available = if i == 1 then localActive else outPort[i - 1].available and not outPort[i - 1].reset;
  end for;
  // Default setting, if an inPort or an outPort is not connected
  for i in 1:nIn loop
    if cardinality(inPort[i]) == 0 then
      inPort[i].set = false;
    end if;
  end for;
  for i in 1:nOut loop
    if cardinality(outPort[i]) == 0 then
      outPort[i].reset = false;
    end if;
  end for;
end PartialStep;

modelica://Modelica.StateGraph/PartialTr:
Modelica.StateGraph: PartialTransition (block)

Code:
partial block PartialTransition "Partial transition with input and output connections"
  input Boolean localCondition "= true, if transition may fire" ;
  parameter Boolean enableTimer = false "= true, if timer is enabled" ;
  parameter Modelica.Units.SI.Time waitTime(min = 0) = 0 "Wait time before transition fires" ;
  output Modelica.Units.SI.Time t "Actual waiting time (transition will fire when t > waitTime)";
  output Boolean enableFire "= true, if all firing conditions are true";
  output Boolean fire "= true, if transition fires" ;
  Modelica.StateGraph.Interfaces.Transition_in inPort "Vector of transition input connectors" ;
  Modelica.StateGraph.Interfaces.Transition_out outPort "Vector of transition output connectors" ;
protected
  discrete Modelica.Units.SI.Time t_start "Time instant at which the transition would fire, if waitTime would be zero";
  Real t_dummy;
initial equation
  pre(t_start) = time;
  pre(enableFire) = false;
equation
  assert(cardinality(inPort) == 1, "Connector inPort is not connected to exactly one other connector");
  assert(cardinality(outPort) == 1, "Connector outPort is not connected to exactly one other connector");
  // Handling of Timer
  if enableTimer then
    when enableFire then
      t_start = time;
    end when;
    t_dummy = time - t_start;
    t = if enableFire then t_dummy else 0;
    fire = enableFire and time >= t_start + waitTime;
  else
    when false then
      t_start = pre(t_start);
    end when;
    t_dummy = 0;
    t = 0;
    fire = enableFire;
  end if;
  // Determine fire setting and report it to the connected step
  enableFire = localCondition and inPort.available and not outPort.occupied;
  inPort.reset = fire;
  outPort.set = fire;
end PartialTransition;

