  output Modelica.Units.SI.Temperature T2(displayUnit = "degC") = openTank2.TTank "Temperature in tank 2";
  Modelica.Thermal.FluidHeatFlow.Components.OpenTank openTank1(ATank = 1, hTank = 1, useHeatPort = false, g = 10, level(fixed = true, start = 0.9), T0 = 313.15, T0fixed = true, pAmbient = 100000) ;
  Modelica.Thermal.FluidHeatFlow.Components.OpenTank openTank2(ATank = 1, hTank = 1, useHeatPort = false, g = 10, level(fixed = true, start = 0.1), T0 = 293.15, T0fixed = true, pAmbient = 100000) ;
  Modelica.Thermal.FluidHeatFlow.Components.Pipe pipe(m = 0, h_g = 0, T0 = 293.15, V_flowLaminar = 2, dpLaminar = 10, V_flowNominal = 4, dpNominal = 30) ;
equation
  connect(openTank1.flowPort, pipe.flowPort_a) ;
  connect(pipe.flowPort_b, openTank2.flowPort) ;

end TwoTanks;

modelica://Modelica.Thermal/TestCylinder:
Modelica.Thermal: TestCylinder (model)

Test of a system with 2 cylinders (with same volume):   
cylinder1: A = 0.1 m2, L=10. m, initial position of piston at s=L/2 cylinder2: A = 1.0 m2, L=1.0 m, initial position of piston at s=L/2  
 A force is applied that presses from 0.25 s to 0.50 s with 1 Nm on piston1. Due to the ratio of areas 10:1   
the force at piston2 is ten times the force at piston1 movement of piston1 is ten times the movement of piston2  
 At piston2 a mass is mounted which is moved and presses the springDamper. When the force at piston1 is removed, the springDamper pushes back the mass and a damped oscillation occurs.   
 Note: Take care of the initial conditions. The unstretched spring length is cylinder2.L/2, i.e. when piston2 is the middle of its cylinder the spring applies no force to the mass (and piston2).

Code:
model TestCylinder "Two cylinder system"
  extends Modelica.Icons.Example;
  output Modelica.Units.SI.Force f1 = -10 * cylinder1.f "10 x Force on piston 1";
  output Modelica.Units.SI.Position s1 = 0.1 * cylinder1.s "0.1 x Position of piston 1";
  output Modelica.Units.SI.Position s2 = cylinder2.s "Position of piston 2";
  output Modelica.Units.SI.Force f2 = -cylinder2.f "Force on piston 2";
  output Modelica.Units.SI.Force f = springDamper.f "Force of springDamper";
  Modelica.Blocks.Sources.CombiTimeTable combiTimeTable(table = [0, 0; 0.25, -1; 0.5, 0; 0.75, 0], smoothness = Modelica.Blocks.Types.Smoothness.ConstantSegments) ;
  Modelica.Mechanics.Translational.Sources.Force force ;
  Modelica.Thermal.FluidHeatFlow.Components.Cylinder cylinder1(A = 0.1, L = 10, s(fixed = true, start = cylinder1.L / 2), T0 = 313.15, T0fixed = true) ;
  Modelica.Thermal.FluidHeatFlow.Components.Cylinder cylinder2(T(fixed = true), A = 1, L = 1, T0 = 313.15, T0fixed = true) ;
  Modelica.Mechanics.Translational.Components.Mass mass(m = 1) ;
  Modelica.Mechanics.Translational.Components.SpringDamper springDamper(s_rel0 = cylinder2.L / 2, c = 100, s_rel(fixed = true, start = cylinder2.L / 2), v_rel(fixed = true, start = 0), d = 10) ;
  Modelica.Mechanics.Translational.Components.Fixed fixed ;
equation
  connect(cylinder1.flowPort, cylinder2.flowPort) ;
  connect(force.flange, cylinder1.flange) ;
  connect(combiTimeTable.y[1], force.f) ;
  connect(cylinder2.flange, mass.flange_a) ;
  connect(springDamper.flange_b, mass.flange_b) ;
  connect(springDamper.flange_a, fixed.flange) ;

end TestCylinder;

