Code:
function term "Evaluate term of an expression"
  extends Modelica.Icons.Function;
  input String string;
  input Integer startIndex;
  input String message = "";
  output Real result;
  output Integer nextIndex;
protected
  Real result2;
  Boolean scanning = true;
  String opString;
algorithm
  // scan for "primary * primary" or "primary / primary"
  (result, nextIndex) := Modelica.Utilities.Examples.expression.primary(string, startIndex, message);
  while scanning loop
    (opString, nextIndex) := Modelica.Utilities.Strings.scanDelimiter(string, nextIndex, {"*", "/", ""}, message);
    if opString == "" then
      scanning := false;
    else
      (result2, nextIndex) := Modelica.Utilities.Examples.expression.primary(string, nextIndex, message);
      result := if opString == "*" then result * result2 else result / result2;
    end if;
  end while;
end term;

