Code:
function primary "Evaluate primary of an expression"
  extends Modelica.Icons.Function;
  input String string;
  input Integer startIndex;
  input String message = "";
  output Real result;
  output Integer nextIndex;
protected
  Modelica.Utilities.Types.TokenValue token;
  Real result2;
  String delimiter;
  String functionName;
  Real pi = Constants.pi;
algorithm
  (token, nextIndex) := Modelica.Utilities.Strings.scanToken(string, startIndex, unsigned = true);
  if token.tokenType == Modelica.Utilities.Types.TokenType.DelimiterToken and token.string == "(" then
    (result, nextIndex) := Modelica.Utilities.Examples.expression(string, nextIndex, message);
    (delimiter, nextIndex) := Modelica.Utilities.Strings.scanDelimiter(string, nextIndex, {")"}, message);
  elseif token.tokenType == Modelica.Utilities.Types.TokenType.RealToken then
    result := token.real;
  elseif token.tokenType == Modelica.Utilities.Types.TokenType.IntegerToken then
    result := token.integer;
  elseif token.tokenType == Modelica.Utilities.Types.TokenType.IdentifierToken then
    if token.string == "pi" then
      result := pi;
    else
      functionName := token.string;
      (delimiter, nextIndex) := Modelica.Utilities.Strings.scanDelimiter(string, nextIndex, {"("}, message);
      (result, nextIndex) := Modelica.Utilities.Examples.expression(string, nextIndex, message);
      (delimiter, nextIndex) := Modelica.Utilities.Strings.scanDelimiter(string, nextIndex, {")"}, message);
      if functionName == "sin" then
        result := Modelica.Math.sin(result);
      elseif functionName == "cos" then
        result := Modelica.Math.cos(result);
      elseif functionName == "tan" then
        result := Modelica.Math.tan(result);
      elseif functionName == "sqrt" then
        if result < 0.0 then
          Modelica.Utilities.Strings.syntaxError(string, startIndex, "Argument of call \"sqrt(" + String(result) + ")\" is negative.\n" + "Imaginary numbers are not supported by the calculator.\n" + message);
        end if;
        result := sqrt(result);
      elseif functionName == "asin" then
        result := Modelica.Math.asin(result);
      elseif functionName == "acos" then
        result := Modelica.Math.acos(result);
      elseif functionName == "atan" then
        result := Modelica.Math.atan(result);
      elseif functionName == "exp" then
        result := Modelica.Math.exp(result);
      elseif functionName == "log" then
        if result <= 0.0 then
          Modelica.Utilities.Strings.syntaxError(string, startIndex, "Argument of call \"log(" + String(result) + ")\" is not positive.\n" + message);
        end if;
        result := Modelica.Math.log(result);
      else
        Modelica.Utilities.Strings.syntaxError(string, startIndex, "Function \"" + functionName + "\" is unknown (not supported)\n" + message);
      end if;
    end if;
  else
    Modelica.Utilities.Strings.syntaxError(string, startIndex, "Invalid primary of expression.\n" + message);
  end if;
end primary;

