  impure function sortDirectory "Sort directory in directories and files with alphabetic order"
  extends Modelica.Icons.Function;
  input String directory "Directory that was read (including a trailing '/')";
  input String names[:] "File and directory names of a directory in any order";
  output String orderedNames[size(names, 1)] "Names of directories followed by names of files";
  output Integer nDirectories "The first nDirectories entries in orderedNames are directories";
  protected
  Integer nEntries = size(names, 1);
  Integer nFiles;
  Integer lenDirectory = Modelica.Utilities.Strings.length(directory);
  String directory2;
  algorithm
  // Construct directory with a trailing "/"
  directory2 := if Modelica.Utilities.Strings.substring(directory, lenDirectory, lenDirectory) == "/" then directory else directory + "/";
  // Distinguish directories and files
  nDirectories := 0;
  nFiles := 0;
  for i in 1:nEntries loop
    if Modelica.Utilities.Internal.FileSystem.stat(directory2 + names[i]) == Modelica.Utilities.Types.FileType.Directory then
      nDirectories := nDirectories + 1;
      orderedNames[nDirectories] := names[i];
    else
      nFiles := nFiles + 1;
      orderedNames[nEntries - nFiles + 1] := names[i];
    end if;
  end for;
  // Sort files and directories alphabetically
  if nDirectories > 0 then
    orderedNames[1:nDirectories] := Modelica.Utilities.Strings.sort(orderedNames[1:nDirectories], caseSensitive = false);
  end if;
  if nFiles > 0 then
    orderedNames[nDirectories + 1:nEntries] := Modelica.Utilities.Strings.sort(orderedNames[nDirectories + 1:nEntries], caseSensitive = false);
  end if;
  end sortDirectory;

