    files := Modelica.Utilities.Internal.FileSystem.readDirectory(directoryName, nEntries);
    (files, nDirectories) := sortDirectory(directoryName, files);
    // List directories
    if nDirectories > 0 then
        Modelica.Utilities.Streams.print("  Subdirectories:");
      for i in 1:nDirectories loop
          Modelica.Utilities.Streams.print("    " + files[i]);
      end for;
        Modelica.Utilities.Streams.print(" ");
    end if;
    // List files
    if nDirectories < nEntries then
        Modelica.Utilities.Streams.print("  Files:");
      for i in nDirectories + 1:nEntries loop
          Modelica.Utilities.Streams.print("    " + files[i]);
      end for;
    end if;
  else
      Modelica.Utilities.Streams.print("... Directory\"" + directoryName + "\" is empty");
  end if;
  end listDirectory;
