impure function copy "Generate a copy of a file or of a directory"
  extends Modelica.Icons.Function;
  input String oldName "Name of file or directory to be copied";
  input String newName "Name of copy of the file or of the directory";
  input Boolean replace = false "= true, if an existing file may be replaced by the required copy";
  //..............................................................
protected
  impure function copyDirectory "Copy a directory"
  extends Modelica.Icons.Function;
  input String oldName "Old directory name without trailing '/'; existence is guaranteed";
  input String newName "New directory name without trailing '/'; directory was already created";
  input Boolean replace "= true, if an existing newName may be replaced";
  algorithm
  copyDirectoryContents(Modelica.Utilities.Internal.FileSystem.readDirectory(oldName, Modelica.Utilities.Internal.FileSystem.getNumberOfFiles(oldName)), oldName, newName, replace);
  end copyDirectory;

  impure function copyDirectoryContents
  extends Modelica.Icons.Function;
  input String oldNames[:];
  input String oldName;
  input String newName;
  input Boolean replace;
  protected
  String oldName_i;
  String newName_i;
  algorithm
  for i in 1:size(oldNames, 1) loop
    oldName_i := oldName + "/" + oldNames[i];
    newName_i := newName + "/" + oldNames[i];
    Files.copy(oldName_i, newName_i, replace);
  end for;
  end copyDirectoryContents;

  //..............................................................
  Integer lenOldName = Modelica.Utilities.Strings.length(oldName);
  Integer lenNewName = Modelica.Utilities.Strings.length(newName);
  String oldName2 = if Modelica.Utilities.Strings.substring(oldName, lenOldName, lenOldName) == "/" then Modelica.Utilities.Strings.substring(oldName, 1, lenOldName - 1) else oldName;
  String newName2 = if Modelica.Utilities.Strings.substring(newName, lenNewName, lenNewName) == "/" then Modelica.Utilities.Strings.substring(newName, 1, lenNewName - 1) else newName;
  Modelica.Utilities.Types.FileType oldFileType = Modelica.Utilities.Internal.FileSystem.stat(oldName2);
  Modelica.Utilities.Types.FileType newFileType;
algorithm
  if oldFileType == Modelica.Utilities.Types.FileType.NoFile then
    Modelica.Utilities.Streams.error("It is not possible to copy the file or directory\n" + "\"" + oldName2 + "\" because it does not exist.");
  elseif oldFileType == Modelica.Utilities.Types.FileType.Directory then
    newFileType := Modelica.Utilities.Internal.FileSystem.stat(newName2);
    if newFileType == Modelica.Utilities.Types.FileType.NoFile then
      Modelica.Utilities.Files.createDirectory(newName2);
    elseif newFileType == Modelica.Utilities.Types.FileType.RegularFile or newFileType == Modelica.Utilities.Types.FileType.SpecialFile then
      if replace then
        Modelica.Utilities.Files.removeFile(newName2);
        Modelica.Utilities.Files.createDirectory(newName2);
      else
        Modelica.Utilities.Streams.error("Directory \"" + oldName2 + "\" should be copied to\n" + "\"" + newName2 + "\" which is an existing file.\n" + "Since argument replace=false, this is not allowed");
      end if;
    end if;
    copyDirectory(oldName2, newName2, replace);
  else
    // regular or special file
    if replace then
      Modelica.Utilities.Files.removeFile(newName2);
    else
      Modelica.Utilities.Files.assertNew(newName2, "File \"" + oldName2 + "\" should be copied or moved to\n" + "\"" + newName2 + "\" which is an existing file or directory.\n" + "Since argument replace=false, this is not allowed");
    end if;
    Modelica.Utilities.Internal.FileSystem.copyFile(oldName2, newName2);
  end if;

