modelica://Modelica.Utilities/createDire:
Modelica.Utilities: createDirectory (function)

Syntax    Files. createDirectory (directoryName);    Description  
 Creates directory "directoryName". If this directory already exists, the function call is ignored. If several directories in "directoryName" do not exist, all of them are created. For example, assume that directory "E:/test1" exists and that directory "E:/test1/test2/test3" shall be created. In this case the directories "test2" in "test1" and "test3" in "test2" are created.   
 This function is silent, i.e., it does not print a message. In case of error (e.g., "directoryName" is an existing regular file), an assert is triggered.

Code:
impure function createDirectory "Create directory (if directory already exists, ignore call)"
  extends Modelica.Icons.Function;
  input String directoryName "Name of directory to be created (if present, ignore call)";
  //..............................................................
protected
  impure function existDirectory "Inquire whether directory exists; if present and not a directory, trigger an error"
  extends Modelica.Icons.Function;
  input String directoryName;
  output Boolean exists "= true, if directory exists";
  protected
    Modelica.Utilities.Types.FileType fileType = Modelica.Utilities.Internal.FileSystem.stat(directoryName);
  algorithm
  if fileType == Modelica.Utilities.Types.FileType.RegularFile or fileType == Modelica.Utilities.Types.FileType.SpecialFile then
      Modelica.Utilities.Streams.error("Directory \"" + directoryName + "\" cannot be created\n" + "because this is an existing file.");
  elseif fileType == Modelica.Utilities.Types.FileType.Directory then
    exists := true;
  else
    exists := false;
  end if;
  end existDirectory;

  function assertCorrectIndex "Print error, if index to last essential character in directory is wrong"
  extends Modelica.Icons.Function;
  input Integer index "Index must be > 0";
  input String directoryName "Directory name for error message";
  algorithm
  if index < 1 then
      Modelica.Utilities.Streams.error("It is not possible to create the directory\n" + "\"" + directoryName + "\"\n" + "because this directory name is not valid");
  end if;
  end assertCorrectIndex;

  //..............................................................
  String fullName;
  Integer index;
  Integer oldIndex;
  Integer lastIndex;
  Boolean found;
  Boolean finished;
  Integer nDirectories = 0 "Number of directories that need to be generated";
algorithm
  // Ignore call, if directory exists
  if not existDirectory(directoryName) then
    fullName := Modelica.Utilities.Files.fullPathName(directoryName);
    // Remove a trailing "/"
    index := Modelica.Utilities.Strings.length(fullName);
    if Modelica.Utilities.Strings.substring(fullName, index, index) == "/" then
      index := index - 1;
      assertCorrectIndex(index, fullName);
    end if;
    lastIndex := index;
    fullName := Modelica.Utilities.Strings.substring(fullName, 1, index);
    // Search upper directories until a directory is found that exists
    // ??? check the following while loop later, if also cases such as
    //  "c:/", "c:", "//name" are handled correctly ???
    found := false;
    while not found loop
      oldIndex := index;
      index := Modelica.Utilities.Strings.findLast(fullName, "/", startIndex = index);
      if index == 0 then
        index := oldIndex;
        found := true;
      else
        index := index - 1;
        assertCorrectIndex(index, fullName);
        found := existDirectory(Modelica.Utilities.Strings.substring(fullName, 1, index));
      end if;
    end while;
    index := oldIndex;
    // Create directories
    finished := false;
    while not finished loop
      Modelica.Utilities.Internal.FileSystem.mkdir(Modelica.Utilities.Strings.substring(fullName, 1, index));
      if index >= lastIndex then
        finished := true;
      elseif index < lastIndex then
        index := Modelica.Utilities.Strings.find(fullName, "/", startIndex = index + 2);
        if index == 0 then
          index := lastIndex;
        end if;
      end if;
    end while;
  end if;

</pre></blockquote>
<h4>Description</h4>
<p>
Creates directory \"directoryName\". If this directory already exists,
the function call is ignored. If several directories in \"directoryName\"
do not exist, all of them are created. For example, assume
that directory \"E:/test1\" exists and that directory
\"E:/test1/test2/test3\" shall be created. In this case
the directories \"test2\" in \"test1\" and \"test3\" in \"test2\"
are created.
</p>
<p>
This function is silent, i.e., it does not print a message.
In case of error (e.g., \"directoryName\" is an existing regular
file), an assert is triggered.
</p>
</html>"));
end createDirectory;

