modelica://Modelica.Utilities/splitPathN:
Modelica.Utilities: splitPathName (function)

Syntax    (directory, name, extension) = Files. splitPathName (pathName);    Description  
 Function splitPathName (..) splits a path name into its parts.    Example    (directory, name, extension) = Files.splitPathName("C:/user/test/input.txt") -> directory = "C:/user/test/" name = "input" extension = ".txt"

Code:
function splitPathName "Split path name in directory, file name kernel, file name extension"
  extends Modelica.Icons.Function;
  input String pathName "Absolute or relative file or directory name";
  output String directory "Name of the directory including a trailing '/'";
  output String name "Name of the file without the extension";
  output String extension "Extension of the file name. Starts with '.'";
protected
  Integer lenPath = Modelica.Utilities.Strings.length(pathName);
  Integer i = lenPath;
  Integer indexDot = 0;
  Integer indexSlash = 0;
  String c;
algorithm
  while i >= 1 loop
    c := Modelica.Utilities.Strings.substring(pathName, i, i);
    if c == "." then
      indexDot := i;
      i := 0;
    elseif c == "/" then
      indexSlash := i;
      i := 0;
    else
      i := i - 1;
    end if;
  end while;
  if indexSlash == lenPath then
    directory := pathName;
    name := "";
    extension := "";
  elseif indexDot > 0 then
    indexSlash := Modelica.Utilities.Strings.findLast(pathName, "/", startIndex = indexDot - 1);
    if indexSlash == 0 then
      directory := "";
      name := Modelica.Utilities.Strings.substring(pathName, 1, indexDot - 1);
    else
      directory := Modelica.Utilities.Strings.substring(pathName, 1, indexSlash);
      name := Modelica.Utilities.Strings.substring(pathName, indexSlash + 1, indexDot - 1);
    end if;
    extension := Modelica.Utilities.Strings.substring(pathName, indexDot, lenPath);
  else
    extension := "";
    if indexSlash > 0 then
      directory := Modelica.Utilities.Strings.substring(pathName, 1, indexSlash);
      name := Modelica.Utilities.Strings.substring(pathName, indexSlash + 1, lenPath);
    else
      directory := "";
      name := pathName;
    end if;
  end if;

</pre></blockquote>
<h4>Description</h4>
<p>
Function <strong>splitPathName</strong>(..) splits a path name into its parts.
</p>
<h4>Example</h4>
<blockquote><pre>
(directory, name, extension) = Files.splitPathName(\"C:/user/test/input.txt\")

-> directory = \"C:/user/test/\"
   name      = \"input\"
   extension = \".txt\"
</pre></blockquote>
</html>"));
end splitPathName;

