modelica://Modelica.Utilities/count:
Modelica.Utilities: count (function)

Syntax    Strings. count (string, searchString) Strings. count (string, searchString, startIndex=1, caseSensitive=true)    Description  
 Returns the number of non-overlapping occurrences of string "searchString" in "string". The search is started at index "startIndex" (default = 1). If the optional argument "caseSensitive" is false, for the counting it does not matter whether a letter is upper or lower case.

Code:
function count "Count the number of non-overlapping occurrences of a string"
  extends Modelica.Icons.Function;
  input String string "String that is analyzed";
  input String searchString "String that is searched for in string";
  input Integer startIndex(min = 1) = 1 "Start search at index startIndex";
  input Boolean caseSensitive = true "= false, if lower and upper case are ignored for count";
  output Integer result "Number of occurrences of 'searchString' in 'string'";
protected
  Integer lenSearchString = Modelica.Utilities.Strings.length(searchString);
  Integer i = startIndex;
algorithm
  result := 0;
  while i <> 0 loop
    i := Modelica.Utilities.Strings.find(string, searchString, i, caseSensitive);
    if i > 0 then
      result := result + 1;
      i := i + lenSearchString;
    end if;
  end while;

end count;

modelica://Modelica.Utilities/find:
Modelica.Utilities: find (function)

Syntax    index = Strings. find (string, searchString); index = Strings. find (string, searchString, startIndex=1, caseSensitive=true);    Description  
 Finds first occurrence of "searchString" within "string" and return the corresponding index. Start search at index "startIndex" (default = 1). If the optional argument "caseSensitive" is false, lower and upper case are ignored for the search. If "searchString" is not found, a value of "0" is returned.

Code:
function find "Find first occurrence of a string within another string"
  extends Modelica.Icons.Function;
  input String string "String that is analyzed";
  input String searchString "String that is searched for in string";
  input Integer startIndex(min = 1) = 1 "Start search at index startIndex";
  input Boolean caseSensitive = true "= false, if lower and upper case are ignored for the search";
  output Integer index "Index of the beginning of the first occurrence of 'searchString' within 'string', or zero if not present";
protected
  Integer lengthSearchString = Modelica.Utilities.Strings.length(searchString);
  Integer len = lengthSearchString - 1;
  Integer i = startIndex;
  Integer i_max = Modelica.Utilities.Strings.length(string) - lengthSearchString + 1;
algorithm
  index := 0;
  while i <= i_max loop
    if Modelica.Utilities.Strings.isEqual(Modelica.Utilities.Strings.substring(string, i, i + len), searchString, caseSensitive) then
      index := i;
      i := i_max + 1;
    else
      i := i + 1;
