Syntax    Strings. replace (string, searchString, replaceString); Strings. replace (string, searchString, replaceString, startIndex=1, replaceAll=true, caseSensitive=true);    Description  
 Search in "string" for "searchString" and replace the found substring by "replaceString".   
The search starts at the first character of "string", or at character position "startIndex", if this optional argument is provided. If the optional argument "replaceAll" is true (default), all occurrences of "searchString" are replaced. If the argument is false , only the first occurrence is replaced. The search for "searchString" distinguishes upper and lower case letters. If the optional argument "caseSensitive" is  false , the search ignores whether letters are upper or lower case.  
 The function returns the "string" with the performed replacements.

Code:
function replace "Replace non-overlapping occurrences of a string from left to right"
  extends Modelica.Icons.Function;
  input String string "String to be modified";
  input String searchString "Replace non-overlapping occurrences of 'searchString' in 'string' with 'replaceString'";
  input String replaceString "String that replaces 'searchString' in 'string'";
  input Integer startIndex = 1 "Start search at index startIndex";
  input Boolean replaceAll = true "= false, if only the first occurrence is replaced, otherwise all occurrences";
  input Boolean caseSensitive = true "= false, if lower and upper case are ignored when searching for searchString";
  output String result "Resultant string of replacement operation";
protected
  Integer lenString = Modelica.Utilities.Strings.length(string);
  Integer lenSearchString = Modelica.Utilities.Strings.length(searchString);
  Integer i = startIndex;
  Integer i_found;
algorithm
  result := if startIndex == 1 then "" else Modelica.Utilities.Strings.substring(string, 1, startIndex - 1);
  while i > 0 loop
    i_found := Modelica.Utilities.Strings.find(string, searchString, i, caseSensitive);
    if i_found > 0 then
      result := if i_found == 1 then replaceString else result + (if i_found - 1 < i then "" else Modelica.Utilities.Strings.substring(string, i, i_found - 1)) + replaceString;
      i := i_found + lenSearchString;
      if i > lenString then
        i := 0;
      elseif not replaceAll then
        result := result + Modelica.Utilities.Strings.substring(string, i, lenString);
        i := 0;
      end if;
    elseif lenString < i then
      i := 0;
    else
      result := result + Modelica.Utilities.Strings.substring(string, i, lenString);
      i := 0;
    end if;
  end while;

Strings.<strong>replace</strong>(string, searchString, replaceString,
                startIndex=1, replaceAll=true, caseSensitive=true);
